-- Petőfi Sándor összes költeményei, 1/5. rész (forrás: MEK-01006, nem jogvédett)
insert into public.classic_poems (key,poet_id,title,body,excerpt,written,year,section,themes,seasons,is_excerpt,sort,source) values
('petofi-1838-183801-01','petofi','Búcsúzás','Immár kész koszorúnk, melyet tíz hónapig izzadt
Arccal, gyenge eszünknek gyüjtve diszét, fonogattunk
A zöld Pindus alatt, a nyájas Múzsasereg közt!
Ennyit, nagytudományu atyák, volt gyüjteni képes
S nem többet iparunk! - Noha édes múzsai körben
Töltni időt, noha Pallas kertjében gyönyörűebb
Illatozásu virágok kelnek, mint a vadonynak
Puszta helyén, fárasztóbb mégis a pindusi ösvény,
Vonzóbb drága szülőnk s kedves rokonink köre, mintsem
Hogy kis időre szivünk azt kész nem volna kerülni.
Számüzetett Naso, ki tanítál a Helikonra
Törni utat s akadályt meggyőzni karunk panaszid már
Nem veszi a tanodába, se Nepos hősei éltét,
Ki mutatá híven, mennyit vittek vala véghez
Graecia nagy fiai s Karthágó győztesi, mely jót
S mely rosszat tettek, mi csatákba'' valának
És hogy haltanak el. Mai ünnep válni megenged
Tőletek s a tanulástól, míg belekezdeni kell majd.
Nagyságos báró, tanodánk kegyes elnöke s atyja!
S ti tisztelt figyelők, ti nagytudományu atyáink!
Volt türedelmetökért szívünk mit nektek adózzon,
Hogy minket hallgatni nem untatok el, rebegőket?
Gonditokért hálás kebelünk forró köszönetjét
És a csekély szálkú koszorúnkat kegybe vegyétek!
Hosszú éltetöket soha gond, bú, baj ne epessze,
Létünk és tanodánk folyton kegyetöknek örüljön!
Drága tanító úr, ki fáradhatatlan iparral
A tudományokban jártassá tenni akartál
Bennünk'', vedd végső együttlétünkben ezen pár
Búcsúszót, mert elválunk sok időre tetőled!
S ti kedves helyek, ahol számt''lanszor mulatoztunk
Vagy nagy körbe'' leülve, vagy a labdát veregetve
És kapkodva, vagy ugrándozva, vagy édes örömben
Víg dallokra fakadva, ezentúl csend üli kedvelt
Tájitokat, már-már elhagyni fogunk mi ezennel!
S végre deáktársim, kik nem köz s renyhe erővel
Jártátok velem a tudomány ösvényit: ez óra
Tőletek elválaszt, szétoszlunk mostan, egy erre,
Másik amárra megyen születése helyére, holottan
Hány örömek várják édes szüleinknek ölében!
Majd amidőn a sors keze minket messzire széleszt
Egymástól, midön itt nem lelt örömökbe förödve
Lészünk szűlőink hajlékában, midön ekkép
Szólhat már ajkunk: ti komor gondok, nem adunk most
Helyt főnkben néktek, kipihenni fogunk sok
Munkáinknak utána, pihenni, nem tanodával
Gondolkodni! Elég volt tíz hó arra! - O akkor
Még egyszer gondoljunk itten lelt öröminkre,
Gondoljuk, mennyit fáradtunk s izzadozánk itt,
A tudományoknak kimeríthetetlen ösvényén.
S most társim! miután végét már érte a munka,
Amely tíz hóig szűnetlen foly vala köztünk,
Jóisten veletek! Tanodánkat hagyjuk örömmel
És szaporán édes szüleink kebelébe siessünk!','Immár kész koszorúnk, melyet tíz hónapig izzadt
Arccal, gyenge eszünknek gyüjtve diszét, fonogattunk
A zöld Pindus alatt, a nyájas Múzsasereg közt!
Ennyit, nagytudományu atyák, volt gyüjteni képes','Aszód, 1838. június',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,0,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-02','petofi','A hűtelenhez','Esküszegte lyánka! emlékezzél
Arra, amidőn: "Ah meg ne vessél",
Igy imádva téged kértelek;
"Légy kegyelmes én irántam, s szíved
Add nekem, ki csak tenéked híved
Voltam, és leszek, míg létezek."

Akkoron kérő keblemre dűlve,
S a szerelm'' tüzétől fölhevűlve,
Ezt rebegték csalfa ajkaid:
"Hő szivem tiéd csak, drága lélek!
Esküszöm, hogy csak tenéked élek;
Szünjenek könyűid, bánatid."

Én ezáltal istenülve lettem,
És keserves sorsom elfeledtem,
Emma! gyönge karjaid között.
Édenek nyilának én előttem,
Nem borultak fellegek fölöttem,
Tőlem a bú mind elköltözött.

Ámde mily rövid volt boldogságom,
Mily korán eltűne mennyországom,
Én, ah, nem gondoltam volna azt!
Estem édenből nagy pusztaságra,
És juték keserves árvaságra,
Marja a bú szívem, és hervaszt.

Hő imádód s kedvelőd elhagytad,
Szívedet te ismét másnak adtad,
Engem elfeledve, csalfa lény!
Jól van! én lemondok mindenről már,
Engemet kietlen puszta hely vár
Éjszak hófödözte bús ölén.

Isten véled hát örökre, édes
Tárgya hő szivemnek, ah negédes
Csalfa Emma! isten véled hát!
Majd ha egykor értem, szinte árva,
Eljösz, éjszaknak havát bejárva,
Megleled hű Múzsafid porát.','Esküszegte lyánka! emlékezzél
Arra, amidőn: "Ah meg ne vessél",
Igy imádva téged kértelek;
"Légy kegyelmes én irántam, s szíved','Selmec, 1838. október 26.',null,'Ifjúkori költemények',array['Szerelem','Természet']::text[],'{}'::text[],false,1,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-03','petofi','Szeberényi Lajos emlékkönyvébe','Kegyetlen a végzet; nem hagy sok időig örűlni
Minket együttlétünk édeni napjainak.
Ámde az a földnek bármely részére ragadhat,
Érted ezen kebel ég, s lészen örökre hived.','Kegyetlen a végzet; nem hagy sok időig örűlni
Minket együttlétünk édeni napjainak.
Ámde az a földnek bármely részére ragadhat,
Érted ezen kebel ég, s lészen örökre hived.','Selmec, 1839. január 19.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,2,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-04','petofi','Epigramm','Rákosnak szomorú mezején járván, magyar, hallod
Fái között a szél mily keseregve nyögel?
Oh nem szél nyögel ott, ősid fölisteni lelke
Sír unokáinak elkorcsosodása fölött!','Rákosnak szomorú mezején járván, magyar, hallod
Fái között a szél mily keseregve nyögel?
Oh nem szél nyögel ott, ősid fölisteni lelke
Sír unokáinak elkorcsosodása fölött!','Rákos, 1839. április 30.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,3,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-05','petofi','Róza','Szende szerény ibolyák völgyén füzögetve bokrétát,
Szökdele berkének kedvesem árnyai alatt.
Jött és látta Eos bájait; irigyelve pirúla,
S a fák lombi fölé könnyeket ejtve futott.','Szende szerény ibolyák völgyén füzögetve bokrétát,
Szökdele berkének kedvesem árnyai alatt.
Jött és látta Eos bájait; irigyelve pirúla,
S a fák lombi fölé könnyeket ejtve futott.','Ostfiasszonyfa, 1839. május 29.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,4,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-06','petofi','Epigramm','Hasztalanúl vágyasz, vad sors, kínozni. Nem érzem:
Nincs szivem. A haza s a lányka s barátnak adám.','Hasztalanúl vágyasz, vad sors, kínozni. Nem érzem:
Nincs szivem. A haza s a lányka s barátnak adám.','Ostfiasszonyfa, 1839. június 4.',null,'Ifjúkori költemények',array['Haza']::text[],'{}'::text[],false,5,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-07','petofi','Petrics somához','Bűvölőn hangzik dalod, óh barátom
Petrics, és e szű öröm-érzeteknek
Tengerében leng, s feledem keservem,
Hogyha te zengesz.

Zengj! - Ha dús volnék, aranyat fizetnék
Bőven én néked dalodért; de sorsom
Nem kegyel. Csak vers, mit az árva ifju
Nyerhete tőle.

Hát legyen versem dijad és jutalmad,
S majd ha a végzet kiszakaszt karodból
Engem; olvasván ezeket, lebegjen
Dalma eszedben.','Bűvölőn hangzik dalod, óh barátom
Petrics, és e szű öröm-érzeteknek
Tengerében leng, s feledem keservem,
Hogyha te zengesz.','Ostfiasszonyfa, 1839. szeptember 4.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,6,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-08','petofi','Elválás','Itt a bucsúperc: válok. - Nem szabad!
Leomlok, a világ kereng velem!
E szenvedés, e szörnyü kín alatt
Hogy nem repedsz meg, égő kebelem?

Nem, én nem hordom többé terhemet,
Habár egy élet rajta függene,
Válj lángszavakká, titkos érezet,
Te szívem pokla, szívem édene.

S ha szólanék is, mit remélhetek?
A sors irántam oly vad, oly kemény;
Oh kárhozat, oh gyilkos képzetek!
Nem gyúl érettem viszonérzemény.

Én távozom, s örökre távozom
Gyötrő titkommal tőled, oh leány!
Vezessen a sors boldog útakon,
Öröm-tavasznak tündér-korszakán.

Legyen pályád mosolygó rózsakert,
És minden óra benne rózsaszál,
S ne tudd, ne tudd, leányka, e levert
Sziv-éjjelen, hogy csillagom valál!','Itt a bucsúperc: válok. - Nem szabad!
Leomlok, a világ kereng velem!
E szenvedés, e szörnyü kín alatt
Hogy nem repedsz meg, égő kebelem?','Ostfiasszonyfa, 1839. szeptember',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,7,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-09','petofi','Elválás','Vert az óra,
Halnak a remények,
Kik szívembe
Hajnalfényt hintének;
Szebb jövendő
Tiszta hajnalfényét,
Mely keblemnek
Éjjelét üzé szét.

Vert az óra!
A szörnyű itélet:
"Elszakadni
Mindörökre tőled,
Lány! szerelmem
Nyájas tavaszában!"
Zúga hozzám
Rémes kongásában.

Szűm nyugalmát
Ismét hol találja,
Messze tőled
Keblem ideálja?
Honnan int a
Csendes béke réve,
Honnan int a
Bujdosó elébe?

A mosolygva
Kedvező szerencse
Pályád édes
Örömökkel hintse,
Míg én búban
A széles világot
Átfutom, nem
Lelve boldogságot.','Vert az óra,
Halnak a remények,
Kik szívembe
Hajnalfényt hintének;','Ostfiasszonyfa, 1839. szeptember',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,8,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-10','petofi','Boszú','Kecses tavasz virúla;
Vidám tekintete
Berkemnek kebelébe
Rózsákat űltete.

Mosolygtak a tavasznak
Bájgyermeki felém,
S én bíbor bimbókat
Enyelgve tördelém.

De látta a leányka
Könnyelmű tettemet,
S testvéreit boszúlva -
Kitépte szívemet.

Azóta létem árva,
Kietlen pusztaság,
Mint, melynek elraboltam
Diszét, a rózsaág.','Kecses tavasz virúla;
Vidám tekintete
Berkemnek kebelébe
Rózsákat űltete.','Sopron, 1839. őszén',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,9,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-11','petofi','Első szerelem','Szép a rózsa hajnal-ébredése,
A leányka arculatja szebb volt.
Messze bércek kékellő homályán
Bájjal ég az arany esti csillag;
A leányka nefelejcs-szemében
Tündérfénnyel szebb csillagzat égett.
Csattogánynak zengeménye nyájas
Csendes éjjel, viruló berekben;
Nyájasabban kelt a lányka hangja
Ajaki paradicsom-kertéből.
És ha tiszta a liget virágit
Gyémánt-cseppel éltető patakcsa:
Tiszta volt a lyányka keble szinte,
Tiszta szíve, tiszták érzeményi.
A leánykát hévvel én szerettem,
Őt szerettem első szerelemmel,
Érte gyúltam őrült gerjelemben,
S haj, a végzet elszakaszta durván,
Elszakaszta mindörökre tőle!
Hagyjatok, ha néha álmim őtet
Elragadtan a dicsőet festik,
Oh barátim, hagyjatok zokogni:
Veszteségem szörnyü, mondhatatlan!','Szép a rózsa hajnal-ébredése,
A leányka arculatja szebb volt.
Messze bércek kékellő homályán
Bájjal ég az arany esti csillag;','Sopron, 1839. őszén',null,'Ifjúkori költemények',array['Szerelem','Természet']::text[],'{}'::text[],false,10,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-12','petofi','Bucsú','Irígyen a sors boldogságom ellen,
Pozsony! körödből ismét messze hí;
Megyek - de dúlva van bucsúzó mellem,
Miként váradnak puszta termei.
Utánam intesz még Dunád ködébül,
S arcomra keserű köny árja gördül.

Nem hosszu volt tebenned múlatásom,
S az órák mint a nyíl röpűltenek,
De ily órákat a nagy mennyországon
Angyalnak adnak csak az istenek.
Édenben éltem üdvözűlöttképen
Barátaimnak nyájas, hű körében.

A messze távol kéklő fátyolába
Takarja már szép képedet, Pozsony,
Nem lágyul a vad végezet, hiába
Nyögel panasz kesergő ajkamon:
Mennem kell! s tán örökre szakadátok
Már tőle el, ti szeretett barátok?

Vegyétek hát a bujdosó kebelnek
A zúgó szélben hangzó végszavát:
Szerencse kényei akár emelnek,
Akár nyomor s inségbe döntnek át,
Míg a koporsó nyugtomat nem adja,
Érettetek gyúl szívem indulatja.','Irígyen a sors boldogságom ellen,
Pozsony! körödből ismét messze hí;
Megyek - de dúlva van bucsúzó mellem,
Miként váradnak puszta termei.','Pozsony, 1840. január 21.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,11,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-13','petofi','Galgapartihoz','Üdvözöllek messze bérctetőkről,
Szent helyek!
Hol a Galga lassu andalgással
Hempelyeg.

Hol pályája éden volt a gyermek-
Ifjunak.
Hol az életüdv örömvirági
Nyíltanak.

Lángszerelem szép viszonozója,
Barna lány,
Emlékezve küldsz-e még sohajt a
Szív után,

Mellyet annyi kéjnek bölcsejében
Ringatál,
Mellynek első éneket lantjára
Te csalál?

Ah, rád vissza bús könyhullatással
Néz szemem:
Vesztve téged vésze boldogságom,
Mindenem!','Üdvözöllek messze bérctetőkről,
Szent helyek!
Hol a Galga lassu andalgással
Hempelyeg.','Gréc, 1840, május 1.',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,12,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-14','petofi','Az őrágyhoz','Égig emeljen bár a játszi szerencse kegyelme,
És legyen első rang rangom az isten után;
S bár csak azért szűljön két India kincset özönnel,
Hogy büszkén ajakam mondani tudja: enyém!
Durva faalkotmány! emléked nem leszen irtva
Szűmből s akkoron is hajlik öledbe fejem;
Hisz te az inségnek mikor éje boronga körűlem,
S hervasztott a bú: balzsamos enyhet adál.
Enyhet adál! az ölő vad kínok örömtelen ifja
Leggyönyörűbb álmit kebleden álmodozá.','Égig emeljen bár a játszi szerencse kegyelme,
És legyen első rang rangom az isten után;
S bár csak azért szűljön két India kincset özönnel,
Hogy büszkén ajakam mondani tudja: enyém!','?, 1840.',null,'Ifjúkori költemények','{}'::text[],'{}'::text[],false,13,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-15','petofi','A dráván','Marburgnál

Zúgó habjaidba szórom
E virágfüzért,
Dráva! Hajtsd alá, s a partra
Tedd, midőn hazámba ért.

Bárha dúlt lesz akkorára
Dísze s hervadott,
És özönnel kelyhe nem hint
Szerte éden-illatot.

S mondjad: ilyen a honáért
Lángoló kebel,
Melyet a sors zivatarja
Tőle messze sodra el.','Marburgnál
Zúgó habjaidba szórom
E virágfüzért,
Dráva! Hajtsd alá, s a partra','Marburg, 1840',null,'Ifjúkori költemények',array['Haza']::text[],'{}'::text[],false,14,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-16','petofi','Álom','Kór valék, fájdalmaimnak
Szenvedém nagy kínjait;
Jött az éj szelíden végre,
S könyörűlve békeségre
Álmaim karába vitt.

És láttam ott
A szőke lányt,
Nem hidegen
Már szűm iránt;

Hozzám voná
A szerelem,
S eget lele
E kebelen,

S én piruló
Lángajakán,
Mézcsókjait
Lecsókolám.

És újra csók,
S megannyi csók,
S oly édesek!
S oly lángolók!!

Ily álmakat adjatok, isteneim,
És marhat a fájdalom, a fene kín;
Én tűrni fogok, - valahára talán
Majd égi való jön az álmak után.','Kór valék, fájdalmaimnak
Szenvedém nagy kínjait;
Jött az éj szelíden végre,
S könyörűlve békeségre','?, 1840.',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,15,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-17','petofi','Honvágy','Borúnak éjjelén, derűnek hajnalán
Feléd siet remegve bús
Pillantatom, mindig feléd, arany kalász
Hazája, boldog róna, hol
Csókolva ölelkeznek Csepe mezőivel
Dunánk ezüst hullámai.
Áldás malasztja rám felőled nem lebeg,
Csak egy kemény atya átkait
Zúgják fülembe a nyargaló fuvalmak, oh
Ezer tövissel hinteni
A bujdosónak útait! Mégis te vagy
Örök betűkkel írva fel
E szív emlékkönyvében. A napok sorát,
Melyet lefutnom rendele
Az ég, ohajtom én kunyhód homályiban
Élhetni, s a szelíd halál,
A szenvedések altatója hogyha jő
S átszenderíti lelkemet
Egy boldogabb világba: harsogó Duna!
Kiszenvedett porom fölött
Te mosd a zöldelő hant bársony pázsitát,
S a mormogó habzaj között
Édesd nyugalmak ülnek sírkövemre majd,
S a jégszív is talán, kinek
Átkai nyomák a kínos életet, ledől
Békülten a halom fölé,
S lágyult kebel meleg könyűivel rebeg
Panaszt: szegény, szegény fiam!','Borúnak éjjelén, derűnek hajnalán
Feléd siet remegve bús
Pillantatom, mindig feléd, arany kalász
Hazája, boldog róna, hol','?, 1840.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,16,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-18','petofi','Triolett','Rejts ölednek éjjelébe
Szent nyugalmu sírhalom!
E kinéletnek vesződve
Láncait mért hordozom?
Kebled csendes éjjelébe
Nem tekint a fájdalom,
S a keservek halvány képe;
Ott öröklő bék'' vagyon.
Rejts hát kebled éjjelébe,
Szent nyugalmu sírhalom!','Rejts ölednek éjjelébe
Szent nyugalmu sírhalom!
E kinéletnek vesződve
Láncait mért hordozom?','?, 1840.',null,'Ifjúkori költemények',array['Haza']::text[],'{}'::text[],false,17,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-19','petofi','Vándordalok','1

Távol szeretteimtől,
S tőled, te drága hon!
Vándorlom a világot
Végetlen útakon.

És lábam a nagy úton
Fáradva lépdegel,
Mert vállaim tetézvék
Butyornak terhivel.

Eldobtam én a terhet,
Nincs többé vállamon;
És mégis vajh mi csüggeszt?
És mégis vajh mi nyom?

Boldogtalan fiú te!
Mely tégedet lever,
Nem válladon... szivedben
Az óriás teher.

2

Hová, hová az égi úton,
Darusereg;
Azért hagyjátok-e a tájat,
Mert nem meleg?

Vándorlok én is, ámde pályám
Ellenkező:
A szerelem forró honából
Jégsír felé.','1
Távol szeretteimtől,
S tőled, te drága hon!
Vándorlom a világot','Pápa, 1841.',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,18,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-20','petofi','Kuruttyó','1

"Hogy fejedre pusztaságot hozzon
Isten átka, csalfa, bűnös asszony!
Aki által oly sötét gyalázat
Vonta éjbe a Kuruttyóházat.

Hittem asszony esküvő szavának,
De hiszek már inkább karcsu nádnak,
Hogy kerengő forgószél viharja
Lenge szálát földre nem csavarja.

Szűzeséged a manó elhordta,
Nem köllesz már, hűtelen rosz borda!
Nem köllesz, maradj magadra, s engem -
Vagy látsz többé vagy sem életemben."

Dörg Kuruttyó s üllőt, kalapácsot
És szöget, mit izzadván kovácsolt,
Hány a sátor minden szögletébe,
S nagy szitokkal ajakán kilépe.

Útnak indul, úgy ragadja lába,
Hogy fejér ló sem jutna nyomába.
Sír az asszony, a szegény ártatlan,
Messze a férj bujdos már távolban.

2

Barna csapszékben Kuruttyó
Űl sötéten,
Űzni vágyván szíve kínját,
Bor kezében.

S korty után korty, haj, de kínja
Végtelen hív,
Semmikép sem szabadulhat
Tőle a szív.

S jő toborzó víg legények
Cifra serge,
S énekelnek sarkantyújok
Összeverve:

"Jöszte, pajtás, közénk, csapj föl
Katonának,
Szép szolgálni a királynak
És hazának.

Életünk vidor, mosolygó
Szép halálunk,
Ha riadtán trombitának
Harcra szállunk.

Itt a markunk, csapj belé, jer
Katonának,
Szép szolgálni a királynak
És hazának!"

S űzi ének, tánc Kuruttyó
Nagy bánatját.
A garadra önt néhányszor,
S - parolát ád.

3

Zajos órák mámora
Hogyha széjjellebben,
Dúl a régi fájdalom
Annál dühösebben.
Nyugszik a tánc, hallgat a vig zeneszó,
És buvában újra sorvad Kuruttyó.

Tarka, foltos fegyvere
Rajt virít a rozsda,
S fényesítni oly nehéz
Az istenátkozta.
"Hej, jobb volna most koholni vasszeget,
Vagy heverve nyujtózkodni zug megett."

Nézd, Kuruttyó, nézd ki jő
Látogatni téged?
Isten engem, oly alak,
Mint a feleséged.
Ő az, ő! az ártatlan férjhagyta nő.
Karján mosolyg nyájas barna csecsemő.

"Ez Kuruttyóivadék!"
Mond a kisded apja,
És a rajkót és a nőt
Kebelére kapja.
S vége nélkül, hossza nélkül pityereg.
Jókat kacag rajt a víg ujoncsereg.','1
"Hogy fejedre pusztaságot hozzon
Isten átka, csalfa, bűnös asszony!
Aki által oly sötét gyalázat','Pápa, 1841. március 10.',null,'Ifjúkori költemények',array['Haza']::text[],'{}'::text[],false,19,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-21','petofi','Török Gyula emlékkönyvébe','Hogyha messze lészek tőled vettetődve,
E lap által légy rám emlékeztetődve.','Hogyha messze lészek tőled vettetődve,
E lap által légy rám emlékeztetődve.','Pozsony, 1841. március 25.',null,'Ifjúkori költemények','{}'::text[],'{}'::text[],false,20,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-22','petofi','Neumann Károly emlékkönyvébe','Szeretlek, mint a hold a csendes éjet,
Miként a léget a szabad madár;
Szeretlek oh, barátom, míg az élet
Köréből a halál a sírba zár.','Szeretlek, mint a hold a csendes éjet,
Miként a léget a szabad madár;
Szeretlek oh, barátom, míg az élet
Köréből a halál a sírba zár.','Selmec, 1841. április 17.',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,21,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-23','petofi','Örök bú','Tódul a felleg; barna éjbe vonja
A látkört, búsul a sötét vidék.
Sötét e szív is, hű szerelmem honja,
Reá a bú gyászfátyla szöveték.

Nem bírva terhét, a felhő könyekre
Fakad, s a rózsa gyüjti gyöngyeit.
Megtelt e szív is, könyeim peregve
Áztatják arcom hervadt díszeit.

Színekkel tarkaékesen szivárvány
Ragyog keletről, szép derű jele.
Borúm örök, haj, lánykám nem mosolyg rám
Szivárványként, hogy földerítene.','Tódul a felleg; barna éjbe vonja
A látkört, búsul a sötét vidék.
Sötét e szív is, hű szerelmem honja,
Reá a bú gyászfátyla szöveték.','Dunavecse, 1841. április 24.',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,22,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-24','petofi','Zivatar','Mit nekem hab? mit nekem vész?
Én nem félem haragát;
Kebelemnek pusztaságán
Száz sirokko rohan át.

Rajta, gyorsan evezőhöz,
Talpra reszkető legény,
Bár toronnyá nő a hullám,
A túlpartra szállok én.

Köd borong ott, sűrű ködnek
Kétségbarna éjjele,
Lány, temetve mindörökre
Légyen emléked bele;

Mely ez égő szerelemmel
Enyelegve játszhatál,
Mely hüséget esküvél, és
Ah mely mégis megcsalál.

Rajta, bajtárs, csüggedetlen!
Nincsen messze már a part;
Bár izzadva, férfiszívvel
Mi kiálljuk a vihart.

Im, mi kép leng a ködéjben?
Bájoló, mint a tavasz,
Szőke fürttel - kék szemekkel -
Hűtelen lány! képed az.

Haj, nélkűle nincsen élet!
Vissza, izzadó legény,
Bár Mátrává nő a hullám,
Vissza - hozzá - szállok én!','Mit nekem hab? mit nekem vész?
Én nem félem haragát;
Kebelemnek pusztaságán
Száz sirokko rohan át.','Dunavecse, 1841. május 8.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,23,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-25','petofi','Újság','Figyeljetek, derék história!
"Halljuk! Tovább! Na s aztán!" A minap
Szent elragadtatás tüzével egy
Költő merészen mászta Helikon
Bércét, örök életű hírkoszorút
Füzendő fürtibe a fénytetőn.
Már-már magos céljához ért, midőn
Réműletes mennydörgés hallatik.
""Védj, szent Apolló!"" Ujra mennydörög.
Megborzad a költő, s uramfia!
A mélybe henterűl. "Hahahaha!"
S ugyan mi dörge? "A boszús Olymp."
Nem. "Halljuk! Halljuk!" Hát a Múzsafi
Nem legbővebben abrakolt - hasa.','Figyeljetek, derék história!
"Halljuk! Tovább! Na s aztán!" A minap
Szent elragadtatás tüzével egy
Költő merészen mászta Helikon','Vadas, 1841. május 16.',null,'Ifjúkori költemények','{}'::text[],'{}'::text[],false,24,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-26','petofi','Változás','Míg a földet gyász temette,
Dúlván fergeteg felette
Pusztaságnak vad telén,
Mért virúla bájos éden
Kebelemnek belsejében?
Mert rózsámat ölelém.

Most, midőn a szép tavasznak
Uj virányi illatoznak
A mosolygó téreken;
Mért vagyon tél kebelemben,
Puszta, gyászos, véghetetlen?
Mert rózsám nem ölelem.','Míg a földet gyász temette,
Dúlván fergeteg felette
Pusztaságnak vad telén,
Mért virúla bájos éden','Vadas, 1841. május 23.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,25,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-27','petofi','Csal','Völgy homályán, fák hüsében,
Kert megett,
Zeng a lantos hév szerelmi
Éneket.

Zeng, ha gyúl a rózsahajnal
Keleten,
Ha nyugodni bérc megé a
Nap megyen.

S szép tavasszal, nyár hevén, hüs
Őszön át
Pengeti a szerelemnek
Hév dalát.

S édes díja zengzetének,
A leány
Ha kacsingat által a kert
Ajtaján.

Jő a tél, és megnyil a kert,
És ragad
Kebelére a leány - más
Boldogot.

A csalódott megy kinok bús
Éjjelén,
S hallgat a dal lantja néma
Idegén.','Völgy homályán, fák hüsében,
Kert megett,
Zeng a lantos hév szerelmi
Éneket.','Dunavecse, 1841. május 27.',null,'Ifjúkori költemények',array['Természet','Szerelem']::text[],'{}'::text[],false,26,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-28','petofi','Vendég','Kerepöl a szarka
Házam tetején:
Vendég jön. Vendégnek
Vajh, kit várjak én?

Messze föld határán
Jár a szerető,
Csalfa volt szerelme,
Vissza nem jön ő.

Tán te léssz vendégem,
Óhajtott halál;
Úgy siess, ne késsél,
Ajtóm nyitva áll.','Kerepöl a szarka
Házam tetején:
Vendég jön. Vendégnek
Vajh, kit várjak én?','Dunavecse, 1841. június 5.',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,27,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183801-29','petofi','Elégia','Meddig dúlsz, szerelem pusztító lángja, szümön, mint
A mennyverte Prometh keblin az éhes ölyü?
Meddig nyűgöz Amor kinos lánca? Endymionnal
Meddig jajgat hurom búskeseregve panaszt?
Féktelen érzetnek vad hevű szikrája, lohadj el,
Hullj le bilincs, szünjön, lant, szomoru, árva jajod:
Végihez ér nagy fáradozása a Danaidáknak,
Föltészi a sziklát hegy tetejére, Sysiph,
Nem forog Ixion, Tantalnak szomja csillapszik:
De hidegen marad a lánynak örökre szive.
S érette, ah boldogtalan én, mindegyre hevülök,
Keblem Vesta-tüzét nincsen eloltni erőm.
Égj, szivem, hát, égj mint forró Hyperiona nyárnak,
Melynek ölő sugarán gyönge virágcsa fonyad.
Hervadok én is majd, s hervadván enyhre találok,
Ha tovaszállt lelkem Lethe özönébe merűl.','Meddig dúlsz, szerelem pusztító lángja, szümön, mint
A mennyverte Prometh keblin az éhes ölyü?
Meddig nyűgöz Amor kinos lánca? Endymionnal
Meddig jajgat hurom búskeseregve panaszt?','Dunavecse, 1841. június 22.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,28,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-30','petofi','Epigrammok','1

Ujra mosolyg a táj aranyos sugarakba'' fürödve,
A hanyatló Phoebus ha nyugalomra megyen.
Engemet, haj, szeretőm búcsúzó pillanatával
Holdtalan éjfélként bánat homálya takar.

Dunavecse, 1841. június 23.

2

Martial után

Pompej magzatjait Ázsia és Európa temette,
Őt pedig Afrika; hant ha bizonyára födi.
Hogy szanaszét ekkép hever elszóródva, mit ámulsz?
Hogy birt volna a föld egy helye annyi romot?

Dunavecse, 1841. június 23.

3

Martial után

Zápor zápor után, a szüret szűnetlenül ázik.
Bár akarod nem jő szűz bor icédbe, csaplár.

Dunavecse, 1841. június 23.

4

A szerelem jelené; multé s jövőé a barátság.','1
Ujra mosolyg a táj aranyos sugarakba'' fürödve,
A hanyatló Phoebus ha nyugalomra megyen.
Engemet, haj, szeretőm búcsúzó pillanatával','Dunavecse, 1841. június 23.',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,29,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-31','petofi','Méz és csók','Kis méh! te a füvet, fát
S virágokat leped,
Hogy édes kelyheikből
Gyüjthessed mézedet.

Kis méh! Lidim füvet, fát
S virágokat nem lep,
Mézednél csókja mégis
Mi sokkal édesebb.','Kis méh! te a füvet, fát
S virágokat leped,
Hogy édes kelyheikből
Gyüjthessed mézedet.','Pápa, 1841. november-december',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,30,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-32','petofi','Tűnődés','Ifjúkoromnak ébredése
Ah, oly tündéri, szép vala,
Miként a koszorús tavasznak
Varázst mosolygó hajnala.

Hű lyányka dűle karjaimba,
Hű lyányka csókja égete,
S mennynek röpíté képzeményim
Hesper-tüzű tekintete;

S az érzemény, mely lelkesítve
Dagasztá e meleg kebelt,
Rózsás berek lombsátorában
Szelíden ömlő dalra kelt.

Lejárt az év, s a fáradatlan
Idő uj évet alkota,
A kellemgazdag ifjuságnak
Elhulla bájvirúlata;

S nincs már a lyányka karjaimban.
És hervad a fantázia,
Az istenítő boldogságnak
Ekkép ki kelle halnia!

Ti, fönt a menny kék tengerében
Mosolygva fürdő csillagok!
Trónjához a szent végezetnek
Olyan közel kik állotok.

Melyik ragyog reményt szivembe,
Melyik ragyog közűletek?
Hogy egykor még örömre kelni
Nem lészen tiltva véletek;

Akár a lyányka hű ajkáról
Szedvén új édes csókokat,
Akár ha szárnya képzetemnek
Dicsőbb világokhoz ragad.','Ifjúkoromnak ébredése
Ah, oly tündéri, szép vala,
Miként a koszorús tavasznak
Varázst mosolygó hajnala.','Pápa, 1841. november',null,'Ifjúkori költemények',array['Szerelem','Természet']::text[],'{}'::text[],false,31,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-33','petofi','Lenke sírján','Ádáz koporsó zordon éjjele!
Mivé tevél te oly sok örömet?
Mivé tevél te annyi szép reményt?
Mely zsenge a szülői szív felett,

Mely egy kéjparadicsomot igért
Rózsás jövendő boldog karjain;
Kegyetlenűl mind elragadtad ezt,
Csak romja áll még: a keserv, a kín!

Oh, a szülők! ha sorsok vészt zudít
Keblökbe dúlni és pusztítani:
Ki fog miként egy égnek angyala
Bút űzve rájok felmosolygani?

Nyugodjatok meg, szerető anya!
S te bús atyának gyászló kebele!
Kedves Lenkétek, ah, nem lészen ő
Temetve itt e sírnak mélyibe.

Hol a teremtő széke tündököl
Felhők felett a csillagezreden:
Tekintsetek fel, egy szelíd sugár
Leng ottan rátok csendes éjeken.

És e sugár az ő szép szelleme!
Az angyalok között ott múlat ő,
Imádva istent, hogy boldog legyen
A kor, mely a kedves szülőkre jő.

S örvend előre a jövő felett:
Midőn az alkotó székéből int,
S a drága magzat, s a kedves szülők
Egymást vigadva ölelik megint.','Ádáz koporsó zordon éjjele!
Mivé tevél te oly sok örömet?
Mivé tevél te annyi szép reményt?
Mely zsenge a szülői szív felett,','Pápa, 1841. december',null,'Ifjúkori költemények',array['Szerelem','Család']::text[],'{}'::text[],false,32,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-34','petofi','Hazatérés','Németből Heine után

Te szép halászleányka,
Hajtsd partra csolnakod;
Jőj, s űlj le oldalamhoz,
És nyujtsd nekem karod.

Fejecskéd tedd szivmre,
S ne félj, ne oly igen,
Hisz gondtalan naponként
Jársz a vad tengeren.

Tengerhez szűm hasonló,
Van rajt vész, ár, apály;
És mélyen fenekében
Nem egy szép gyöngy is áll.','Németből Heine után
Te szép halászleányka,
Hajtsd partra csolnakod;
Jőj, s űlj le oldalamhoz,','Pápa, 1842. február',null,'Ifjúkori költemények',array['Haza']::text[],'{}'::text[],false,33,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-35','petofi','Ifjú a pataknál','Németből Schiller után

Forrás mellett űlt a gyermek,
Koszorúkat kötözött,
S látta őket elragadtan
Tűnni a habtánc között.
Éltem így röpűl, miként a
Forrás, fáradatlanúl,
S mint a koszorúk, sietve
Ifjuságom elvirúl.

Ne kérdjetek, mért busongok
Éltem rózsaidején;
Minden örvend és reményel
A tavasznak jövetén.
Ámde az új természetnek
Ébredő hangezrede
Kebelemnek rejtekében
Csak nehéz bút kelthete.

Nem vidítnak a vigalmak,
Melyeket nyujt a szép tavasz;
Egy köt engem csak: közel van,
S mégis messze tőlem az.
A kedvelt árnykép elébe
Vágyva nyujtom karomat,
Haj! nem érem el s ez érzet
Csillapítatlan marad.

Jőj le, jőj, o szép leányka,
Hagyd kevély lakod falát,
Majd virágit a tavasznak
Kebeledbe hintem át.
Ime, dal zeng a berekben,
S tiszta zajjal jár az ér;
Egy boldog szerelmü szívpár
Kis kunyhóban is megfér.','Németből Schiller után
Forrás mellett űlt a gyermek,
Koszorúkat kötözött,
S látta őket elragadtan','Pápa, 1842. február',null,'Ifjúkori költemények',array['Természet']::text[],array['tavasz']::text[],false,34,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-36','petofi','Pórnak esti dala','Németből Claudius után

Az ékes nappali csillagzat
Pályáját végezé,
Jer, és törűld le izzadásom,
S teríts fel, drága nő.

Csak itt a földön is teríthetsz,
Gyümölcsfánkhoz közel;
Itt jóizű az étel este,
S legtágasabb a hely.

Aprócska vendéginket is hídd,
Mert úgy kiéhezém;
A legkisebb is hagyja fészkét,
Ha álom nincs szemén.

Sokat tálalnak a királynak,
Ő, amint hírelik,
Mindennap sűltet, meg lepényt, meg
Pástétomot eszik.

S egy ember van mellé rendelve,
Más dolga nincs neki,
Asztalneműjét rendezi csak,
S szolgálatát teszi.

Adj isten ő egészségére!
Mert mennyi dolga van;
Hogy minket békében tarthasson,
Éj s nappal nyugtalan.

Ha úri mód nem élhetünk is,
Van mégis kenyerünk,
Van tiszta, szép és fris tej és vaj;
S hát kell-e több nekünk?

Elég ez úntig póri népnek;
Vedd hálánk érte, ég!
S ma estelink szabadban tartjuk,
Hol annyi csillag ég!

A hold ezüstlő súgarakkal
Leszen velünk jelen,
És áldást hintve tálainkba
Fog tündökölni fen.

Nos, gyermekeim, együnk vidáman,
S a mennyek áldjanak!
O én irígylendő, szegény és
Mégis gazdag vagyok!','Németből Claudius után
Az ékes nappali csillagzat
Pályáját végezé,
Jer, és törűld le izzadásom,','Pápa, 1842. február',null,'Ifjúkori költemények',array['Természet']::text[],'{}'::text[],false,35,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-37','petofi','Elégia egy várrom fölött','Németből Mathisson után

Nyugszik esti szürkület fátylában
A halk táj, s a berki dal kivesz,
Még csak itt az agg falak körében
Egy tücsök borongva zengedez.
Csend lebeg le fellegetlen égről,
Lassan mén a csorda mezejéről,
És a fáradt földmives halad
Megnyugodni ősfedél alatt.

Itt az erdőkoszorús tetőkön,
Az enyészet töredékiben,
Hol reám a múltból borzalom száll,
Bánat! e dalt néked szentelem.
Búval gondolom, hogy mik valának
Hajdanán e porló maradványok:
Egy tornyos vár állt felségesen
A hegyeknek szirttetőiben.

Ott, hol oszlopok setét kövére
Bút susogva hajlik a repkény,
És a puszta ablak üregén át
Csillog szomorún az esti fény,
Az atyának ott talán könyűje
Áldva perge bátor gyermekére,
Melynek hírsovárgó kebele
Vágyva néze harcnak ellene.

Béke veled! szólt az őszűlt bajnok,
Átövezve hősi karddal őt,
Soha többé, vagy térj győzve vissza;
Érdemeld meg őseid nevét!
És a nemes ifjunak szemébe
Rémitő láng szálla; arca ége
Rózsáknak virító berkeként,
Melyre bíbor hajnal hinte fényt.

És arszlánszivű Richardként harcba
Akkoron röpűlt a dalia,
S mint erdőnek a viharban kellett
Ellenének meghajolnia!
S mint virágos partu ér szelíden
Szállt meg sziklavára teremében,
Az örömkönyűt siró atyát
És ölelve szép menyasszonyát.

Ah gyakorta a szorongó kedves
Erkélyéről néz a völgy felé,
Vért, pajzs csillog estnek aranyában,
A paripa nyargal, hive jő:
Hallgatólag jobbját néki nyujtja,
S áll majd halványan, majd elpirúlva;
De mi szende szemeiből szól,
Olyat Petrarc'' s Sappho sem dalol.

Hol bagolyfészkek fölött terűlnek
Durván összebonyolúlt füvek,
Ott a billikom vidáman csenge,
Míg a csillagok kiégtenek;
Terhesen vítt harcok diadalma,
És a szent csaták szörnyű kalandja
Míg emlékezetben újra kelt,
Kedvvel tölté a zord hőskebelt.

Ó mi változás! most borzadályos
Éj takarja a dicső helyet,
S esti szél nyög búsan, hol erősek
Vígadának áldomás felett;
Ott magányos kórók lengedeznek,
Hol lándzsát és pajzsot kért a gyermek,
Ha riadván a harctrombita
Csataménre pattant az atya.

Elhamvadtak a hatalmas csontok
Immár a borongó föld alatt;
Félig sűlyedt kő alig mutatja,
Hol találták végnyugalmokat.
Mennyi lett játéka a szeleknek,
Sírjaikkal emlékeik is vesztek;
A vitéz kor fénytettei felett
Feledés űz barna felleget.

Igy enyész a élet dicsősége,
S hatalomnak álomképzete!
Igy merűl a gyors idő röptével
Éjbe minden, amit föld szüle!
Hamvveder, szánt az emlékezetnek,
Halhatatlanság-igérő ének,
Győztes főt koszorúzó babér,
S tett, amelyet érc, márvány dicsér:

Minden, ami bájol, s vággyal tölti
Itt a porban a nemes kebelt,
Eltűnt, mint az őszi nap sugára,
Hogyha vész a láthatárra kelt.
Kik vígan ölelkezének este,
A korány arcokra már bút feste;
A barátság is, s a szerelem
Kéje vész a földről jegytelen.

Édes szerelem! rózsás ösvényed
Pusztaság tövisivel határ,
S te, barátság aetheri világa,
Egy rögtön vihar homályba zár.
Kábaság a hír, fenség, hatalmak!
A koporsók egyiránt takarnak
Éjbe büszke földuralkodót
S reszketeg fejű zarándokot.','Németből Mathisson után
Nyugszik esti szürkület fátylában
A halk táj, s a berki dal kivesz,
Még csak itt az agg falak körében','Pápa, 1842. február',null,'Ifjúkori költemények',array['Természet','Haza','Szerelem']::text[],'{}'::text[],false,36,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-38','petofi','Ideál','Küzdő gerjedelmek... fény,... homály,... csapongó
Vágyak és remények tarka serege!
Melyek majd borongva, majd derengve kelnek,
Indulatcsatáit a zajló kebelnek,
Ah! ki festi le?

Mért e láng, e hullám dagadó eremben?
Honnan e feszítő érzet keblemen?
S szomjazó hevökben e zajongó vágyak
Lenge képzeletnek karján merre szállnak,
Merre szűntelen?

Mely varázserőnek bűvös ihletése,
Ah, mi készti zengő dalra lantomat?
És a dal ha fölzeng, újra vajh mi némit?
Mert a húr beszélni szívem érzeményit
Nem lel hangokat.

Messze, messze szállnak érzeményim innen,
Ó a puszta föld ez nem az én hazám;
Itt a bús valónak hervatag körében
Bájoló ajakkal édesen, szelíden
Mi mosolygna rám?

Fent, elérhetetlen égmagas tetőkön
Istenszép alakkal rózsafényben áll,
Mely után epedve küzd a hév indúlat,
Mely után e szívnek dobbanása gyúlad,
Ott az ideál!

Ott lebegsz előttem tündér fátyolodban
A hajnal biborszín leplén, szép alak!
Ott lebegsz az alkony elhaló tüzénél,
S szende fényhomályán a merengő éjfél
Holdsugárinak.

És ha zúg a szélvész tomboló csatája,
És ha nyögve sír a berki csalogány;
És te lengsz előmbe, hogyha sujta bánat,
S hogyha keblem éjén kéj koránya támad
Kíncsaták után.

Lelkesűlt idegről száll feléd az ének,
Forró érzeményim szállanak vele;
Óh ki élsz ragyogva túl a földhomályon,
Halld meg a sovár szűt, égi ideálom
Tiszta kebele.

Jőj le bájaidnak szép gazdagságában,
Jőj egy pillanatra, túlvilági lény!
Jőj, ez árva lét hogy elfeledve légyen,
Hogy szelíd ölednek enyhe édenében
Idvezűljek én.

Hervadok, teérted hullanak virágim,
Mint a gyenge rózsa nyári hév alatt;
Légy keserveimnek édes, égi bére,
Hintsd e sorvadó ajk égető tüzére
Szellemcsókodat!

Vagy ha zárva tőled e világ határa,
Oh ha karjaimba jőnöd nem szabad!
Ints, ragadj fel hozzád egy varázserővel,
Ints, hagyj összeforrni fényed szépségével,
Nélküled haj éltem kín és kárhozat!','Küzdő gerjedelmek... fény,... homály,... csapongó
Vágyak és remények tarka serege!
Melyek majd borongva, majd derengve kelnek,
Indulatcsatáit a zajló kebelnek,','Pápa, 1842. február-március',null,'Ifjúkori költemények',array['Természet','Haza']::text[],'{}'::text[],false,37,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-39','petofi','Kolmár József emlékkönyvébe','Magas trónján a sors ül, titkos könyv kezében,
Az életkönyv ez; benne két lap a mienk,
Az egyiken borongó gyász vonúl sötéten,
A másik hajnalodva rózsaként dereng.
Ohajtom én: legyen hő kedveződ a végzet,
Hogy általolvasnod ne kelljen a sötétet!','Magas trónján a sors ül, titkos könyv kezében,
Az életkönyv ez; benne két lap a mienk,
Az egyiken borongó gyász vonúl sötéten,
A másik hajnalodva rózsaként dereng.','Pápa, 1842. április 12.',null,'Ifjúkori költemények','{}'::text[],'{}'::text[],false,38,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-40','petofi','Dalforrás','Költőnek lenni isteni,
Én is költő leszek!
Varázserővel szívemet
E vágy szállotta meg.

S e vágy nem szűnő lángiban
Mindegyre égtem én;
Ragadtam végre a kobozt
Nagy tűzzel, hevenyén.

S hogy énekem röpűlete
Fellengezőbb legyen,
Telt hordóhoz vevém magam,
Pincének mélyibe.

Míg fejtörés között időm
Itt lassan mendegelt:
A - nem mondhatnám szűk - torok,
S a csap nem vesztegelt.

De bármint törtem fejemet,
S levék borral tele:
Hiában! a csigázott ész
Egy kukkot sem szüle.

Végpontra szállt a türelem!
Még egyszer jót iszom;
S manó vigye, ha éneket
Ugysem zeng kobozom.

S a csapnak estem nagy mohón,
Gondolva ezeket,
De ó hallatlan bosszu! a
Csap már nem csepegett.

Zajló kebellel álltam ott,
Bennem harag gyuladt,
És megragadtam s vágtam a
Hordóhoz lantomat.

Felhangzott a kiürűlt
Hordónak kebele...
S o üdv, o kéj! a fejtörő
Titok kulcsot lele.

Bélőlem - végre rájövék -
Költő miként leszen:
Im, telve hallgatott s konog
A hordó üresen.

Éhezni kell, éhezni hát,
Ki költő lenni vágy,
Éheztem én is... s folyt a dal
S enyém a mirtuszág.','Költőnek lenni isteni,
Én is költő leszek!
Varázserővel szívemet
E vágy szállotta meg.','Pápa, 1842. április',null,'Ifjúkori költemények','{}'::text[],'{}'::text[],false,39,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-41','petofi','Változó ízlés','Mint szerettem a cseresznyét
Gyermekéveimben én!
Csak cseresznye kelle nékem;
Nem volt szebb szín, édesebb nem
Terme a föld kerekén.

Nem kellett cseresznye többé,
Gyermekéveim után:
Mert az ajak édesebb volt,
Mert az ajkon szebb pir lángolt,
Melyet nyujta szép leány.

És az évek ballagának,
És fejemben ért az ész,
S jóra jöttem valahára!
Most szemem a lyány ajkára
Szinte egykedvűleg néz.

Mert a rózsanedvhez képest,
Mely Ménesnek bércfokán
Omlik kéjes kedvet adva,
A lyány édes bájos ajka
Keserű és halavány!','Mint szerettem a cseresznyét
Gyermekéveimben én!
Csak cseresznye kelle nékem;
Nem volt szebb szín, édesebb nem','Pápa, 1842. április',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,40,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-42','petofi','Ideál és való','Dalra, dalra, néma húrok!
Lengj előmbe, ideál;
Hagyd hevűlni képzeményim
Égi fényed bájinál.

S száll egéből ideálom,
És az ott - mely rózsaszál?
Ah a lyányka ablakából
Ablakomra kandikál.

S ideál és szép leányka
Engemet hevítenek.
Kit tekintsek, kit daloljak?
Mondjátok meg istenek!

Képzetem varázsalakja!
Tünj egedbe, tünj tova;
Való kell a föld fiának,
S költő - nem a föld fia?','Dalra, dalra, néma húrok!
Lengj előmbe, ideál;
Hagyd hevűlni képzeményim
Égi fényed bájinál.','Pápa, 1842. április',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,41,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-43','petofi','Tolvaj huszár','1

Ló dobog, por kél az úton,
Zeng a harsány trombita:
Kvártély, kisbiró! huszárok
Szállanak a faluba.

És hogy jöttek, hogy megálltak
A vitézi seregek:
Aggalom s öröm vegyűlve
A lakókat szállta meg.

Aggalom s öröm szivökben
Nem hiába lakozik:
A huszárok csínosak, de
Kissé hosszuk újjaik.

"Jól vigyázz leányom édes,"
Mond az aggódó anya,
Nehogy ez vagy az lakunkból
Vélek elvándorlana."

2

Ébred a hajnal sugára,
Véle ébred a huszár;
Lóra pattan, induló zeng,
S messze föld fogadja már.

És merengő fájdalommal
Néz utánok a leány;
Köny pereg le szép szeméről,
Mély sohaj kel ajakán.

"Mért, leányom, e busongás?
Könybe mért lábbad szemed?"
"Jó anyácskám, meglopának,
Egy... elvitte szívemet."','1
Ló dobog, por kél az úton,
Zeng a harsány trombita:
Kvártély, kisbiró! huszárok','Pápa, 1842. június',null,'Ifjúkori költemények',array['Szerelem']::text[],'{}'::text[],false,42,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-44','petofi','Szín és való','1

Némúl a hangszerek zenéje,
A függöny felrepűl,
S az arcokon kiváncsiságnak
Csendes figyelme űl.

És ékes színpadon a múzsa
Kegyelt papnéja áll,
Bájlóbb a kikelet kertjének
Minden viráginál.

És oh midőn szavak születnek
Az ajkak bíborán,
Nem, így nem énekel tavaszkor
Pacsírta s csalogány.

S mit benne látsz megtestesűlve:
Erény és szerelem;
S a néptömeg, varázslatánál
Kéjtengerré leszen.

Hódolva a dicső müvészet
Magasb hatalminak,
Éljenzaj és örömkiáltás
És tapsok hangzanak.

De a zajongó nép között áll
Az ifju mereven,
Ah érzeményi zavarának
Nyelvet, szót hol vegyen?

Egy új világ nyilik szivében,
Egy új édenvilág,
És benne lángoló szerelme
Az illatos virág.

2

A barnaleples éj
Nyugalmat osztogat,
De ah! az ifjunak
Nyugalmat az nem ad.

Zajló küzdés szivén,
Szerelmi, égető,
Mely tarka gondolat-
Füzért tünődve sző.

"El, el! meglátni őt,
Az égi szép szemet.
Amelynek e kebel
Imádó rabja lett;

Meglátni a szelíd
Angyalvonásokat,
Melyeknek bájain
Szív és ész elakad;

S a tündértermetet,
S a hullámzó kebelt,
Hol a kecs istene
Két rózsatrónt emelt.

Meglátni, asszonyok
Legszebbje tégedet,
Minőt az ég csupán
Egyszer teremthetett!"

S az ifju elsiet
Szerelme vágyiban
A kedves hely felé,
Hol istennője van.

"Ti ablaki fölött
Irígy őrkárpitok!
Pillantanom reá,
O kérlek, hagyjatok."

Rejtsétek a szobát
Hiven, o kárpitok!
Szivszaggató, miket
Az ifju látni fog.

Csók és édes szavak...
S szerelmi jelenet...
S o bűn, o förtelem...
Szerelmet.. pénz vehet!

3

Színházba seregesen tódúl a nép,
Csudálni a müvésznő érdemét;

S míg hangja lelkesűlt szivekbe hat:
Új és új érdemkoszorút arat.

S az ifju? ... Az ifju tetszés-zaja
Fel-felzeng bájoló játékira;

De ah! titkon folyó könyűiben
Kihalt a néma, kínos szerelem.','1
Némúl a hangszerek zenéje,
A függöny felrepűl,
S az arcokon kiváncsiságnak','Pápa, 1842. június',null,'Ifjúkori költemények',array['Szerelem','Természet']::text[],'{}'::text[],false,43,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-45','petofi','Lehel','1

Mennydörg az óriás kürt
Lehelnek ajakán.
Örvendve nyúl ezer kar
Kifent acél után.

Vérszomjazó örömben
Szikráznak a szemek,
Telt a kebel dicsétől
Harc nagy reményinek.

Jaj annak! aki ellen
E nép kardja száll.
Jaj annak! sorsa lészen
Gyalázat és halál.

Még egyszer zúg riadva
A szélvészhangú kürt
S az alemann seregre
A dúló szittya tört.

S vérnek patakja árad
Az eltiport mezőn,
Kietlen rém-halommá
A holtak teste lőn.

Még vínak oly erősen,
Oly fáradatlanúl!
A szittya kar csapásin
Sok alemann kimúl.

De nyugot népe nem fogy,
Elhullott száz helyett
Konrád hatalmas szóval
Idéz új ezeret.

És haj fordít a kockán
Az inda-végezet,
És haj a magyaroknak
Romlása érkezett.

2

Zajtalan áll a
Gyász-arcu csatahely,
Bátor leventék
Elhullott ezrivel.

Győzött a teutón.
A hosszu harc után
Rabság Lehelnek,
Megtörött had román.

"Rablók! hogy többé
Reánk ne törjetek:
Akasztófára
Egyig most veletek!"

Mond nagy kevélyen
A győző fejdelem,
És a bakóknak
Vad serege ott terem.

"Vezér, jer, illet
Elsőség tégedet,
Elő, hadd lássuk
Félt hősi képedet.

Olyan magasra,
Miként én, emelt-e
A magyaroknak
Hatalmas istene?"

''Fejdelm, oh látnom,
Határtalan kegyed,
Azért hadd kérjek
Tőled tehát egyet:

És teljesítsed,
Kivánatom csekély.''
Előre lépve
Ekkép Lehel beszél.

''Éltemnek a kürt
Olyan hű társa volt,
Mellette vívtam
Sok véres viadalt.

Halálom tőle
Örökre elszakaszt;
Engedd utószor
Megharsogtatnom azt!''

S megriad a kürt
Lehelnek ajakán,
Miként oroszlán
Erdői vad tanyán.

S hogy harsogtatta
Dörgőleg mindenszerte,
Konrádnak álla
És véle őt leverte.

''Te felmagasztalsz,
És én a porba váglak!''
S megy büszke-bátran
Elébe a halálnak.','1
Mennydörg az óriás kürt
Lehelnek ajakán.
Örvendve nyúl ezer kar','Pápa, 1842. tavaszán',null,'Ifjúkori költemények',array['Haza','Természet','Elmúlás']::text[],'{}'::text[],false,44,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1838-183802-46','petofi','Lehel','A kürtkebelbe fú Lehel,
S a kürt riadva énekel
Vad éneket csatára;
S szilaj szikrát ezer szem hány,
És nyúl kifent acél után
Ezer kéz, hallatára.

A kürtnek harsogó szava
Még egyszer szálla tétova,
És összeütközének:
Hadúr világduló fia
S a bosszuló Germánia;
Mind harcszomjas legények.

Iszonyterhes lön a csata!
Vérnek patakja árada
Mezők tiport füvében,
És por közé a hadfiak
Sürűn omolva hulltanak,
Mint gabna jégesőben.

Még dúl soká az ütközet,
Még diadal nem nyujt kezet
Sem ennek sem amannak.
Még a koromsötét halál
Honába kard csapásinál
Ezren s ezren rohannak. -

A sors kockája vetve van!
És haj! seregje csúfosan
Leverve nyög Lehelnek.
S kiket nem ére a halál
Kardok duló csapásinál,
Rabláncon vesztegelnek.

"Hogy többé ránk ne törjetek,
Bitóra tüstént véletek,
Rablók gonosz csapatja!"
Kihez hajolt a győzelem,
Parancsszavát a fejdelem
Ily büszkedurván adja.

"Elő vezér! elő veled;
Elsőség illet tégedet,
Hadd lássuk szörnyu képed.
Olyan magasra emel-e
A magyarok nagy istene,
Mint én emellek téged?"

S a porba tipratott kebel
Fojtott dühérzeményivel
A hős előre lépett,
És szóla: ''Fejdelem! kegyed,
Látom, határtalan; egyet
Engedj hát kérni tőled.

A kürt éltem hű társa volt;
Ő annyi vért és viadalt
Karom között szemléle.
Ez óra tőle elszakaszt;
Hagyd még egyszer megfúnom azt,
Hagyj elbucsúzni tőle!''

És zúg dörögve rémitőn
A kürt ismét Lehel kezén;
S hogy harsogtatta szerte:
Rá szent hevűlet lángja száll,
A győző fejdelemnek áll,
És véle őt leverte!

''Te fölmagasztalsz,'' e szavak
A hősi ajkon hangzanak,
''És én a porba váglak!''
S megy bátran, míg önérzete
Arcára kéjsugárt vete,
Elébe a halálnak.','A kürtkebelbe fú Lehel,
S a kürt riadva énekel
Vad éneket csatára;
S szilaj szikrát ezer szem hány,','Pápa, 1842. június',null,'Ifjúkori költemények',array['Haza','Elmúlás']::text[],'{}'::text[],false,45,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-01','petofi','A borozó','Gondüző borocska mellett
Vígan illan életem;
Gondüző borocska mellett,
Sors, hatalmad nevetem.

És mit ámultok? ha mondom,
Hogy csak a bor istene,
Akit én imádok, aki
E kebelnek mindene.

És a bor vidám hevében
Füttyentek rád, zord világ!
Szívemet hol annyi kínnak
Skorpiói szaggaták.

Bor tanítja húrjaimra
Csalni nyájas éneket;
Bor tanítja elfeledni,
Csalfa lyányok, titeket.

Egykor majd borocska mellől
A halál ha űzni jő:
Még egy korty - s nevetve dűlök
Jégöledbe, temető!','Gondüző borocska mellett
Vígan illan életem;
Gondüző borocska mellett,
Sors, hatalmad nevetem.','Pápa, 1842. április',1842,'1842',array['Szerelem']::text[],'{}'::text[],false,46,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-02','petofi','Két vándor','Honán kül a fiú,
Honában a patak
Magas hegyek között
Együtt vándorlanak.

De míg az ifju megy
Csüggedt lépésivel,
Sziklákon a patak
Gyorsan sikamlik el;

S az ifju ajkain
Míg néma csend honol,
Az illanó vizár
Vig hangokat danol.

A hegysor elmarad;
Az ifju s a patak
Sík róna térein
Tovább vándorlanak.

De, ifju és patak!
Oly gyorsan szerepet
A róna térein
Miért cseréltetek?

Hallgatnak a habok,
S ballagva lejtenek,
Míg gyors szökés között
Az ifju dalt zeneg.

Az elnémult patak
Honát vesztette el;
A dalra kelt fiú
Ismét honára lel.','Honán kül a fiú,
Honában a patak
Magas hegyek között
Együtt vándorlanak.','Pápa, 1842. április',1842,'1842',array['Természet']::text[],'{}'::text[],false,47,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-03','petofi','Mi haszna, hogy a csoroszlya...','Mi haszna, hogy a csoroszlya
Az ugart fölhasogatja?
Hogyha magot nem vetsz bele,
Csak kóróval leszen tele.

Hej kisleány, pillantatod
Mélyen a szivembe hatott;
Mint a földet a csoroszlya,
Azt keresztűlhasogatta.

De hiába hasogatta,
Azért csak bú terem rajta!
Ültesd bele szerelmedet,
Úgy nő rózsa tövis helyett.','Mi haszna, hogy a csoroszlya
Az ugart fölhasogatja?
Hogyha magot nem vetsz bele,
Csak kóróval leszen tele.','Pápa, 1842. nyarán',1842,'1842',array['Szerelem']::text[],'{}'::text[],false,48,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-04','petofi','A dunán','Folyam, kebled hányszor repeszti meg
Hajó futása s dúló fergeteg!

S a seb mi hosszu és a seb mi mély!
Minőt a szíven nem vág szenvedély.

Mégis, ha elmegy fergeteg s hajó:
A seb begyógyul, s minden újra jó.

S az emberszív ha egyszer megreped:
Nincs balzsam, mely hegessze a sebet.','Folyam, kebled hányszor repeszti meg
Hajó futása s dúló fergeteg!
S a seb mi hosszu és a seb mi mély!
Minőt a szíven nem vág szenvedély.','Komárom, 1842. augusztus végén',1842,'1842','{}'::text[],'{}'::text[],false,49,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-05','petofi','Járnak, kelnek sokan zöld erdőben...','Járnak, kelnek sokan zöld erdőben;
Vagyon a nap épen lemenőben.
Rózsákat fest utósó sugára
Dombtetőre, lombok sudarára.

De veszik ők mindezt csekélyebbnek,
Semhogy rajta megörvendezzenek;
Párosult két vadgalamb búgása -
Ebben fakad örömök forrása.

Járok, kelek én is zöld erdőben.
Nap lementén van gyönyörüségem,
Nap lementén, nap piros sugarán,
Amint játszik a lombok sudarán.

Csak ne volna galambok búgása -
Ebben fakad bánatom forrása;
Mert ha látom szép páros voltokat,
Megsiratnom kell árva magamat.','Járnak, kelnek sokan zöld erdőben;
Vagyon a nap épen lemenőben.
Rózsákat fest utósó sugára
Dombtetőre, lombok sudarára.','Mezőberény, 1842. szeptember-október',1842,'1842',array['Természet']::text[],'{}'::text[],false,50,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-06','petofi','K... Vilmos barátomhoz','Katonának számüzött balvégzetem,
S kétszer élt a szép tavasz a ligeten,
A ligeten, oh de nem e szív fölött,
Míg sorsomnak rabbilincse megtörött.

Mégis - bár a léleksujtó vész miatt,
Mely emésztő hatalommal rám szakadt,
Keservesen megsiratni van okom -
E két tavaszt megsiratni nem fogom.

Hű bajtárs, e két diszetlen kikelet
Tőn enyémmé mindörökre tégedet;
S nem két évet, volna kettő életem:
Érted adnám mind a kettőt szívesen.

Én tudom, mit érsz te nékem, jóbarát!
Jó, minőt az isten többé sosem ád;
Te valál, ki vélem híven felezéd
A nyomornak végső falatkenyerét.

E falattal nékem adtad lelkedet,
E falattal lelkünk összeköttetett;
És nincsen hely, nincs erőszak, nincs idő,
Szent frigyünk szép kötelét eltéphető.

S amint nincs hely, sem erőszak, sem idő,
Szent frigyünk szép kötelét eltéphető:
Nincs is ember, aki oly két szívre lel,
Mely egyezzen, mint egyez e két kebel.

Minket egy sors fondor kénye hányt-vetett,
Minket egy csillagnak fénye vezetett,
Még szerelmet is egy lénynek áldozánk -
Néked éltünk, érted égtünk, jó hazánk!

Oh, midőn a két közember homlokát
Néma bánat mély redői ráncolák:
Aki látta, nem gondolta, jól tudom,
Hogy keservünk téged gyászol, drága hon!

És ha néha jobb időkben a pohár
Bútemetni köztünk kézről kézre járt:
Ott is a hon éltetését zengte szánk,
Ott is a hon megvetőit átkozánk.

Messze vagy most, messze tőlem, jóbarát!
De ne nyomd el a reménynek szép szavát,
Mely hitetve súgja, hogy megjő a kor,
Hol szivünk hév ölelés közt összeforr.

S él az isten, s tudni fogja, hogyha él:
Mit szenvedtem, s te bajtárs, mit szenvedél;
Él az isten, aki annyi bánatért
Tán megadja akkor a várt pályabért.','Katonának számüzött balvégzetem,
S kétszer élt a szép tavasz a ligeten,
A ligeten, oh de nem e szív fölött,
Míg sorsomnak rabbilincse megtörött.','Mezőberény, 1842. szeptember-október',1842,'1842',array['Természet','Haza']::text[],array['tavasz']::text[],false,51,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-07','petofi','Hortobágyi kocsmárosné...','Hortobágyi kocsmárosné, angyalom!
Tegyen ide egy üveg bort, hadd iszom;
Debrecentől Nagy-Hortobágy messze van,
Debrecentől Hortobágyig szomjaztam.

Szilaj nótát fütyörésznek a szelek,
Lelkem, testem majd megveszi a hideg:
Tekintsen rám, kocsmárosné violám!
Fölmelegszem kökényszeme sugarán.

Kocsmárosné, hej hol termett a bora?
Savanyú, mint az éretlen vadalma.
Csókolja meg az ajkamat szaporán,
Édes a csók, megédesűl tőle szám.

Szép menyecske... savanyú bor... édes csók...
Az én lábam idestova tántorog;
Öleljen meg, kocsmárosné édesem!
Ne várja, míg itt hosszában elesem.

Ej galambom, milyen puha a keble!
Hadd nyugodjam csak egy kicsit fölötte;
Úgyis kemény ágyam lesz az éjszaka,
Messze lakom, nem érek még ma haza.','Hortobágyi kocsmárosné, angyalom!
Tegyen ide egy üveg bort, hadd iszom;
Debrecentől Nagy-Hortobágy messze van,
Debrecentől Hortobágyig szomjaztam.','Hortobágy, 1842. október',1842,'1842',array['Szerelem']::text[],'{}'::text[],false,52,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-08','petofi','Hazámban','Arany kalásszal ékes rónaság,
Melynek fölötte lenge délibáb
Enyelgve űz tündér játékokat,
Ismersz-e még? oh ismerd meg fiad!

Rég volt, igaz, midőn e jegenyék
Árnyékain utószor pihenék,
Fejem fölött míg őszi légen át
Vándor darúid V betűje szállt;

Midőn az ősi háznak küszöbén
A búcsu tördelt hangját rebegém;
S a jó anyának áldó végszavát
A szellők már régen széthordozák.

Azóta hosszu évsor született,
És hosszu évsor veszte életet,
S a változó szerencse szekerén
A nagyvilágot összejártam én.

A nagyvilág az életiskola;
Verítékemből ott sok elfolya,
Mert oly göröngyös, oly kemény az ut,
Az ember annyi sivatagra jut.

Ezt én tudom - mikép nem tudja más -
Kit ürömével a tapasztalás
Sötét pohárból annyiszor kinált,
Hogy ittam volna inkább a halált!

De most a bút, a hosszu kínokat,
Melyektől szívem oly gyakran dagadt,
És minden szenvedés emlékzetét
Egy szent öröm könyűje mossa szét:

Mert ahol enyhe bölcsőm lágy ölén
Az anyatejnek mézét ízlelém:
Vidám napod mosolyg ismét reám,
Hű gyermekedre, édes szép hazám!','Arany kalásszal ékes rónaság,
Melynek fölötte lenge délibáb
Enyelgve űz tündér játékokat,
Ismersz-e még? oh ismerd meg fiad!','Dunavecse, 1842. október',1842,'1842',array['Haza','Gyermekkor']::text[],'{}'::text[],false,53,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-09','petofi','A bujdosó','Mit nekem hab! mit nekem vész!
Én nem félem haragát,
Kebelemnek pusztaságit
Száz vihar rohanja át.

Rajta! gyorsan evezőhöz,
Talpra, reszkető legény!
Bár toronnyá nő a hullám,
A túlpartra szállok én.

Éj borong ott, sűrü ködnek
Kétségbarna éjjele;
Lyány! temetve mindörökre
Legyen emléked bele,

Ki ez égő szerelemmel
Enyelegve játszhatál,
Ki hűséget esküvél, és
Oh! ki mégis megcsalál.

Messze tűnnek már a partok.
Messze tűn a gyászvidék.
Hol szivemnek béke, csönde
Romhalomba dönteték:

Tűnjön is nagy messze tőlem,
Hogy ne légyen semmi jel,
Mely a multat, érzeményim
Háborítni, költse fel.

Hah! mi kép leng a ködéjben?
Bájoló mint a tavasz...
Szőke fürttel... kék szemekkel...
Hűtelen lyány, képed az!

Nincs tehát a nagyvilágon,
Nincs hely, csalfa szép alak!
Hol sebemre ír csepegjen,
Hol feledni tudjalak?','Mit nekem hab! mit nekem vész!
Én nem félem haragát,
Kebelemnek pusztaságit
Száz vihar rohanja át.','Dunavecse, 1842. október',1842,'1842',array['Szerelem','Természet']::text[],'{}'::text[],false,54,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-10','petofi','Furcsa történet','"Öcsémuram, vigyázzon magára,
Vagy inkább az oldalbordájára;
Fiatal is, szép is a menyecske -
Ugy segéljen, kutya van a kertbe''."

''Bátyámuram, mit nem kell hallanom?
Szomorú az eset, ha úgy vagyon;
No de míg másnak fúja kásáját,
Meg ne égesse a maga száját.''

"Öcsémuram! mit gondol, az égre?
Az én öregem ezt már túllépte..."
''Hja, a sót vén kecske is megnyalja.
Hanem ez csak ugy van mondva, tudja.''

Így az agg szomszéd jó indulatja
Öccseurát gyakran látogatja;
S sosem hiányzik ilyetén lecke:
Fiatal is, szép is a menyecske.

Történik, hogy a jó szomszéd bátya
Öccs''urától elmarad sokára.
Megtudni, hogy mi ennek az oka,
Öccseura hozzája ballaga.

S akközben, hogy ballagott hozzája,
Már készült is erősen reája,
Mit feleljen? ha majd szól a lecke:
Fiatal is, szép is a menyecske.

De most ez egyszer a szomszéd bátya
Jó tanácsával elő nem álla;
Hanem, ülvén a kemence mellett,
Nagy szomorún ilyen szókat ejtett:

"Öcsémuramnak igaza vala,
Mikoriban azt mondotta, hogy a..."
S felsikolt felesége magzatja,
S a jó öreg - mit tegyen? - ringatja.','"Öcsémuram, vigyázzon magára,
Vagy inkább az oldalbordájára;
Fiatal is, szép is a menyecske -
Ugy segéljen, kutya van a kertbe''."','Dunavecse, 1842. október',1842,'1842',array['Család']::text[],'{}'::text[],false,55,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-11','petofi','Felköszöntés','Miljom átok! bort a billikomba,
Részegítő, lánghullámu bort!
Mely keservet és bút martalékul
A felejtés örvényébe hord.

Bort öblébe váltig a kehelynek.
Bort elémbe szakadatlanúl!
Idenézzen a puszták homokja,
És ha nem tud inni, megtanúl.

Kedvben ég e csont velője máris,
És eremben a kéj habja forr;
Üdv neked, te mámorok homálya!
Üdv neked, te mámor anyja, bor!

Hah, e kancsó a mesés világnak
Feneketlen hordaja talán?
Bort belé! mert nem szivelhetem, ha
Puszta szájjal ásitoz reám;

Bort belé! hogy felköszöntsön ajkam -
Éljen a nemes keblű barát,
Ki, midőn a vész harangja zúgott,
Szent hűséggel nyujtá jobb karát;

Éljen a világ dicső folyása...
És az élet... és a szép világ...
S az igazság védpalástja, mely az
Üldözöttnek menedéket ád;

Éljen a sziv biztató vezére,
A varázsdalt pengető remény;
Éljen a menny, a pokol és minden,
Minden éljen... oh csak vesszek én!','Miljom átok! bort a billikomba,
Részegítő, lánghullámu bort!
Mely keservet és bút martalékul
A felejtés örvényébe hord.','Pápa, 1842. november 1.',1842,'1842',array['Természet']::text[],'{}'::text[],false,56,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-12','petofi','Vadonban','Éj leng alá a mély vadonra,
S az út majd jobb-, majd balra tér;
Lépteim bolyongva tévedeznek -
Ki lesz előttem hű vezér?

A menny ivén ugyan fölöttem
Ragyognak égő csillagok,
De vajh talál-e célra pályám,
Ha lángjaiknak hinni fog?

Az égi fények ezredénél
A lyányszem tündöklőbb vala,
S mégis, ki hittem súgarának,
Haj engem mégis megcsala!','Éj leng alá a mély vadonra,
S az út majd jobb-, majd balra tér;
Lépteim bolyongva tévedeznek -
Ki lesz előttem hű vezér?','Veszprém, 1842. november',1842,'1842',array['Szerelem']::text[],'{}'::text[],false,57,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-13','petofi','Első szerepem','Szinésszé lettem. Megkapám
Az első szerepet,
S a színpadon először is
Nevetnem kelletett.

Én a szerepben jóizűn
S szivemből neveték;
Pályámon, oh ugyis tudom,
Leend ok sírni még.','Szinésszé lettem. Megkapám
Az első szerepet,
S a színpadon először is
Nevetnem kelletett.','Székesfejérvár, 1842. november',1842,'1842',array['Természet']::text[],'{}'::text[],false,58,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1842-184201-14','petofi','Disznótorban','Nyelvek és fülek... csend,
Figyelem!
Szóm fontos beszédre
Emelem.

Halljátok, mit ajkim
Zengenek;
Egyszersmind az ég is
Hallja meg.

Hosszan nyúljon, mint e
Hurkaszál,
Életünk rokkáján
A fonál.

Valamint e sültre
A mi szánk:
Mosolyogjon a sors
Szája ránk;

S pályánk áldásával
Öntse le,
Mint e kását a zsír
Özöne.

S életünk fölé ha
A halál
Romboló torát meg-
Ülni száll:

Egy gömböc legyen a
Magas ég,
És mi a gömböcben
Töltelék!','Nyelvek és fülek... csend,
Figyelem!
Szóm fontos beszédre
Emelem.','Székesfejérvár, 1842. november 18.',1842,'1842',array['Természet']::text[],'{}'::text[],false,59,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-01','petofi','Pálnapkor','Itt van a tél, a hideg tél
Közepe,
Zúgolódik az idő kinn
Ízibe.

Zúgolódjék! egyéb dolga
Nincs neki;
Úgy akarja, hagyjuk kedvét
Tölteni.

Hisz nekünk ez úgysem árthat,
Igaz-e?
Meg nem fázunk - jó meleg van
Idebe.

A kandallón pattog a fa,
Ég a tűz,
S a kulacsnak kotyogása
Fagyot űz.

Hát a csók piros menyecskék
Ajakán?
Az hevíti ám az embert
Igazán.

Háborogj hát, istenadta
Ideje!
Föl sem vesszük... víg barátim,
Igaz-e?','Itt van a tél, a hideg tél
Közepe,
Zúgolódik az idő kinn
Ízibe.','Kecskemét, 1843. január 25.',1843,'1843',array['Természet']::text[],array['tel']::text[],false,60,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-02','petofi','Dínomdánom','Hegedűszó, furulyaszó, cimbalom...
Van-e még, kit a búbánat terhe nyom?
Akinél van, igazítsa el a bút,
Nehogy neki mutassuk meg, hol az út.

A búbánat gonosz vendég, rosz madár,
A kebelbe életet, vért lopni jár.
A búbánat szívet rágó ürgefi:
Borral lehet, borral kell kiönteni.

A bor éleszt, a bor éget, mint a csók -
Csókot, lyányka, hosszut, édest, lángolót!
Csókod lángja, mint a napfény, mennyei,
Mely az élőfán a lombot neveli.

Lombon fakad, lombon fejlik a virág,
Lomb ne''kül, virág ne''kül mit ér az ág?
Hogyha pusztán s szárazon a törzsök áll,
Hamar éri a sodró vész, a halál...

Hah halál, te nagy kérdésjel, melyre még,
Nem felele sem idő, sem bölcseség,
Mivel áldasz, mivel versz a sír után?
Van-e ott is élet és bor és leány?

Mit törődöm, mit tünődöm még sokat!
Élek most, és ölelem, mi élvet ad;
S mi ad élvet, hogyha nem bor és leány?
Éljen a lyány, éljen a bor... húzd, cigány!','Hegedűszó, furulyaszó, cimbalom...
Van-e még, kit a búbánat terhe nyom?
Akinél van, igazítsa el a bút,
Nehogy neki mutassuk meg, hol az út.','Kecskemét, 1843. január',1843,'1843',array['Természet','Szerelem','Elmúlás']::text[],'{}'::text[],false,61,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-03','petofi','Üresen áll már a kancsó...','Üresen áll már a kancsó, bort bele!
Ide hamar a javából, be vele!
Boncidáig folyjon a bor, mint tenger,
Ki megállhat még a lábán, nem ember.

Jer ölembe, kincsem, rózsám, itt a bor!
Ha megittad, csókra kerül majd a sor:
Igyál tehát, ürítsd ki, mert szomjazom;
De csókodat, hű csókodat, galambom!','Üresen áll már a kancsó, bort bele!
Ide hamar a javából, be vele!
Boncidáig folyjon a bor, mint tenger,
Ki megállhat még a lábán, nem ember.','Kecskemét, 1843. január',1843,'1843',array['Szerelem']::text[],'{}'::text[],false,62,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-04','petofi','Farkaskaland','''Pajtás, te ettél, véres a fogad;
S mi szenvedünk éhségi kínokat.

Mogorva a tél, puszta a határ,
Rajt a vihar légparipája jár;

Csak ember és állatnak nincs nyoma...
De most beszélj, hol volt a lakoma?''

Igy kérdi társát a farkassereg,
Kit érkezéskor üdvezeltenek.

A jóllakott nem késik szólani,
És tőle ily beszédet hallani:

"Ott a vityilló pusztaközepen,
Él a juhász és felesége benn.

A ház mögött pedig terűl az ól,
Honnan juhoknak bégetése szól.

E lakhoz éjszakának idején
Két útazó suhant. Egy úrfi s én.

A pásztornéra titkon foga fájt
Az úrfinak, s én éhezém a nyájt.

Ott sompolygott ő a kunyhó előtt.
Juhot nem kaptam én... megettem őt."','''Pajtás, te ettél, véres a fogad;
S mi szenvedünk éhségi kínokat.
Mogorva a tél, puszta a határ,
Rajt a vihar légparipája jár;','Kecskemét, 1843. január',1843,'1843',array['Természet']::text[],'{}'::text[],false,63,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-05','petofi','Könyeim','1

Áldás reátok, ligetemben
Odább iramló csermelyek!
Utaitokon a szép tavasznak
Himes virági termenek.

Ez arc fölött is két patak foly,
Folytok, szerencsétlen könyek!
De halvány pályátok körében
Virágok ah nem zsengenek.

2

Forró sugárokat
Lövel a nyári nap;
Sugári lánghevén
Patak, folyó apad.

O forró nyári nap,
O lángoló sugár,
Könyűmnek árjait
Apasztanád ki bár!

3

Eljött az ősz; a part virága
Hervadva hull a csermelyár habjába.
Eljött a bú; az élet kéje
Kihalva fúl a könyek özönébe.

4

O télnek dermesztő hidegje!
Mely a folyókat lebilincseléd;
O télnek dermesztő hidegje,
Bilincseld le szememnek csepkönyét!

5

Fuss, oh patakcsa,
Fuss csüggedetlen;
Megnyúgoszol majd
A tengerekben.

Hullasz könyüm, hullj;
O a halálban
Számodra is tán
Megnyúgovás van.','1
Áldás reátok, ligetemben
Odább iramló csermelyek!
Utaitokon a szép tavasznak','Kecskemét, 1843. február',1843,'1843',array['Természet']::text[],'{}'::text[],false,64,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-06','petofi','Halálvágy','Sírt nekem, sírt és koporsót,
Mélyen fekvőt föld alatt!
Hol nem élnek érzemények,
Hol nincs többé gondolat.

Oh fej, oh kebel, te kettős
Átok életem felett!
Mért kinozni lángcsapásu
Ostorokkal engemet?

Mért a vágy e lázas agyban,
Szállni csillagok fölé?
Hogyha őt a sors haragja
Földön csúszni rendelé.

Vagy ha száll e vágyak szárnya,
Mért nincs rajta égi toll?
Mely vigyen, hol a magasban
Halhatatlanság honol;

És ha puszta nékem üdvben
E világ, mért a kebel,
Megteremtve, hogy lakóul
Örömet fogadjon el?

Vagy ha van szív, mely a kéjben
Föllobogva érzene,
Mért reám e jégtekintet?
Boldogságnak istene!

Sírt nekem, sírt és koporsót,
Mélyen fekvőt föld alatt,
Hol nem élnek érzemények,
Hol nincs többé gondolat...','Sírt nekem, sírt és koporsót,
Mélyen fekvőt föld alatt!
Hol nem élnek érzemények,
Hol nincs többé gondolat.','Kecskemét, 1843. február',1843,'1843',array['Elmúlás']::text[],'{}'::text[],false,65,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-07','petofi','Az első dal','Kit a dal istene
Szent csókjával füröszt,
Első vagyok, hazám,
Színházad népe közt.

Zengjen tehát a lant!
S legelső énekem,
Pályámnak társai,
Tinéktek szentelem.

Az érzet kútfeje
A dagadó kebel;
Dalomnak hangjai
Onnan szakadtak el.

S mint szívnek gyermeki
A szívbe vágynak ők;
Engedjétek nekik
Honokba menniök. - -

Ki a müvészet e
Szent templomába lép,
Az, illő, hogy legyen
Főben, kebelben ép;

Az elme éjjele
S a megromlott kebel
E fának ágain
Gyümölcsöt nem nevel.

Két csillag sugara
Derengje át egünk:
Hon és erény legyen
E két csillag nekünk.

Nem kell a színpadot
Tekinteni csak úgy,
Mint hol mindennapi
Kenyérhez nyílik út;

A színpad célja nagy,
A színpad célja szent:
Ez a szív parlagán
Erkölcsöt fejt, teremt.

Azért érzelmeink
Gyulassza tiszta tűz,
Mely minden szennyet a
Kebelből számkiűz;

Mert várni lehet-e,
Hogy romlott föld alatt
A mag termő legyen
Gazdag kalászokat?

Föl hát! és míg a szem
Csak egy sugárt lövel,
Előle a magas,
Szent cél ne vesszen el.

S ha ez lesz életünk:
Édes jutalmat ad
A hon áldó szava
S a nyúgodt öntudat.','Kit a dal istene
Szent csókjával füröszt,
Első vagyok, hazám,
Színházad népe közt.','Kecskemét, 1843. március 5-e előtt',1843,'1843',array['Haza']::text[],'{}'::text[],false,66,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-08','petofi','Jövendölés','"Mondád, anyám, hogy álmainkat
Éjente festi égi kéz;
Az álom ablak, melyen által
Lelkünk szeme jövőbe néz.

Anyám, álmodtam én is egyet,
Nem fejtenéd meg, mit jelent?
Szárnyim növének, s átröpűltem
A levegőt, a végtelent."

''Fiacskám, lelkem drága napja,
Napomnak fénye! örvendezz;
Hosszúra nyujtja élted isten,
Álmodnak boldog titka ez.'' -

És nőtt a gyermek, lángra lobbant
Meleg keblén az ifjukor,
S a dal malasztos enyh a szívnek,
Midőn hullámzó vére forr.

Lantot ragadt az ifju karja,
Lantjának adta érzetét,
S dalszárnyon a lángérzemények
Madárként szálltak szerteszét.

Égig röpűlt a bűvös ének,
Lehozta a hír csillagát,
És a költőnek, súgarából
Font homlokára koronát.

De méreg a dal édes méze;
S mit a költő a lantnak ad,
Szivének mindenik virága,
Éltéből egy-egy drága nap.

Pokollá lett az érzelemláng,
És ő a lángban martalék;
A földön őt az életfának
Csak egy kis ága tartja még.

Ott fekszik ő halálos ágyon,
Sok szenvedésnek gyermeke,
S hallá, mit a szülő bus ajka
Kínjának hangján rebege:

''Halál, ne vidd el őt karomból,
Ne vidd korán el a fiut;
Soká igérte őt éltetni
Az ég... vagy álmunk is hazud?...''

"Anyám, az álmok nem hazudnak;
Takarjon bár a szemfödél:
Dicső neve költő-fiadnak.
Anyám, soká, örökkön él."','"Mondád, anyám, hogy álmainkat
Éjente festi égi kéz;
Az álom ablak, melyen által
Lelkünk szeme jövőbe néz.','Kecskemét, 1843. március 5-e előtt',1843,'1843',array['Természet','Család']::text[],'{}'::text[],false,67,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-09','petofi','Jön az ősz...','Jön az ősz, megy a gólya már,
Hideg neki ez a határ;
Röpűl, röpűl más országba,
Hol jobban süt a nap rája.

Hej, van oka a gólyának,
Hogy más hazát néz magának;
De, galambom, hogy elhagytál,
Nem t''om, mi okot találtál.

Hív voltam én hozzád mindig,
Elejétől utójáig,
Nem volt szivemben ősz, tavasz,
Érted, mint a nyár, égett az.

S vajjon akihez röpűltél,
Nem lesz-e annak szivén tél?
Megeshetik, szép galambom,
Noha neked nem kivánom.

Mert a gólya ha visszaszáll,
Virító szép tavaszt talál;
Hej, de mire te visszaszállsz,
Csak puszta sírhalmot találsz.','Jön az ősz, megy a gólya már,
Hideg neki ez a határ;
Röpűl, röpűl más országba,
Hol jobban süt a nap rája.','Kecskemét, 1843. március 14-e előtt',1843,'1843',array['Természet']::text[],array['osz']::text[],false,68,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-10','petofi','Kakasszóra hajnal ébred...','Kakasszóra hajnal ébred,
Én lányokkal nem beszélek.
Mert ha szólok őhozzájok,
Hajnal lesz a két orcájok.

Így valaki azt gondolná,
Én is kakas vagyok talán;
S hej, a kakas hamis madár,
Untalan más fészekhez jár.

Pedig én kakas nem vagyok,
Hanem filemile vagyok,
Egy a fészkem, egy a párom,
Egyért élek a világon.','Kakasszóra hajnal ébred,
Én lányokkal nem beszélek.
Mert ha szólok őhozzájok,
Hajnal lesz a két orcájok.','Kecskemét, 1843. március 14-e előtt',1843,'1843',array['Természet']::text[],'{}'::text[],false,69,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-11','petofi','Lopott ló','Mint a porszem szélvész
Fuvatán,
Röpül a legény gyors
Paripán.

''Honnan, atyafi, oly
Hevenyén?''
"Pusztáról csikóval
Jövök én.

A nyerítő ménes
Ott legel;
Pej csikómat onnan
Loptam el.

Túri vásár nincsen
Messze már;
Szegénylegény oda
Lovon jár."

''Ej, nem ugy, jó földi,
Nem ugy ám!
Adja kend csak vissza
Paripám.

Enyim a ménes, mely
Ott legel,
A csikót kend tőlem
Lopta el.'' -

De szavára nem hajt
A betyár;
Őkegyelme már jó
Tovajár.

Mégis a gazdának
Vígaszul,
Hátrafordulván, így
Válaszol:

"Föl se vegye kárát,
Gazduram;
Hiszen úgyis elég
Lova van.

Hej, csak egy szivet bírt
E kebel -
Azt is a kend lyánya
Lopta el."','Mint a porszem szélvész
Fuvatán,
Röpül a legény gyors
Paripán.','Kecskemét, 1843. március',1843,'1843',array['Természet']::text[],'{}'::text[],false,70,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-12','petofi','Emlény','A szinész utain virág s tövis terem,
A szinész élete öröm és gyötrelem.
Bűvös szellemkezek vezérlik lépteit,
Leplezve gondosan az élet terheit.
Szép álmot álmodik: öröklő hirnevet,
Szellem bejárja a földet és eget.
Bú- s kéjnek egyaránt feltárja kebelét,
Részvéttel osztja meg a szenvedő könyét,
S bár megvetett, szegény, de nem boldogtalan,
Amig szive dobog s mig pártfogója van,
Mert pártfogója az, mi neki üdvöt ád,
Szeretni lángolón ohajtott pályáját.
S még a hir nevéről
Szép dolgokat beszél,
Sirhalma pázsitán
Zokogva sír a szél.','A szinész utain virág s tövis terem,
A szinész élete öröm és gyötrelem.
Bűvös szellemkezek vezérlik lépteit,
Leplezve gondosan az élet terheit.','Kecskemét, 1843. március 23-30. között',1843,'1843',array['Természet']::text[],'{}'::text[],false,71,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-13','petofi','Víz és bor','Le a tenger fenekére
Merül a halász,
Lent a tenger fenekében
Gyöngyöket halász.
Nekem a boros pohárnak
Öble tengerem,
S gyöngy ha van tán dalaimban,
Az csak ott terem.

Bűnnek éje ült a földön.
Jött a vízözön.
A víz által a bűn éje
Elseperve lön.
Búnak éje ül szivemben;
A bú éjjelét
- Bennem a víz tehetetlen! -
Csak bor mossa szét.

Nyári hévben a virágszál
Sanyarogva nő;
A virágot új életre
Kelti langy eső.
Csüggedésben, tikkadásban
Langy esőm a bor;
Permetegje enyhe csöpjén
Vérem ujra forr.

Tettetés-e, vagy belösztön,
Vagy akármi más?
Csakhogy a halottra könyet
Ejteni szokás;
Engemet víz ott se érjen,
S már ha sírni kell,
Sírja hát hideg poromra
Könyét borkehely.','Le a tenger fenekére
Merül a halász,
Lent a tenger fenekében
Gyöngyöket halász.','Kecskemét, 1843. március',1843,'1843',array['Természet']::text[],'{}'::text[],false,72,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-14','petofi','Én','A világ az isten kertje;
Gyom s virág vagytok ti benne,
Emberek!
Én a kertnek egy kis magja,
De az úr ha pártom fogja:
Benne gyom tán nem leszek.

Tiszta e kebelnek mélye;
Égi kéz lövelt beléje
Lángokat.
És a lángok szűzen égnek
Szent oltárúl az erénynek
El nem romlott szív alatt.

Nem építek sors kegyére,
Tűrök, mit fejemre mére,
Jót, roszat;
Mit ma ád, elvészi holnap;
Majd megadja, amit elkap;
Jellemképe: változat.

Mint a róna, hol születtem,
Lelkem útja tetteimben
Egyenes!
Szavaimmal egy az érzet,
Célra jutni álbeszédet
Tétovázva nem keres.

És az ég szivem földébe,
Drága fádat ülteté be,
Szerelem!
Koszorúba fűzöm ágit,
Koszorúm szerény virágit
A hazának szentelem.','A világ az isten kertje;
Gyom s virág vagytok ti benne,
Emberek!
Én a kertnek egy kis magja,','Kecskemét, 1843. március',1843,'1843',array['Természet']::text[],'{}'::text[],false,73,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-15','petofi','Az utósó alamizsna','A költő és a sorsharag
Egy anyaméhből született;
Ikertestvérek voltak ők,
Együtt bolygák az életet.

Fa, mint most, akkor is virúlt.
Árnyában sok megnyúgodott;
De használt a költőnek is:
Ágáról tört koldúsbotot.

S ezek valának társai:
Koldúsbot és a sorsharag;
Elhagyja minden hűtlenűl,
Csak e kettő, mi hű marad.

És lantja! lantja hova lőn?
Hisz a költőnek lantja van...
Igen bizony, volt lantja is,
Mely zenge bűvösbájosan.

Megpenditette húrjait
Mennydörgő éjben egykoron.
S a mennydörgésnek ágyuja
Elszenderűlt e hangokon.

S az ég, a barna, haragos,
Midőn danáját hallaná:
Feledni kezdé a boszút,
S csillagmosollyal néze rá.

És a költő megéhezett,
És emberek közé mene.
Tudá: az emberszív kemény;
De vélte: lágyit a zene.

S mely a vihart elaltatá,
És földeríté az eget,
Elandalító húrjain
Az ének újra zenegett.

De melyet ég, vihar megért,
A dalt ember nem érti meg...
És ím a lant elszégyenűl,
S fájdalmában kettéreped. -

Ez volt a lant története.
A költőbül tovább mi lett?
Soká nyögé - nem tudni, hol? -
Az inségterhes életet.

Egy újabb nemzedék előtt
Évek multán megjelenék.
Nem őszült ő meg... fürteit
A gond, a bú kitépte rég.

"Egy-két garast, egy-két garast!"
Halk hangja így esedeze;
S mint szélringatta száraz ág,
Remegve nyúlt ki két keze.

A részvét megkérdezte őt:
''Ki vagy, nyomornak embere!
Kit sujtoló istenharag
Ily könyöretlen megvere?''

S nevét elmondja, s újra esd:
"Egy-két garast..." - ''Megállj, jövel,
Örök dicsőség gyermeke!
A bőség szarva födjön el.

Neved ragyog, miként az ég
Csillagsugáros éjfelen;
Mely egykor árván hangozék,
Bámulja lantod a jelen.

Jövel tehát! jövel, cserélj
Bársonyt e koldusrongy helyett;
Borostyán koronázza főd,
Dús asztalnál legyen helyed!''

"O szép beszéd.. o köszönet!
De én semmit sem éhezem,
És nincsen is szükség reá,
Hogy elcseréljem rongymezem.

És a borostyán... oh mi szép,
Mi jó lehet lángifjunak;
De száraz törzsön a galyok
Többé meg nem fogamszanak.

Hanem ha dobsz egy-két garast:
Fogaddsza hálaszózatom;
Mert pénzre vár az asztalos...
Koporsómat csináltatom."','A költő és a sorsharag
Egy anyaméhből született;
Ikertestvérek voltak ők,
Együtt bolygák az életet.','Pest, 1843. április 10-e előtt',1843,'1843',array['Természet']::text[],'{}'::text[],false,74,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184301-16','petofi','Szeget szeggel','Jaj, a hátam, jaj a hátam
Odavan!
Szomszéd bácsi kiporozta
Csúfosan.
Átkozott a görcsös fütykös
Somnyele!
Mellyel engem oly pogányúl
Csépele.

Mért is tart hát kertet s benne
Körtefát?
És az isten rá gyümölcsöt
Minek ád?
Csábitólag kandikált a
Körte rám;
Csábjait ki már sehogysem
Állhatám.

Átugortam a palánkon -
Átesém!
Hogy megingott bele májam
És vesém.
S nem elég ez; szomszéd bácsi
Rajtakap,
S akkor jött még a valódi
Haddelhadd.

Én teremtőm! mért is értem
E napot?
Megrakott, hogy minden csontom
Ropogott.
Nesze, monda, nesze másik,
Harmadik!
És a mindentudó tudja,
Hányadik.

Jelen volt a holdvilág a
Lakzinál;
Búsan nézte: szomszéd bácsi
Mit csinál.
Fellegekből vett magára
Gyászmezet,
És megosztva szenvedésem
Könnyezett.

Ő, csak ő nem könyörűle
Egyedűl;
Három a tánc! monda, s egyre
Hegedűlt, -
Hegedűlt a bottal hátam
Közepén,
Keservesen, siralmasan
Jártam én.

...De''szen jól van! kiheverem
Én e bajt.
S visszakapja még a kölcsönt,
Vissza majd.
Tudjuk, hányat vert az óra,
Tudjuk ám!
Ön is rak a tüzre rosz fát,
Bácsikám.

Ablakunkhoz estenként mért
Sompolyog?
Vettem észre, hányadán van
A dolog.
Más szemében ő a szálkát
Megleli,
S az övében a gerendát
Feledi.

A deákné vászonánál
Ő se'' jobb:
Engem dönget a lopásért
S szinte lop;
Lopni jár ő, csókot lopni
Nénihez,
Míg anyánk a bibliában
Levelez.

Tegye lábát ablakunkhoz
Ezután:
Fogadom, nem nézek által
A szitán.
Megugratni vagy anyánkat
Hívom át,
Vagy leöntöm dézsa vízzel
A nyakát!','Jaj, a hátam, jaj a hátam
Odavan!
Szomszéd bácsi kiporozta
Csúfosan.','Puszta-Palota, 1843. április',1843,'1843',array['Szerelem']::text[],'{}'::text[],false,75,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-17','petofi','Barátimhoz','Nos, fiúk, nem szólt a szarka
Házfödélteken?
Vagy ki álmodá meg, hogy ma
Vendégtek leszen?

De mi a kő! mért e hosszu
Méla bámulás?
H''sz én vagyok, ha nem csalódom,
Én és senki más.

Vagy feledve már talán a
Régi jóbarát?
Nem hihetem, hogy reátok
Illenék e vád.

A szövetség, melynek szála
Minket összefont,
Áll, amíg csak vért bir a szív
És velőt a csont.

No de kissé meglepett tán
Jöttöm úgyebár?
Hja, öcséim, velem a sors
Furcsa táncot jár.

Köztem s közte folyton-folyva
Tart a háború,
S majd lenyom, majd, mint a pelyhet,
Végtelenbe fú.

De azért nem csüggedünk ám,
Aki lelke van!
Szembeszállok őkelmével
Bátran, szilajan.

S tán ha látja sors komám, hogy
Csüggedés nem ért:
Egykor annál bőkezűbben
Nyujtja majd a bért...

Eh, de mit most okoskodni!
Csapjatok kezet;
Jóbarát markába csapni
Kedves élvezet.

S mely bennünket ily váratlan
Együvé hozott,
Áldomással ünnepeljük
A pompás napot!','Nos, fiúk, nem szólt a szarka
Házfödélteken?
Vagy ki álmodá meg, hogy ma
Vendégtek leszen?','Pápa, 1843. április',1843,'1843',array['Szerelem']::text[],'{}'::text[],false,76,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-18','petofi','Az én mátkám','Istenem, be várva-várom
Azt az órát, amidőn,
Kit nekem rendelt a végzet,
A leány ölembe jön.

És ugyan ki és minő lesz
Majd az én szerelmesem?
Ugy sovárgok tudni, mint még
Nem sovárgá senki sem.

Szőke, barna lesz-e fürte?
Szeme kék vagy fekete?
Felnyúló-e, mint a cédrus,
Gömbölyű-e termete?

Szép a szőke, szép a barna,
Mind a kettő szép, ha szép;
Hátha még a bájjal aztán
A jóság is frigybe lép!

Isten, ilyet adjsza nékem,
S nem bánom - csak ilyet adj -
Akár szőke, akár barna,
Akár kicsiny, akár nagy!','Istenem, be várva-várom
Azt az órát, amidőn,
Kit nekem rendelt a végzet,
A leány ölembe jön.','Pozson, 1843. május',1843,'1843',array['Szerelem']::text[],'{}'::text[],false,77,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-19','petofi','Távolból','Kis lak áll a nagy Duna mentében;
Oh mi drága e lakocska nékem!
Könnyben úszik két szemem pillája,
Valahányszor emlékszem reája.

Bár maradtam volna benne végig!
De az embert vágyai vezérlik;
Vágyaimnak sólyomszárnya támadt,
S odahagytam őslakom s anyámat.

Kínok égtek a szülőkebelben,
Hogy bucsúmnak csókját ráleheltem;
S kínja lángi el nem aluvának
Jéggyöngyétől szeme harmatának.

Mint ölelt át reszkető karával!
Mint marasztott esdeklő szavával!
Oh, ha akkor látok a világba:
Nem marasztott volna tán hiába.

Szép reményink hajnalcsillagánál
A jövendő tündérkert gyanánt áll,
S csak midőn a tömkelegbe lépünk,
Venni észre gyászos tévedésünk.

Engem is hogy csillogó reményem
Biztatott csak, minek elbeszélnem?
S hogy mióta járom a világot,
Bolygó lábam száz tövisre hágott.

...Szép hazámba ismerősök mennek;
Jó anyámnak tőlök mit izenjek?
Szóljatok be, földiek, ha lészen
Útazástok háza közelében.

Mondjátok, hogy könnyeit ne öntse,
Mert fiának kedvez a szerencse - -
Ah, ha tudná, mily nyomorban élek,
Megrepedne a szive szegénynek!','Kis lak áll a nagy Duna mentében;
Oh mi drága e lakocska nékem!
Könnyben úszik két szemem pillája,
Valahányszor emlékszem reája.','Pozson, 1843. május',1843,'1843',array['Természet','Család']::text[],'{}'::text[],false,78,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-20','petofi','Ki vagyok én? Nem mondom meg...','Ki vagyok én? nem mondom meg;
Ha megmondom: rám ismernek.
Pedig ha rám ismernének?
Legalább is felkötnének.

Nincs a fokos a kezemben,
Hogyha kéne verekednem;
Nyerges lovam messze legel,
Nem t''ok futni, ha futni kell.

Hogy is tudnék futni mostan?
Mikor a fejem televan;
Nem csak fejem, de szívem is -
A bor meg a leány hamis.

Ha elhagyom galambomat,
Kialuszom mámoromat,
S rajtam ütnek a hadnagyok:
Majd megmondom, hogy ki vagyok!','Ki vagyok én? nem mondom meg;
Ha megmondom: rám ismernek.
Pedig ha rám ismernének?
Legalább is felkötnének.','Pozson, 1843. május',1843,'1843',array['Szerelem']::text[],'{}'::text[],false,79,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-21','petofi','Lánggal égő teremtette...','Lánggal égő teremtette!
Nagy a harag a szívembe'';
Úgy háborgok, úgy hánykodom,
Mintha volnék a Balaton.

Viszontagság az életem,
Ezer bajba keveredem,
Hogyha leányszemem volna,
Egy pár kendőt telesírna.

Eh, a sírás nem kenyerem!
Kinek tetszik, pityeregjen.
Én egy nagyot káromkodom,
Úgy csillapul a haragom.','Lánggal égő teremtette!
Nagy a harag a szívembe'';
Úgy háborgok, úgy hánykodom,
Mintha volnék a Balaton.','Pozson, 1843. május',1843,'1843',array['Szerelem']::text[],'{}'::text[],false,80,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-22','petofi','Szemrehányás','Már ezt föl nem tettem rólad,
Szív barátom!
Te ugyan derék legény vagy,
Amint látom.

Oh, te szív, te szív, te csalfa,
Háladatlan!
Szólj: ki véde annyi baj közt
Szakadatlan?

Sorscsapási buzogányok
Súlya ellen,
Mondd, ki őrze? mondd, ki óva?
Nemde mellem?

Lám, e mellnek bizton voltál
Rejtekében,
Bekeríte csontfalával
Bástyaképen.

S ím, hogy fordult most a kocka,
S a szerencse
Kis szeszélye víg ajakkal
Rád köszönte:

Mostan - ahha, háladatlan! -
Örömödben
Háborogva, zajgva tombolsz
Őröd ellen.

Égsz, dagadsz... alighogy bírom
E keresztet!...
Mellemet majd meggyujtod, majd
Megrepeszted.','Már ezt föl nem tettem rólad,
Szív barátom!
Te ugyan derék legény vagy,
Amint látom.','Pest, 1843. július-augusztus',1843,'1843',array['Természet']::text[],'{}'::text[],false,81,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-23','petofi','Érik a gabona...','Érik a gabona,
Melegek a napok,
Hétfőn virradóra
Aratásba kapok.
Érik szerelmem is,
Mert forró a szivem;
Légy te aratója,
Édes egyetlenem!','Érik a gabona,
Melegek a napok,
Hétfőn virradóra
Aratásba kapok.','Pest, 1843. július-augusztus',1843,'1843',array['Szerelem']::text[],'{}'::text[],false,82,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-24','petofi','Befordúltam a konyhára...','Befordúltam a konyhára,
Rágyujtottam a pipára...
Azaz rágyujtottam volna,
Hogyha már nem égett volna.

A pipám javában égett,
Nem is mentem én a végett!
Azért mentem, mert megláttam,
Hogy odabenn szép leány van.

Tüzet rakott eszemadta,
Lobogott is, amint rakta;
Jaj de hát még szeme párja,
Annak volt ám nagy a lángja!

Én beléptem, ő rám nézett,
Aligha meg nem igézett!
Égő pipám kialudott,
Alvó szívem meggyúladott.','Befordúltam a konyhára,
Rágyujtottam a pipára...
Azaz rágyujtottam volna,
Hogyha már nem égett volna.','Pest, 1843. július-augusztus',1843,'1843',array['Szerelem']::text[],'{}'::text[],false,83,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-25','petofi','Hej nekem hát vigasztalást mi sem ad...','Hej nekem hát vigasztalást mi sem ad?
Bánatomban le kell innom magamat.
Az irgalmát, ide avval a borral!
A bú vagy én, de egyikünk belehal.

Úgysem tetszik ez a világ énnekem;
Sok már, amit életemben szenvedtem,
Nagyon is sok e parányi életre!
Annyi baj közt kinek volna még kedve?

Nem vagyok én gyökeres fa, virágzó,
Hanem vagyok letörött ág, fonnyadó;
Nem vagyok én az örömnek rózsája,
De vagyok a szomorúság gyászfája.

Én előttem ilyen élet nem élet,
Hol az ember de semmit sem remélhet.
Volna bár e pohár borban halálom,
Hogy lehetne bajaimtól megválnom!','Hej nekem hát vigasztalást mi sem ad?
Bánatomban le kell innom magamat.
Az irgalmát, ide avval a borral!
A bú vagy én, de egyikünk belehal.','Pest, 1843. július-augusztus',1843,'1843',array['Természet']::text[],'{}'::text[],false,84,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-26','petofi','L........né','Én alkotóm! mindenható vagy:
Hozd vissza a pillantatot,
Midőn e hölgy a szerelemnek
Első tüzére gyúladott;
Midőn ajkán a vallomásnak
Első, szent hangja reszkete,
S ott én legyek, kit csókra hí föl
Édes kedves tekintete!

S mit adjak érte?... E husz éves
Életnek vedd el tavaszát,
A szép remények tündérföldét,
Mit lelkem a jövőben lát;
S ha nyílik út embernek égbe,
És üdvességet osztasz ott:
E túlvilági üdvességből
Végy el egy drága századot!','Én alkotóm! mindenható vagy:
Hozd vissza a pillantatot,
Midőn e hölgy a szerelemnek
Első tüzére gyúladott;','Pest, 1843. július-augusztus',1843,'1843',array['Szerelem']::text[],'{}'::text[],false,85,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-27','petofi','Kördal','Bús az ember, ha nincs kedve;
Borba van a kedvmag vetve.
Hát azért iszunk mi mindig,
Meg sem állunk tíz-husz pintig.

Van minékünk pincénk, házunk,
Mindazáltal itt tanyázunk,
Itt tanyázunk naphosszában,
Itt tanyázunk a kocsmában.

Itt tanyázunk, mert van nékünk,
Mert van nékünk feleségünk.
Nyelves, szájas mind az asszony;
Rá az ember hogy hallgasson?

Van minékünk egy kis pénzünk,
De a pénzre mi nem nézünk;
Úgyis holtig él az ember,
Költeni ha mer, ha nem mer.

Hát azért csak iddogálunk,
Míg fel nem kötik az állunk,
Iddogálunk naphosszában,
Iddogálunk a kocsmában.','Bús az ember, ha nincs kedve;
Borba van a kedvmag vetve.
Hát azért iszunk mi mindig,
Meg sem állunk tíz-husz pintig.','Pest, 1843. július-augusztus',1843,'1843','{}'::text[],'{}'::text[],false,86,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-28','petofi','Merengés','Jó Petőfi, te sem félhetsz,
Hogy két vállad valahogy
A szerencse áldásának
Nagy terhétől összerogy.

Adománya mindössze is
E lantocska és a dal,
Mit belőle búsan, vígan
Érzelmid játéka csal.

Hátha így találna szólni
Egy tündérvilági hang:
"Nos, fiam, mi kell? jókedvem
Íme mindent megadand."

Mondaná, hogy: "Rád ruházom
A bübájat, a varázst,
Daljaid, mivé kivánod,
Azzá testesülni lásd.

Hogyha kell hír: minden hangod
Egy borostyángally legyen,
Mig Petrarca koszorúja
Nem vet árnyat fürtiden.

- Hisz Petrarca és Petőfi
Félig-meddig már rokon;
Annál inkább osztozhatnak
A borostyánlombokon. -

Hogyha kincs kell: mind megannyi
Gyönggyé válik éneked,
Mígnem gyönggyel rakhatod ki
Gombod, sarkantyúszeged."

Mit felelnél mindezekre,
Mit felelnél, jó fiú?
Tudom én szived bibéjét,
Tudom, a szél honnan fú.

Te bizony csak ezt felelnéd:
Szép a hír és jó a kincs;
És hogy őket ne kivánnám,
Abból ugyan semmi sincs.

De ha már ezermesterré
Engeded, hogy válhatom:
- Van a hírnél, van a kincsnél
Egy igézőbb hatalom;

Mint csillagfüggés az égen
Változatlan, végtelen,
Úgy függ rajta és csak rajta
Vágyban égő kebelem! -

Hadd legyen hát egy lépvessző,
Egy kalitka énekem,
S a legszebb madárt... egy lyányka
Szívét fogja meg nekem.','Jó Petőfi, te sem félhetsz,
Hogy két vállad valahogy
A szerencse áldásának
Nagy terhétől összerogy.','Gödöllő, 1843. augusztus végén',1843,'1843',array['Természet']::text[],'{}'::text[],false,87,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-29','petofi','Temetőben','Fölhangolom olykor a lant idegeit,
Megzengeni téged, o kellemes élet!
- Mert kellemes az, noha sok sebet ejt,
És rengetegekbe nem egy uta téved.

De bármi magasra törekszik a dal,
Bármint csalogassam az életi mézzel:
Mélázva örömtelen hangjaival
Mindenkor a sírban, a sírban enyész el.

Kivánatos a tavasz éke nekem,
Indúlok is olykor örűlni virághoz;
S mig kertbe röpíti sugárit a szem,
Lábam temetői keresztek alá hoz.

Itt élek a szív komoly álmainak
A halk temető morajatlan ölében;
Ákácai lombja rezegve inog,
Hintázza az est fuvalomja szelíden.

A szobrok a domboru hant elején
Mindannyi betűi egy isteni lapnak;
Nagy gondolatit mikor olvasom én;
A sírba, a sírbul az égbe ragadnak.

Bús tompa harang konog a faluban.
Új gödröt amott komor emberek ásnak.
Gyászhangja kiséri áhítatosan
A holtat honához a hamvadozásnak.

Sejtése szivemnek aligha csaland:
Nem messze lehet keze már az időnek,
Mely engem is ágyba tesz itten alant,
S szememre halál örök álmai jőnek.

Isten neki! üssön, ha ütnie kell,
Mely pályafutásom elállja, az óra;
Létem fonalai, szakadozzatok el,
Társim, bucsucsókot a hervadozóra.

S mit sorsom elérni nem engede, nem!
Bár vágyaimon koszorúba szövődék:
Isten veled, égi virág... szerelem!
S föld hajnali csillaga, napja... dicsőség!','Fölhangolom olykor a lant idegeit,
Megzengeni téged, o kellemes élet!
- Mert kellemes az, noha sok sebet ejt,
És rengetegekbe nem egy uta téved.','Gödőllő, 1843. szeptember',1843,'1843',array['Elmúlás','Természet']::text[],'{}'::text[],false,88,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-30','petofi','Kis furulyám szomorúfűz ága...','Kis furulyám szomorúfűz ága,
Temetőben szomorkodik fája;
Ott metszettem azt egy sírhalomról,
Nem csoda, hogy oly siralmasan szól.

Ott hunytál le, kedves szép csillagom!
Ragyogásod többé nem láthatom.
Hogyne volna hát sötét világom!
Hogy volna hát élni kivánságom!

Hazaballag nyájam estefelé,
Én ballagok a temető felé,
Kél a holdnak halovány orcája,
Kél furulyám epedő nótája.

Addig epeszt a bánat engemet,
Addig-addig nyögöm keservemet:
Míg egyszer a hanggal egyetemben
Lelkem is a másvilágba reppen.','Kis furulyám szomorúfűz ága,
Temetőben szomorkodik fája;
Ott metszettem azt egy sírhalomról,
Nem csoda, hogy oly siralmasan szól.','Diószeg, 1843. október 15-31. között',1843,'1843',array['Természet']::text[],'{}'::text[],false,89,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-31','petofi','A szerelem, a szerelem...','A szerelem, a szerelem,
A szerelem sötét verem;
Beleestem, benne vagyok,
Nem láthatok, nem hallhatok.

Őrizem az apám nyáját,
De nem hallom a kolompját;
Rá-rámegy a zöld vetésre,
Hej, csak későn veszem észre.

Telerakta édesanyám
Eleséggel a tarisznyám;
Elvesztettem szerencsésen,
Lesz módom a böjtölésben.

Édesapám, édesanyám,
Ne bizzatok most semmit rám,
Nézzétek el, ha hibázok -
Tudom is én, mit csinálok!','A szerelem, a szerelem,
A szerelem sötét verem;
Beleestem, benne vagyok,
Nem láthatok, nem hallhatok.','Székelyhíd, 1843. november 4-24. között',1843,'1843',array['Szerelem','Család']::text[],'{}'::text[],false,90,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-32','petofi','Matildhoz','Mért vagy hozzám olyan idegen?
Mért tekintesz rám oly hidegen?
Hidegen, mint téli napsugár,
Melynek mosolya is faggyal jár.

Be sokat szeretnék mondani,
S alig merlek megszólítani;
Alig merlek nézni, hej pedig
Elnéznélek világ végeig!

Emelj föl magadhoz engemet,
Fogadd el neked szánt lelkemet,
Annyibul ha megérdemli tán,
Hogy szeretni képes igazán.

Oh, szerelmem forró szerelem,
Forróbb, mint a dél nyárközepen;
Ha a nap ily tűzzel sütne ránk,
Rég elégett volna a világ.','Mért vagy hozzám olyan idegen?
Mért tekintesz rám oly hidegen?
Hidegen, mint téli napsugár,
Melynek mosolya is faggyal jár.','Debrecen, 1843. december',1843,'1843',array['Szerelem','Természet']::text[],'{}'::text[],false,91,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-33','petofi','Megúnt rabság','Mindent elkövettem,
Amit lehetett,
Jó remény fejében,
Hogy majd megszeret.

Féktelen, szilaj volt
Lelkem, mint a tűz,
Melyet a szél meggyúlt
Háztetőkön űz;

És lettem szelíd láng,
Min melegszenek
Őszi estén békés
Pásztoremberek.

Voltam mélybe omló
Bérci zuhatag,
Habjaim robajjal
Szakadoztanak;

S lettem méla csermely,
Halk, morajtalan,
Kedvemet lelő a
Part virágiban.

Voltam sziklahomlok,
Zordon és magas,
Hol lakott mennydörgő
Villám s büszke sas;

S lettem völgy ölébe
Rejtezett berek,
Melyben csalogányok
Búja kesereg.

Voltam... mi nem voltam!
Mivé nem levék!
És a lyányka most is
Csak a régi még.

Nem, tovább nem űzöm!
Mert ez drága bér;
Tán ily áldozattal
A díj föl sem ér.

Szerelem, lerázom
Fölvett láncodat,
Kedves lánc, igaz, de
Mégis lánc marad.

Most hát lelkem, repdess
Régi szárnyadon,
Merre a szabadság
Végtelenje von!','Mindent elkövettem,
Amit lehetett,
Jó remény fejében,
Hogy majd megszeret.','Debrecen, 1843. december',1843,'1843',array['Haza','Szerelem','Természet']::text[],'{}'::text[],false,92,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-34','petofi','Élő halott','Egem ki nem derűl,
Ha jő a kikelet;
Egem be nem borúl,
Ha látom a telet.

Mint őszi alkonyon
A félhomályu köd,
Fásult egykedvüség
Mereng szivem fölött.

Ellenség, jóbarát,
Végeztem veletek;
Senkit nem gyűlölök,
Senkit nem szeretek.

Nincs semmi örömem,
Nincs semmi bánatom;
Érzelmim, vágyaim
Mind, mind elaltatom.

Ohajtásim közül
Ébren csak egy marad:
Aludjam én ... minél
Elébb... a föld alatt.','Egem ki nem derűl,
Ha jő a kikelet;
Egem be nem borúl,
Ha látom a telet.','Debrecen, 1843. december',1843,'1843',array['Elmúlás']::text[],'{}'::text[],false,93,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-35','petofi','A virágnak megtiltani nem lehet...','A virágnak megtiltani nem lehet,
Hogy ne nyíljék, ha jön a szép kikelet;
Kikelet a lyány, virág a szerelem,
Kikeletre virítani kénytelen.

Kedves babám, megláttalak, szeretlek!
Szeretője lettem én szép lelkednek -
Szép lelkednek, mely mosolyog szelíden
Szemeidnek bűvösbájos tükrében.

Titkos kérdés keletkezik szivemben:
Mást szeretsz-e, gyöngyvirágom, vagy engem?
Egymást űzi bennem e két gondolat,
Mint ősszel a felhő a napsugarat.

Jaj ha tudnám, hogy másnak vár csókjára
Tündér orcád tejben úszó rózsája:
Bujdosója lennék a nagy világnak,
Vagy od''adnám magamat a halálnak.

Ragyogj reám, boldogságom csillaga!
Hogy ne legyen életem bús éjszaka;
Szeress engem, szívem gyöngye, ha lehet,
Hogy az isten áldja meg a lelkedet.','A virágnak megtiltani nem lehet,
Hogy ne nyíljék, ha jön a szép kikelet;
Kikelet a lyány, virág a szerelem,
Kikeletre virítani kénytelen.','Debrecen, 1843. december',1843,'1843',array['Szerelem','Természet']::text[],array['tavasz']::text[],false,94,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-36','petofi','Nem megyek én innen sehova...','Nem megyek én innen sehova,
Noha sorsom itten mostoha;
Hát ha volna még mostohább is,
Nem maradnék-e itt tovább is?

Nagyon kedves nekem ez a hely;
Elmegy majd a tavasz, menjen el,
Elmehet a nap, a csillagok...
De én nem mék, én itt maradok.

Fa vagyok én, lelkem a gyökér,
Gyökér nélkül a fa meg nem él;
S hogy téphetném azt ki földéből,
Idevaló mátkám szivéből?

Azért nem mék innen sehova,
Noha sorsom igen mostoha;
De ha volna még mostohább is,
Megmaradnék itten tovább is.','Nem megyek én innen sehova,
Noha sorsom itten mostoha;
Hát ha volna még mostohább is,
Nem maradnék-e itt tovább is?','Debrecen, 1843. december',1843,'1843',array['Természet']::text[],'{}'::text[],false,95,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-37','petofi','Síkos a hó, szalad a szán...','Síkos a hó, szalad a szán,
Esketőre viszik babám,
Esketőre viszik szegényt
Mások kivánsága szerént.

Hej, ha mostan hó lehetnék:
A szán alatt beroskadnék;
Fölfordulna, s kedves babám
Még egyszer átkarolhatnám -

Átkarolnám, ajakára
Csókot nyomnék utójára,
S melegétől hű szivének
Elolvadnék... úgy halnék meg!','Síkos a hó, szalad a szán,
Esketőre viszik babám,
Esketőre viszik szegényt
Mások kivánsága szerént.','Debrecen, 1843. december',1843,'1843',array['Természet','Szerelem']::text[],array['tel']::text[],false,96,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1843-184302-38','petofi','Temetésre szól az ének...','Temetésre szól az ének,
Temetőbe kit kisérnek?
Akárki! már nem földi rab,
Nálam százszorta boldogabb.

Itt viszik az ablak alatt;
Be sok ember sírva fakadt!
Mért nem visznek engemet ki,
Legalább nem sírna senki.','Temetésre szól az ének,
Temetőbe kit kisérnek?
Akárki! már nem földi rab,
Nálam százszorta boldogabb.','Debrecen, 1843. december',1843,'1843',array['Elmúlás']::text[],'{}'::text[],false,97,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-01','petofi','Honfidal','Tied vagyok, tied, hazám!
E szív, e lélek;
Kit szeretnék, ha tégedet
Nem szeretnélek?

Szentegyház keblem belseje,
Oltára képed.
Te állj, s ha kell: a templomot
Eldöntöm érted;

S az összeroskadó kebel
Végső imája:
Áldás a honra, istenem
Áldása rája! -

De én nem mondom senkinek,
Ki nem kiáltom:
Legkedvesebbem hogy te vagy
A nagy világon.

Titkon kisérem lépteid,
S mindegyre híven;
Nem, mint az árny az útazót,
Csak jó időben.

De mint az árnyék nő, midőn
Az est közelget:
Nő búm, ha sötétedni kezd,
Hazám, fölötted.

És elmegyek, hol híveid
Pohárt emelve
A sorstól új fényt esdenek
Szent életedre;

S kihajtom egy cseppig borát
A telt üvegnek,
Bár keserű... mert könnyeim
Beléperegnek!','Tied vagyok, tied, hazám!
E szív, e lélek;
Kit szeretnék, ha tégedet
Nem szeretnélek?','Debrecen, 1844. január-február',1844,'1844',array['Haza','Szerelem']::text[],'{}'::text[],false,98,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-02','petofi','Elmondanám...','Elmondanám: "Megállj, leányka
Megállj, virágom, csillagom!
Egy istenadta szívet bírok;
Nesze, ha kell, neked adom."

Elmondanám, hogy: "Szívem tenger,
Uralkodjál e tengeren!
Jól jársz vele, mert a legszebb gyöngy,
A hűség gyöngye itt terem."

Elmondanám, hogy: "Tiszta fényét
E gyöngy örökre tartja meg."
Elmondanám ezt, s többet ennél;
De nem mondom, mert nincs kinek.','Elmondanám: "Megállj, leányka
Megállj, virágom, csillagom!
Egy istenadta szívet bírok;
Nesze, ha kell, neked adom."','Debrecen, 1844. január-február',1844,'1844',array['Természet']::text[],'{}'::text[],false,99,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-03','petofi','A dal','Bölcsőben sír az éber csecsemő;
Bölcső előtt
A dajka zeng - el szokják a dalok
Altatni őt.

Sok szenvedésem síró gyermeke
A fájdalom:
Dalt dalra költök - dalaimmal őt
Elaltatom.','Bölcsőben sír az éber csecsemő;
Bölcső előtt
A dajka zeng - el szokják a dalok
Altatni őt.','Debrecen, 1844. január-február',1844,'1844',array['Gyermekkor']::text[],'{}'::text[],false,100,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-04','petofi','Fütty','Adta finnyás közönsége!
Csúnyaság, amit mivel:
Minden este megköszönti
Társaságunk, füttyivel.

És aztán a füttyök mellett
Milyen a jövedelem?
A színész elébb-utóbb is
Csak megszökni kénytelen.

Ej, egy rókát kétszer nyúzni,
Ez, urak, mégsem megyen;
Már ha fütty van, legalább hát
Tele színházban legyen!','Adta finnyás közönsége!
Csúnyaság, amit mivel:
Minden este megköszönti
Társaságunk, füttyivel.','Debrecen, 1844. január-február',1844,'1844','{}'::text[],'{}'::text[],false,101,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-05','petofi','Végszó ***hoz','Isten veled, te elpártolt barát,
Veszett ebként ki szívem megmarád,
Isten veled;
Fogadd a vett sebért emlékül,
Mely fölszivárog belsejébül,
Lelkemnek vérét, könnyemet.

Nem a legelső rajtam már e seb,
De egyik sem volt fájóbb, mérgesebb
A sok között,
Melyet vétkes könnyelmüséggel
A hűtelenség fegyverével
Bennem baráti kéz ütött.

Dúsgazdag bánya a tapasztalás,
Melyből sok ember életkincset ás -
Nem én, nem én!
Gyönyörszomjas szivem... remélve...
Az annyiszor megnyílt örvénybe
Hanyatthomlok rohan, szegény.

Remény, remény, mért vagy te szép virág?
Téged nekünk az ég miért is ád?
Azért-e csak?
Hogy hervadandó kelyhed légyen,
Hová csalódás éjjelében
Szemünk harmatjai hulljanak...

De nem panaszlok, bár keblem teli,
S az elfojtás még inkább neveli
Búm tengerét;
Ugyis ki tudja? hogyha hallnád
Lelkem kiáradó fájdalmát:
Talán már meg sem értenéd.

Nem is kivánom megtérésedet,
Akár ohajtod, akár megveted
Uj frígyemet.
Az istenség is tehetetlen
Eggyé büvölni e kebelben
A szertezúzott láncszemet...

Nem láncszem az, nem! egy világ vala,
Melynek napjául a hit lángola,
A drága hit!
Rájött a végitélet napja,
S már semmi föl nem támaszthatja
Ledúlt világom romjait.

Isten veled hát, elpártolt barát,
Ki ábrándim ködét elzavarád,
Isten veled!
Fogadd a múltakért emlékül
Megcsalt barátság gyötrelmétül
Utószor omlott könnyemet.','Isten veled, te elpártolt barát,
Veszett ebként ki szívem megmarád,
Isten veled;
Fogadd a vett sebért emlékül,','Debrecen, 1844. január-február',1844,'1844',array['Természet']::text[],'{}'::text[],false,102,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-06','petofi','A nemes','Deresre huzzák a gazembert,
Bünét botokkal róni le;
Lopott, rabolt, és tudj'' az ördög,
Még mit nem mívele.

De ő kiált ellenszegűlve:
"Hozzám ne nyúljatok!
Nemes vagyok... nincs nemesembert
Botozni jogotok."

Hallottad e szót, meggyalázott
Ősének szelleme?
Most már őt húzni nem deresre:
Akasztófára kellene!','Deresre huzzák a gazembert,
Bünét botokkal róni le;
Lopott, rabolt, és tudj'' az ördög,
Még mit nem mívele.','Debrecen, 1844. január-február',1844,'1844','{}'::text[],'{}'::text[],false,103,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-07','petofi','Halvány katona','Volt a honvédő legénység
Harcra készülőben;
Volt egy ifju a sereg közt,
Halovány szinében.

"Hát kendnek tán az inába
Szállt a bátorsága?"
Kérdi egy tiszt gúnyolón, "hogy
Képe olyan sárga."

''Tiszt uram,'' felelt az ifju,
''Már az az én gondom:
Mérthogy olyan sárga képem?
És azt meg se'' mondom.

Még ma úgyis kipiroslik,
Hogyha nem egyébtől:
A kardomról rája feccsent
Ellenség vérétől.''','Volt a honvédő legénység
Harcra készülőben;
Volt egy ifju a sereg közt,
Halovány szinében.','Debrecen, 1844. január-február',1844,'1844',array['Haza']::text[],'{}'::text[],false,104,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-08','petofi','Szomjas ember tűnődése','Ejnye, mi az istennyila!
Üres már a ládafia?
Üres ám -
Jaj pedig be ihatnám!

Száraz kút a gégém csapja,
Süti a szomjuság napja;
Még meggyul,
Ha rá boreső nem hull.

Hm, biz a nem tréfa volna,
A felhőből hogyha folyna
Boreső -
Volna! itt a bökkenő.

Volt a szőlőben határom,
De eladtam tavaly nyáron,
S az ára
Garatomon lejára.

A kocsmából meg már régen
Kikopott az emberségem;
"Addsza - ne!"
Ilyen szépen főznek le.

...Valami jutott eszembe!
Zálogúl majd azt teszem be.
Előre,
Hitvesem fejkötője!

Jaj de hisz már sírba zártam
Szerelmetes hitestársam,
S ott véle
Nyúgoszik fejkötője.

Oh miért is emlékezem
Halálodra, én kedvesem?
Könny gördül
Azonnal két szemembül.

Hátha könnyeimnek árja,
Uram bocsá''! borrá válna:
Akkor még -
Hej, akkor többet sírnék!','Ejnye, mi az istennyila!
Üres már a ládafia?
Üres ám -
Jaj pedig be ihatnám!','Debrecen, 1844. január-február',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,105,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-09','petofi','Ivás közben','Hányadik már a pohár?... csak
Ötödik?
Teremt'' ugyse! becsülettel
Működik.
Máskor megfe-felelek kétannyinak:
S lábaim most már öttől is inganak.

Ing a lábam, a nyelvem meg
Elakad -
Torkom a therpomyléi
Szorulat,
Ledionas a bor, mely lecsepege,
Gondolatim... Sex... Rex... Xerxes serege.

Sehogysem t''om kifejezni
Magamat -
Azt hiszitek, hogy talán a
Bor miatt?
Ne higgyétek, édes atyámfiai,
Nekem a bor nem szokott megártani.

Nekem a bor hogymikép is
Ártana?
Hát hiába voltam volna
Katona?
Úgy biz, aki fölmarkolta, katona -
Mégpedig bakancsos voltam valaha.

Zöldhajtókás, sárgapitykés
Közlegény...
Egész a közlegénységig
Fölvivém!
Jó: bakancsom hogy hamar lerúghatám;
Még idővel degradáltak volna tán.

Tyhű, látjátok, ott az könnyen
Megesik,
Mert a katonai pálya
Fene sik;
Legkivált az olyfélének, mint magam,
Kinek kissé akaratos feje van.

Útmutatást nekem ne is
Adjatok,
Szent Dávid hárfájára sem
Hallgatok!
Orrnál fogva senki engem nem cibál, -
Azt cselekszem, ami tetszik... Tudja Pál,
Mit kaszál.

...Eh, de én itt egyre-másra,
Mint malom,
Csak darálok, csak darálok,
S szomjazom.
Adjatok bort! a malom jól nem megyen:
Hogyha nincs nedv, ami hajtsa, bőviben.

Hadd igyam hát! hogy forogjon
Kerekem -
Meg sem állok, csak a kancsó-
Feneken.
Bárha mindjárt - amint Falstaff szólana -
Bárha, mondom, egy mérföldig tartana.

Hol is hagytam?... tudja gólya...
Úgy igaz!
A malom volt az utósó...
Vagy nem az?
Mit is mondtam a malomról... én bizon
Hogyha présbe csavarítnak sem tudom.

Annyi szent: a szemem héja
Oly nehez,
Mint malomkő... tán az álom
Környekez.
Elég is ma a tivornya, ágyba hát!
Álmadozzuk folytatását... jó ''jszakát!','Hányadik már a pohár?... csak
Ötödik?
Teremt'' ugyse! becsülettel
Működik.','Debrecen, 1844. január-február',1844,'1844',array['Család']::text[],'{}'::text[],false,106,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-10','petofi','Boldogtalan voltam...','Boldogtalan voltam
Teljes életemben;
Csak az vigasztal, hogy
Meg nem érdemeltem.

Boldogtalan leszek,
Koporsóm zártáig;
Csak az vigasztal, hogy
Nincs messze odáig.

Hiába biztattok
Hiába beszéltek -
Tudom azt az egyet,
Hogy nem soká élek.','Boldogtalan voltam
Teljes életemben;
Csak az vigasztal, hogy
Meg nem érdemeltem.','Debrecen, 1844. január-február',1844,'1844',array['Természet']::text[],'{}'::text[],false,107,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-11','petofi','Nem ver meg engem az Isten...','Nem ver meg engem az isten.
Hogy szeretőt mást kerestem.
Te hagytál el, nem én téged;
Délibáb volt a hűséged.

Iskolába nem járattak,
Olvasni nem tanítottak,
De szemedből kiolvasom,
Hogy szivedben bánat vagyon.

Mért búsulsz? tán megbántad már,
Hogy engemet megbántottál?
Sose búsúlj! úgyis késő;
Ami elmúlt, vissza nem jő.

Találtam már mást magamnak,
Találj te is mást magadnak;
Éljed világodat vele,
Áldjon meg az isten vele.','Nem ver meg engem az isten.
Hogy szeretőt mást kerestem.
Te hagytál el, nem én téged;
Délibáb volt a hűséged.','Debrecen, 1844. január-február',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,108,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-12','petofi','Hírös város az aafődön Kecskemét...','Tisza-Duna közti tájbeszéd szerint

Hírös város az aafődön Kecskemét,
Ott születtem, annak öszöm könyerét.
A búzáját magyar embör vetötte,
Kakastéjjee szép mönyecske sütötte.

Nincs énnéköm mestörségöm, nem is kő,
Van azé jó keresetöm, jobb se kő,
Vót is, van is, lösz is, hiszöm istenöm,
Míg utast lát a pusztába két szömöm.

Ómáspej a nyergös lovam, nem vöttem,
Szögénylegény szép szörivee szöröztem.
Csillagos a feje, kese a lába -
Mögeresztöm, a szél sem ér nyomába.

Ezön járok, mint kiskiráj, kényösen,
Borjúszájas ingöm lobog szélösen,
Süvegöm a jobb szömömön viselöm,
Mindön embör előtt mög se emelöm.

Be-benézök a bugaci csárdába,
Öszöm, iszom, kedvem szörént rovásra;
Ölégségös hitelöm van ott néköm,
Mögfizetök, böcsületöm nem sértöm.

A vármögye emböreit pej lovam
Csak ojan jól mögösmeri, mint magam.
Ha érköznek, nagyot nyerít - rátermök;
S ha rajt vagyok, gyühetnek már őkeemök!','Tisza-Duna közti tájbeszéd szerint
Hírös város az aafődön Kecskemét,
Ott születtem, annak öszöm könyerét.
A búzáját magyar embör vetötte,','Debrecen, 1844. január-február',1844,'1844',array['Természet']::text[],'{}'::text[],false,109,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-13','petofi','Tél végén','Örültök úgye a kies tavasznak?
Maholnap eljő, s annyi élvet ad!
A réteken majd méhek táboroznak,
Megostromolni a virágokat.

S amíg elszántan ütközetre mégyen
A szűz bimbók mézéhes ellene:
Csicserg a szomszéd lombozat hüsében
Madárajakról lelkes harczene. -

Elzárkoztában a kihalt kebelnek
Engem virág, dal, méh nem érdekel...
Ohajtásim mégis mivégre kelnek?
Hogy menjen a tél, menjen gyorsan el.

Én a tavaszt csak annyiból kivánom,
Mert melegebbek lesznek a napok,
S mint mostan, akkor hűlt rideg tanyámon
Kopott ruhámban fázni nem fogok.','Örültök úgye a kies tavasznak?
Maholnap eljő, s annyi élvet ad!
A réteken majd méhek táboroznak,
Megostromolni a virágokat.','Debrecen, 1844. február',1844,'1844',array['Természet']::text[],array['tel']::text[],false,110,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-14','petofi','De már nem tudom, mit csináljak...','De már nem tudom, mit csináljak?
Meginnám borát az országnak.
S mentül több az, amit megiszom,
Annál iszonyúbban szomjazom.

Mért nem tesz az isten most csodát?
Változtatná borrá a Tiszát,
Hadd lehetnék én meg a Duna:
Hogy a Tisza belém omlana!','De már nem tudom, mit csináljak?
Meginnám borát az országnak.
S mentül több az, amit megiszom,
Annál iszonyúbban szomjazom.','Tokaj, 1844. február',1844,'1844',array['Természet']::text[],'{}'::text[],false,111,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-15','petofi','Keresztúton állok...','Keresztúton állok,
Merre tartsak?
Ez kelet felé visz,
Az nyugatnak.

Akármerre megyek,
Mindegy nekem,
Mindenütt szomorú
Az életem.

Mért nem tudom, hol vár
A halál rám?
Hogy egyenesen azt
Választhatnám!','Keresztúton állok,
Merre tartsak?
Ez kelet felé visz,
Az nyugatnak.','Miskolc, 1844. február',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,112,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-16','petofi','Eger mellett','Hol jó bort érezek, betérek;
Ne térnék hát Egerbe?
Ha ezt a várost elkerülném,
Az isten is megverne.

Egyúttal azt is megtekintem,
Hol vítt Dobó nagy lelke;
És felköszöntöm, aki őt oly
Dicsőn megénekelte.

S ha majd, amint hiszem, a bortól
Hatalmas kedvem lészen;
Még verset is csinálok - Pesten
Eladhatom jó pénzen.

Áll a határzat, áll erősen,
Be kell Egerbe mennem!
Mert ennyi édes vonzerőnek
Szívem nem állhat ellen.','Hol jó bort érezek, betérek;
Ne térnék hát Egerbe?
Ha ezt a várost elkerülném,
Az isten is megverne.','Andornak, 1844. február',1844,'1844','{}'::text[],'{}'::text[],false,113,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-17','petofi','Egri hangok','Földön hó, felhő az égen -
Hát hiszen csak hadd legyen!
Rajta nincsen mit csodálni,
Télen ez már ígyen megyen.
Én ugyan nem is tudnám, hogy
Tél vagyon,
Ha ki nem pillantanék az
Ablakon.

Itt benn űlök a melegben,
Környékez sok jóbarát,
Töltögetve poharamba
Egri bércek jó borát.
Jóbarátok, jó borocska -
Kell-e más?
Kebleinkben a kedv egy-egy
Óriás.

Kedvemnek ha magja volna:
Elvetném a hó felett.
S ha kikelne: rózsaerdő
Koszorúzná a telet.
S hogyha földobnám az égre
Szívemet,
Melegítné a világot
Nap helyett! -

Idelátszik a hegy is, hol
Dobó a hír könyvibe
Nagy neve örök betűit
Török vérrel irta be.
Hej, az volt ám még az ember,
Biz az ám!
Míg olyan lesz, sok víz elfoly
A Dunán.

Elvirúlt már a magyarnak
Tettvirágos tavasza!
Hosszu gyáva tespedésben
Pang, sínlődik e haza.
Megjövend-e még az elszállt
Kikelet?
Lesz virány e régtől puszta
Hon felett?...

Eh de hagyjuk, hagyjuk ezt most!
Úgyis ritkán vígadok;
E napot ne háborítsák
Legalább a bánatok.
S a sopánkodásnak ugysincs
Sikere,
S mit tehet mást a lant gyönge
Embere?

El tehát a hon bajával,
Most ez egyszer el vele!
A kitört bút minden ember
Új pohárral öntse le.
Új pohár bort hát, barátim,
Új pohárt!
S ismét újat, az előbbi
Ha lejárt.

Igy!... de ím, mit veszek észre?
Egy század minden pohár;
A jelen hátam mögött van,
Lelkem a jövőben jár.
A jövőben vígan élek,
Boldogon!
Mert nem árva már az egykor
Árva hon.','Földön hó, felhő az égen -
Hát hiszen csak hadd legyen!
Rajta nincsen mit csodálni,
Télen ez már ígyen megyen.','Eger, 1844. február',1844,'1844',array['Természet','Haza']::text[],array['tel']::text[],false,114,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-18','petofi','Javulási szándék','Mikor térsz már az eszedre, te Sándor?
Tivornya éjjeled és napod;
Az istenért! hisz az ördög elvisz,
Ha még soká így folytatod.

Szeretetreméltó barátom,
Nézd meg csak a tűkörben magadat;
Hát ember az, akit ott látsz? mennykő!
Tükröd kisértetet mutat.

Fiú, légy hát okosabb valahára,
Szedd rendbe rendtelen életedet;
Hidd el, kedves pajtásom, az ember
Korhelység nélkül is ellehet.

Naponként egy messzely borocska,
Én úgy hiszem, ennyi untig elég.
S mi a szerelmet illeti: jobb lesz
Talán szeretők helyett feleség.

De mit beszélek? mit beszéltem!
Messzely borocska és feleség?
Én és feleség, én és messzely bor?
No hisz csupán az kellene még!

O nem, nem! engem a rendes élet
Időnek előtte megölne, tudom;
Költő vagyok, költőileg kell
Végigrohannom az életuton!','Mikor térsz már az eszedre, te Sándor?
Tivornya éjjeled és napod;
Az istenért! hisz az ördög elvisz,
Ha még soká így folytatod.','Pest, 1844. március-április',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,115,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-19','petofi','Gyönge vagyok...','Gyönge vagyok, lelkem testem
Fáradt.
Vessétek meg nekem azt az
Ágyat.
Vesd meg rózsám, hadd feküdjem
Bele,
Hadd pihenjem ki magamat
Benne.

Istenem! mi van ezen az
Ágyon?
Mindenütt nyom, mindenfelől
Fázom.
Nem vetette rózsám meleg
Keze;
Vetette a halál hideg
Keze.','Gyönge vagyok, lelkem testem
Fáradt.
Vessétek meg nekem azt az
Ágyat.','Pest, 1844. március-április',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,116,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-20','petofi','Virít a kikirics...','Virít a kikirics -
Csak viríts, csak viríts...
Én ugyis hervadok,
Hervadok, száradok,
Csak viríts, kikirics!

Süt a nap sugára
Halovány orcámra;
Sütni fog maholnap
Alacsony siromnak
Kis keresztfájára.

Anyám, édes lelkem!
Mért zokogsz mellettem?
Ki annyit szenvedett,
Mint szegény gyermeked,
Jobb annak odalenn.','Virít a kikirics -
Csak viríts, csak viríts...
Én ugyis hervadok,
Hervadok, száradok,','Pest, 1844. március-április',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,117,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-21','petofi','Mi nagyobb a nagy Szentgellérthegynél...','Mi nagyobb a nagy Szentgellérthegynél?
Mi mélyebb a Duna vizénél?
Dunaviznél mélyebb mély szerelmem,
Szentgellértnél nagyobb nagy keservem.

Dunaparton fűbe heveredtem,
Halásztak a halászok mellettem,
Kihalásztak sok apró kis halat,
Hálójokban alighogy megakadt.

Ha azt tudnám, hogy az én hálómba
Valami nagyon nagy hal akadna,
Akkora, hogy berántana engem:
Nekem is volna halászni kedvem.','Mi nagyobb a nagy Szentgellérthegynél?
Mi mélyebb a Duna vizénél?
Dunaviznél mélyebb mély szerelmem,
Szentgellértnél nagyobb nagy keservem.','Pest, 1844. március-április',1844,'1844',array['Természet']::text[],'{}'::text[],false,118,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-22','petofi','Betegségemben','Megmondtam úgye?: térj eszedre!
S te nem fogadtad szavamat;
Tovább üzéd eszeveszetten
Az ostobáskodásokat.

Most szépen vagy, szépen... de úgy kell
Az ilyen szeleverdinek!
Hanem mit prédikálok? késő
Eső után a köpönyeg.

Amint van, úgy van; most a dolgon
Már változtatni nem lehet,
És legjobb, amit tehetek, ha
Előveszem türelmemet.

Ah, türelem! reád lelkemnek
Valóban nagy szüksége van;
Itten heverni a kórágyon,
Kínok között, magányosan!

Lám, irtózám a házasságtól,
Mondám, hogy nem kell feleség;
Pedig egy szép, egy hű menyecském
Ha volna most, mi jól esnék!

Hozzám hajolna, édes ajka
Elcsókolná fájdalmamat,
És ölelése enyhet adna,
Minőt az orvosság nem ad. -

S tán eddig is azért ejték csak
Nő elleni beszédeket,
Mivelhogy senki, senki nem volt,
Nem volt, ki engem szeretett.

S ha lenne... oh, ha lenne! érzem:
Szeretni tudnék végtelen! -
Megérem-e, hogy nekem is lesz
Szép csendes házi életem?','Megmondtam úgye?: térj eszedre!
S te nem fogadtad szavamat;
Tovább üzéd eszeveszetten
Az ostobáskodásokat.','Pest, 1844. március-április',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,119,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-23','petofi','Vándorélet','Barabás rajzához

Szent Kleofás!
Milyen karaván...
Nem lehet más,
Mint oláhcigány;
Avvagy e szép útazási rend
S pőre purdék serge mit jelent?

Ott huzódik a diszes csapat
Hosszu sorban zöld erdő alatt;
A családfő vén, kehes lovon,
Kit kötőfékszárnál fogva von
Üggyel-bajjal egy izmos legény...
No hisz izzad még az is szegény!
Mert bizony már régen lehete,
Hogy gabancuk a csikófogat
Elhullatta... s most mi élete?
Koplalásban tölt gyásznapokat.
Ily esetben aztán ép erő
Nem tudom, hogy volna nyerhető.

S ami több, ki rája nehezűl,
Nemcsak a jó dáde egyedűl:
Oldalain egy-egy tarisznya lóg,
S mindenikben rajkók láthatók;
Ki-kidugván borzas fejöket,
Pityeregnek szörnyü éneket,
Mert helyök nem legkényelmesebb;
A gyaloglás? még keservesebb!
Ugy sipognak, mint az orgona,
S tudja isten, meddig tartana?
De nagyapjok hátra-hátrarúg,
S meglapulnak szépen a fiúk.

Megy megettök férj, menyecske, lyány
Egymás mellett és egymás után.
Ki bagóz, ki füstöt ereget,
Képezőleg terhes felleget,
Mely szemet rág, s fojtja a tüdőt.
Tán dohányuk paprikában főtt.

Leghátul kócmadzagon pedig
Egy lopott malac hetvenkedik.
Boldogúlni nem lehet vele!
Sejt tán, hogy napja alkonyúl,
Azért viseli magát roszúl.
De segít a meszelő nyele,
Mellyel a derék családanya
Nagy vitézül nekirohana.

Igy intéznek bátor lépteket
Faluvégtől falu végeig.
Ily hős népet mi sem rettegtet...
Csak a szél! ezt megsüvegelik.
S okosan! mert a kaján elem
Mértéken túl emberségtelen.
Néha rájok amidőn akad:
Súg fülökbe olyan dolgokat,
Hogy lábszárok is remeg bele,
Mintha volna nyárfa levele.

De ha szél úr könnyü szekeren
Gyors lovakkal más vidékre hajt:
Régi kedvök ismét ott terem,
S farba rúgnak minden földi bajt.','Barabás rajzához
Szent Kleofás!
Milyen karaván...
Nem lehet más,','Pest, 1844. április',1844,'1844',array['Természet']::text[],'{}'::text[],false,120,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-24','petofi','Szerelem- és pipadal','Szeretlek én téged, pipám!
És a dohányt, mely benned ég;
Hogy is ne? füstöd fellege,
Miként galambom szeme, kék.

Szeretem én galambomat,
Miként szeretem a dohányt;
Hogy is ne? pipa és leány
Érettem égnek egyaránt.

S miként a lyányszem s mint a füst,
Nem kék-e a menny födele?
S miként ezek, a mennyfödél
- Csillagtűzben - nem lángol-e?

Hasonmásául alkotá
Az ég e kettőt énnekem,
Hogy látva őket lássam azt,
Kitől boldogságom nyerem.','Szeretlek én téged, pipám!
És a dohányt, mely benned ég;
Hogy is ne? füstöd fellege,
Miként galambom szeme, kék.','Pest, 1844. április',1844,'1844',array['Szerelem','Természet']::text[],'{}'::text[],false,121,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-25','petofi','Füstbement terv','Egész uton - hazafelé -
Azon gondolkodám:
Miként fogom szólítani
Rég nem látott anyám?

Mit mondok majd először is
Kedvest, szépet neki?
Midőn, mely bölcsőm ringatá,
A kart terjeszti ki.

S jutott eszembe számtalan
Szebbnél-szebb gondolat,
Mig állni látszék az idő,
Bár a szekér szaladt.

S a kis szobába toppanék...
Röpűlt felém anyám...
S én csüggtem ajkán... szótlanúl...
Mint a gyümölcs a fán.','Egész uton - hazafelé -
Azon gondolkodám:
Miként fogom szólítani
Rég nem látott anyám?','Dunavecse, 1844. április',1844,'1844',array['Család']::text[],'{}'::text[],false,122,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-26','petofi','Egy estém otthon','Borozgatánk apámmal;
Ivott a jó öreg,
S a kedvemért ez egyszer -
Az isten áldja meg!

Soká nem voltam otthon,
Oly rég nem láta már,
Úgy megvénült azóta -
Hja, az idő lejár.

Beszéltünk erről, arról,
Amint nyelvünkre jött;
Még a szinészetről is
Sok más egyéb között.

Szemében "mesterségem"
Most is nagy szálka még;
Előitéletét az
Évek nem szünteték.

"No csak hitvány egy élet
Az a komédia!"
Fülemnek ily dicsérést
Kellett hallgatnia.

"Tudom, sokat koplaltál,
Mutatja is szined.
Szeretném látni egyszer,
Mint hánysz bukfenceket."

Én műértő beszédit
Mosolygva hallgatám;
De ő makacs fej! föl nem
Világosíthatám.

Továbbá elszavaltam
Egy bordalom neki;
S nagyon, nagyon örültem,
Hogy megnevetteti.

De ő nem tartja nagyra,
Hogy költő-fia van;
Előtte minden ilyes
Dolog haszontalan.

Nem is lehet csodálni!
Csak húsvágáshoz ért;
Nem sok hajszála hullt ki
A tudományokért.

Utóbb, midőn a bornak
Edénye kiürűlt,
Én írogatni kezdtem,
Ő meg nyugonni dűlt.

De ekkor száz kérdéssel
Állott elő anyám;
Felelnem kelle - hát az
Irást abban hagyám.

És vége-hossza nem lett
Kérdezgetésinek;
De nekem e kérdések
Olyan jól estenek.

Mert mindenik tükör volt,
Ahonnan láthatám:
Hogy a földön nekem van
Legszeretőbb anyám!','Borozgatánk apámmal;
Ivott a jó öreg,
S a kedvemért ez egyszer -
Az isten áldja meg!','Dunavecse, 1844. április',1844,'1844',array['Család']::text[],'{}'::text[],false,123,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-27','petofi','Irtóztató csalódás','Elvégezém az én szivemben,
hogy magamat adnám boritalra.

Biblia

A lelkem is sir!... - És miért?
O mert roppant bubánat ért!

Fogalmatok sincs róla, mi
Gyászos, költőnek hallani:
Hogy verse hitvány, verse rosz,
S egy kukk dicsőséget se'' hoz...
És én hallottam ezeket,
És szívem ketté nem repedt!

Mi több: mely verseim felett
Mondának ily itéletet?
Szép bordalok, jó bordalok!
Tirólatok, tirólatok
Hallottam ezt.... pedig hivém,
Hogy a hir kakasüllején
Anakreon. Vitéz Mihály
S Béranger már alattam áll,
Alattam áll általatok
Szép bordalok, jó bordalok!

S ím szép hitem tündérhona
A magasból lepottyana.

Amen hát! amint van, legyen;
Meghajtom a sorsnak fejem,
És tűrök türedelmesen -
Nem zengem többé sohasem,
Nem zengem én a bort... csupán
Torkomba öntöm ezután.','Elvégezém az én szivemben,
hogy magamat adnám boritalra.
Biblia
A lelkem is sir!... - És miért?','Pest, 1844. április',1844,'1844','{}'::text[],'{}'::text[],false,124,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-28','petofi','Fürdik a holdvilág az ég tengerében...','Fürdik a holdvilág az ég tengerében,
Méláz a haramja erdő közepében:
Sűrű a füvön az éj harmatozása,
De sűrűbb két szeme könnyének hullása.

Baltája nyelére támaszkodva mondja:
"Mért vetettem fejem tilalmas dolgokra!
Édesanyám, mindig javamat akartad;
Édesanyám, mért nem fogadtam szavadat?

Elhagytam házadat, földönfutó lettem,
Rablók, fosztogatók közé keveredtem;
Most is köztük élek magam szégyenére,
Ártatlan útasok nagy veszedelmére.

Elmennék én haza, itt hagynám ezeket,
Örömest itt hagynám, de most már nem lehet:
Édesanyám meghalt... kis házunk azóta
Régen összeroskadt... s áll az akasztófa."','Fürdik a holdvilág az ég tengerében,
Méláz a haramja erdő közepében:
Sűrű a füvön az éj harmatozása,
De sűrűbb két szeme könnyének hullása.','Pest, 1844. április',1844,'1844',array['Természet','Család']::text[],'{}'::text[],false,125,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-29','petofi','A csaplárné a betyárt szerette...','A csaplárné a betyárt szerette,
De a betyár őtet nem szerette.
Csaplárnénak örökbevett lyánya
Volt a betyár egész boldogsága.

A csaplárné ezt megirigyelte,
Irígységből a leányt elverte,
Elverte a háztól a világba;
Pedig ott kinn tél, fagy volt javába''.

A szegény lyány ment egy kis darabot,
Aztán leűlt, űltében megfagyott.
Esett ez a betyárnak tudtára,
S csaplárnénak lett kínos halála.

Betyár ezért hóhérkézre kerűlt,
De nem bánta ő, még inkább örűlt;
Mert mióta a lyányt elvesztette:
Pipa dohányt sem ért az élete.','A csaplárné a betyárt szerette,
De a betyár őtet nem szerette.
Csaplárnénak örökbevett lyánya
Volt a betyár egész boldogsága.','Pest, 1844. április',1844,'1844',array['Szerelem']::text[],array['tel']::text[],false,126,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184401-30','petofi','Magány','Messze, messze a világ zajátul
E kis faluban,
Itt kivánok élni én ezentul
Csendben, boldogan.

Boldogan! mert haj a nagy világban
Boldog nem valék;
Üldözött az utcán és szobámban
A föld és az ég.

Nem volt biztos sem napom, sem éjem;
Vad hiúz-szemek
Támadásra, elfogásra készen
Egyre lestenek.

Összeszedtem végre sátorfámat,
S szépen megszökém,
S itt vagyok, hol a nap újra támad
Éltem bús egén.

Szent magány! hegyláncaid tetőin
Át nem látnak ők,
Szívtelen, rémarcu üldözőim
... A hitelezők.','Messze, messze a világ zajátul
E kis faluban,
Itt kivánok élni én ezentul
Csendben, boldogan.','Dunavecse, 1844. április',1844,'1844',array['Természet']::text[],'{}'::text[],false,127,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-31','petofi','Ebéd után','Ugy jóllaktam, hogy még!...
Egyet nyujtózom, és
Aztán tied vagyok,
Imádott heverés!

Oh kedves pamlagom,
Be áldott puha vagy!
Ki téged föltalált,
Az volt ám még az agy. -

Kölyök, pipát ide...
Siess, a nagyapád!
Nincs rútabb valami,
Mint az a lomhaság.

Add errébb hát, ökör!
Én nyuljak érte tán?
Nem elég tőlem, hogy
Föltátom rá a szám? -

Istentelen legye!
Ingerkedik velem...
Kergesd el... a kutya
Ott űl a fülemen.

Az ember élete
Méreggel van tele;
Csodák csodája, hogy
Meg nem pukkad bele.

Húzd a függönyt odább
Azon az ablakon;
Hadd lám, az építés
Ott kinn meddig vagyon?

Á, szépecskén halad,
Munkálnak mindenütt...
De tedd b'' az ablakot,
A nap szemembe süt.

Disznó forró idő!...
No semmi; legalább
Ki ott kinn dolgozik,
Nem hűti meg magát.','Ugy jóllaktam, hogy még!...
Egyet nyujtózom, és
Aztán tied vagyok,
Imádott heverés!','Dunavecse, 1844. április-május',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,128,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-32','petofi','Álmodom-e?','Álmodom-e?
Vagy látok igazán?
S akit látok,
Tündér-e vagy leány?

Akár leány,
Akár tündér lenne,
Mit bánnám én,
Csak belém szeretne!','Álmodom-e?
Vagy látok igazán?
S akit látok,
Tündér-e vagy leány?','Dunavecse, 1844. április-május',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,129,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-33','petofi','Zsuzsikához','Ne hozd, ne hozd azt a bort, kisleány!
Hisz már a nélkül is részeg vagyok -
Megrészegített kellemed,
Fölfordította eszemet,
Nem ihatom... nem kell... sok, ami sok.

Vagy a borban szerelmet hozsz talán?
Azt, angyalom?... szerelmedet?... nekem?...
Úgy addsza azt a poharat.
Iszom, míg egy csepp sem marad,
Legyen bár méreg, addsza, lenyelem!','Ne hozd, ne hozd azt a bort, kisleány!
Hisz már a nélkül is részeg vagyok -
Megrészegített kellemed,
Fölfordította eszemet,','Dunavecse, 1844. április-május',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,130,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-34','petofi','Gazdálkodási nézeteim','Jertek, barátim, van egy-két forintom,
Hágjunk nyakára, a rézangyalát!
Mit a jövendő! arra semmi gondom;
A jóisten majd eztán is csak ád.
Azért szerezzem a pénzt, hogy legyen?
Azért szerzem, hogy eligyam s egyem.

Mert oh barátim, a terített asztal
Dicsőbb, mint Ádám-Éva édene;
Ez ami búban engemet vigasztal,
Ennél virít a lét kietlene.
Szerzem tehát a pénzt, nem hogy legyen,
Hanem azért, hogy eligyam s egyem.

Emberségemre! nincs szánandóbb pára,
Mint kit fukarság nyavalyája bánt;
Halmozva kincset kincse halmazára,
Küzd, fárad, izzad, s él koldús gyanánt.
Nekem nem kell a pénz csak hogy legyen;
Megszerzem én, hogy eligyam s egyem.

Azt mondják e rend érdemes vitézi:
Ki nem zsugorgat, mig nyujt a jelen,
A múltat könnyen búslakodva nézi
Öreg korának szük időiben.
S én mégsem szerzem a pénzt, hogy legyen -
Csupán azért, hogy eligyam s egyem.

Megnyugtat egykor, tán ha semmim sem lesz,
Hogy ameddig volt, jól éltem vele;
De most ha mennék éhen őseimhez,
Nem lenne sírom nyúgalom helye.
Ebből indulva, nem hogy meglegyen,
De szerzek pénzt, hogy eligyam s egyem.

Menjünk tehát, és e néhány forinton
Élvezzük a jót, mennyiben lehet;
Meg sem jövünk, szent Jóllakásra mondom,
Míg egy rosz pótra nyomja zsebemet -
Mert nem szerzém én e pénzt, hogy legyen:
Azért szerzém, hogy eligyam s egyem.','Jertek, barátim, van egy-két forintom,
Hágjunk nyakára, a rézangyalát!
Mit a jövendő! arra semmi gondom;
A jóisten majd eztán is csak ád.','Dunavecse, 1844. április-május',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,131,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-35','petofi','Hattyúdalféle','Bizony, bizony csehül vagyunk!
Mellem szorúl, majd megfulok,
S szivem táján valami rág...
Belőled én, árnyékvilág,
Aligha el nem patkolok.

Hányszor kivántam a halált!
És most midőn már közeleg,
Midőn félig rám lehele:
Olyanformán vagyok vele,
Mint a mesében az öreg.

Hiába! bármi a halál,
Az élet nála többet ér.
Van ottan béke - semmi más;
Van itten bú - de vígadás
Kéjében is pezsg ám a vér.

S én már maholnap elhagyok
Örömeket, fájdalmakat.
Most gomblyukamban a virág,
S ha újra zöldül a világ:
Talán sirom halmán fakad.

S ti majd, ti jó fiúk, kiket
Hozzám barátság lánca köt,
Kikkel most annyi éjszakát
Fölségesen virasztok át:
Gyászoltok a halott fölött.

De én azt mondom, társaim,
Hogy engem ne gyászoljatok;
Természetünktől az elüt -
Mert tudjátok, velem együtt,
Ti mind víg fickók voltatok.

Jertek ki hozzám legfölebb,
S ha állotok sirom körűl:
Vigan hangoztassátok itt
Holt cimborátok dalait
A múlt idők emlékeűl!','Bizony, bizony csehül vagyunk!
Mellem szorúl, majd megfulok,
S szivem táján valami rág...
Belőled én, árnyékvilág,','Dunavecse, 1844. április-május',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,132,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-36','petofi','Sírom','Hogyha én majd meghalok,
Nem leszen kő síromon;
Egy kis fejfa lesz a jel,
Ahová teszik porom.

De ha megkövűl a kín,
Mely most elhat lelkemig:
Alacsony sirom fölött
Piramíd emelkedik.','Hogyha én majd meghalok,
Nem leszen kő síromon;
Egy kis fejfa lesz a jel,
Ahová teszik porom.','Dunavecse, 1844. április-május',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,133,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-37','petofi','Éjjel','Kinézek én, benéz a hold
Szobámnak ablakán:
Sugárait szerelmesen
Mosolygva hinti rám.

Szegény bohó! mit kandikálsz
Olyan szerelmesen?
Avvagy talán azt gondolod,
Hogy képedet lesem?

Eszem ágába'' sincs biz a,
Hogy téged nézzelek.
Isten hirével elmehetsz -
Mit gondolok veled!

Ott általellenben lakik
Az én kedves babám;
Azt várom én, ha valahogy
Még megpillantanám.','Kinézek én, benéz a hold
Szobámnak ablakán:
Sugárait szerelmesen
Mosolygva hinti rám.','Dunavecse, 1844. április-május',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,134,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-38','petofi','Zsuzsikához','Kicsinke szőke kis leányka,
Az én szerelmem nagy!
És tárgya e nagy szerelemnek
Kis szőke lány, te vagy.

Mit mondasz erre szőke kislány?...
De ez csak fele még.
Azon volnék én, hogy te lennél
Énnékem feleség!

Eljössz-e hozzám? el?... szépséges
Szép fejkötőt veszek,
S csak azt mondom: kimondhatatlan
Hüséges férj leszek.

Őrzöm szemem fényét, de téged
Még jobban őrzelek,
Hogy drága egészségednek ne
Ártson hideg, meleg.

Ott fenn lakunk Pest városában,
Az élet ott vig ám!
De az atyushoz is lejárunk
Kivált pénzfogyatán.

Hogy suttogják majd, ha az utcán
Végigmegyek veled:
Petőfi felesége!... Erről
Csinál szép verseket.

Csinálok ám teringettét is,
Hogy bámulnak bele!
Maholnap egész Magyarország
Nevemmel lesz tele.

Ugy estenként csak nekiűlök,
Te meg majd azalatt
Lefekszel szépen s melegíted
Előre ágyamat.

S ha elkészűl egy-egy dicső vers,
Én is levetkezem,
Hozzád simúlok és azt mondom:
Menj beljebb, gyermekem!

Igy éldegélnénk... hát csak ennyit
Akartam mondani.
Mit szólsz rá szőke kislány, lesz-e
Belőle valami?','Kicsinke szőke kis leányka,
Az én szerelmem nagy!
És tárgya e nagy szerelemnek
Kis szőke lány, te vagy.','Dunavecse, 1844. április-május',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,135,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-39','petofi','Vizen','Beszélgetnek sajkámmal
A fecsegő habok;
Feszítem a lapátot,
Hogy szinte izzadok.

Anyám, ha mostan látnál,
Tudom, hogy mondanád:
"Az istenért... ha feldőlsz...
Nem féled a halált?"

Apám, ha mostan látnál,
Tudom, hogy mondanád:
"Az ördög hurcol arra,
Szaggatni a ruhád."','Beszélgetnek sajkámmal
A fecsegő habok;
Feszítem a lapátot,
Hogy szinte izzadok.','Dunavecse, 1844. április-május',1844,'1844',array['Család']::text[],'{}'::text[],false,136,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-40','petofi','A faluban utcahosszat...','A faluban utcahosszat
Muzsikáltatom magamat;
Tele palack a kezembe'',
Táncolok, mint veszett fene.

Huzd rá, cigány, siralmasan,
Hogy magamat kisírhassam,
De majd ott az ablak alatt
Húzzatok valami vigat.

Ott lakik az én csillagom,
Az én bujdosó csillagom,
Aki tőlem elbujdosott,
S világát mással éli most.

Hej cigányok, itt az ablak:
Most a leges-legvigabbat!
Ne lássa az a csalfa lyány,
Hogy búsulok csalfaságán.','A faluban utcahosszat
Muzsikáltatom magamat;
Tele palack a kezembe'',
Táncolok, mint veszett fene.','Dunavecse, 1844. április-május',1844,'1844',array['Természet']::text[],'{}'::text[],false,137,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-41','petofi','Poharamhoz','Különben én becsüllek, oh pohár!
Csak egy van benned, amit restelek;
Azt restelem csak benned, oh pohár!
Hogy olyan könnyen kihörpentelek.

Ha én tenéked volnék, oh pohár!
Ki nem fogynék a borból sohasem;
Aztán, ha nékem volnál, oh pohár!
Innál belőlem véges-végtelen.','Különben én becsüllek, oh pohár!
Csak egy van benned, amit restelek;
Azt restelem csak benned, oh pohár!
Hogy olyan könnyen kihörpentelek.','Dunavecse, 1844. április-május',1844,'1844','{}'::text[],'{}'::text[],false,138,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-42','petofi','Deákpályám','Diligenter frequentáltam
Iskoláim egykoron,
Secundába ponált mégis
Sok szamár professorom.

A poesisból is ebbe
Estem inter alia;
Absurdum pedig, de nagy, hogy
Ennek kelljen állnia.

El sem obliviscálnak, mert
Ha occasióm akadt:
Kutyáliter infestáltam
E jó dominusokat.

Egynek plane... no de minthogy
Szerelemhistória,
Talán jobb lesz in aeternum
Sub rosa maradnia.

Csak denique mi közöttünk
Sine fine folyt a per,
S consilium abeundi
Lett a vége breviter.

Ergo mentem, és vagáltam
A hazában szanaszét;
Verte tandem a bal combom
Kard... azaz hogy panganét.','Diligenter frequentáltam
Iskoláim egykoron,
Secundába ponált mégis
Sok szamár professorom.','Dunavecse, 1844. április-május',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,139,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-43','petofi','Az én torkom álló malom...','Az én torkom álló malom;
Úgy őröl, ha meglocsolom.
Árva szívem a molnárja,
Bánatot hord garatjára.

Az én feleségem torka
Valóságos pergő rokka;
Hej az én jó feleségem
Pörpatvart fon azon nékem.

Zúg, ha őröl, zúg a malom...
Csak hadd zúgjon, locsolgatom;
Zúgjon, zúgjon - ne halljam meg,
Hogy kincsem rokkája pereg.','Az én torkom álló malom;
Úgy őröl, ha meglocsolom.
Árva szívem a molnárja,
Bánatot hord garatjára.','Dunavecse, 1844. április-május',1844,'1844','{}'::text[],'{}'::text[],false,140,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-44','petofi','Te szivemnek szép gyönyörűsége...','Te szivemnek szép gyönyörűsége,
Mért van szivednek kőkeménysége?
Csakugyan meg akarsz,
Meg akarsz ölni hát?
Vagy mért nem enyhíted
Szeretőd fájdalmát?

Szeretőd vagyok én, hű szeretőd,
Elmondhatom isten, ember előtt;
De azt is mondhatom,
Hogy ez a világ nagy,
S a világon te a
Legkegyetlenebb vagy.','Te szivemnek szép gyönyörűsége,
Mért van szivednek kőkeménysége?
Csakugyan meg akarsz,
Meg akarsz ölni hát?','Dunavecse, 1844. április-május',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,141,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-45','petofi','Meredek a pincegádor...','Meredek a pincegádor,
Nehéz teher az a mámor.
Hazafelé mendegéltem,
Terhe alatt összedőltem -
Összedőltem!

Elnyúltam a föld színére,
Megeredt az orrom vére.
Ha ott tégla nem lett volna:
Orrom vére nem folyt volna -
Nem folyt volna!

Nem járnék én a pincébe
Jó időbe'', rosz időbe''...
De tehetek is én arról,
Hogy oly igen jó az a bor -
Jó az a bor!','Meredek a pincegádor,
Nehéz teher az a mámor.
Hazafelé mendegéltem,
Terhe alatt összedőltem -','Dunavecse, 1844. április-május',1844,'1844',array['Haza']::text[],'{}'::text[],false,142,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-46','petofi','Katona barátomhoz','Ha előttem a multat kitárja
Képzeményim hű panorámája:
Katona barátom!
Tévelygő szememnek
Elfáradt sugára
Képeden pihen meg.

Oh ez a mult! pusztaság vidéke,
Mely felett hő, tikkasztó nap ége.
Te a pusztaságban
Árnyékos fa voltál,
Új erőt szereztem
Enyhe sátorodnál.

Kedvezett a jószerencse nékem:
Túljövék e szomorú vidéken.
De itt is nagyobb volt
A bú örömemnél:
Mit használt, hogy jöttem?
Ha te nem jöhettél.

S amióta sors parancsolatja
Közös útunk kettéágaztatta.
Évek érkezének,
Évek távozának,
És még csak hirét sem
Hallhatók egymásnak.

El vagyok már szívedben feledve?
Vagy jutok még néha tán eszedbe?
Vagy, miként emlékem
Rajzol egyre téged?
Szinte rajzol engem
Nem muló emléked?','Ha előttem a multat kitárja
Képzeményim hű panorámája:
Katona barátom!
Tévelygő szememnek','Dunavecse, 1844. április-május',1844,'1844',array['Természet']::text[],'{}'::text[],false,143,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-46_A','petofi','Árvalyányhaj a süvegem bokrétája...','Árvalyányhaj a süvegem bokrétája,
Árva leány a szerelmem violája;
Azt magamnak kinn a pusztán szakasztottam,
Ezt magamnak a faluban választottam.

Gyönyörű kis szőke leány a kedvesem,
De hogy jó lesz, még abban sem kételkedem.
A kék virág tiszta búza között terem,
Mátkámnak is kék virág van a szemiben.','Árvalyányhaj a süvegem bokrétája,
Árva leány a szerelmem violája;
Azt magamnak kinn a pusztán szakasztottam,
Ezt magamnak a faluban választottam.','Lacháza, 1844. június',1844,'1844',array['Szerelem','Természet']::text[],'{}'::text[],false,144,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-47','petofi','Mi folyt ott a mezőn...','Mi folyt ott a mezőn?
Patakvíznek gyöngye -
Hát szeretőm arcán?
A búbánat könnye.

Hadd folyjon a patak!
Habjai mentében
Piros rózsa fejlik
A zöld mezőségen.

De könnyed ne folyjon,
Lelkem kisleánya!
Elhervad a könnytől
Orcáid rózsája.','Mi folyt ott a mezőn?
Patakvíznek gyöngye -
Hát szeretőm arcán?
A búbánat könnye.','Pest, 1844. június',1844,'1844',array['Természet']::text[],'{}'::text[],false,145,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-48','petofi','Elvennélek én, csak adnának...','Elvennélek én, csak adnának,
De hiába szólok anyádnak!
Megtagadja tőlem kezedet;
Nem tudom, az oka mi lehet.

Olyan háborodott az elmém!
Sokszor sírnék, ha nem szégyelném.
Mért nem vagyok felhő az égen?
Sírnom akkor nem volna szégyen.

Miért nem termettem búzának!
Aratás van, most levágnának;
Nem kellene soká szenvednem
Ebben a keserves életben.','Elvennélek én, csak adnának,
De hiába szólok anyádnak!
Megtagadja tőlem kezedet;
Nem tudom, az oka mi lehet.','Pest, 1844. június',1844,'1844',array['Természet']::text[],'{}'::text[],false,146,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-49','petofi','Nem nézek én, minek néznék? Az égre...','Nem nézek én, minek néznék? az égre;
Belenézek kedvesem kék szemébe.
Kedvesemnek kék szemében van egem,
Onnan süt rám tiszta napfény melegen.

Nekem ez a világ nem is kellene,
Ha nem volna kedvesem két kék szeme;
Ez az egy szép, ami van a világon,
Ezen a rút, ezen a csúf világon.

Ne nézzetek kedvesemnek szemébe!
Ne ejtsetek engemet a kétségbe!
Féltve őrzöm, féltve őrzöm kincsemet,
A leggyönyörűségesebb kék szemet.','Nem nézek én, minek néznék? az égre;
Belenézek kedvesem kék szemébe.
Kedvesemnek kék szemében van egem,
Onnan süt rám tiszta napfény melegen.','Pest, 1844. június',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,147,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-50','petofi','Mondom, ne ingerkedjetek velem...','Mondom, ne ingerkedjetek velem!
Nem ismeritek a természetem.
Ha föltámad haragom szélvésze,
Nem marad el fejek beverése.

Jó a tréfa, jó a maga helyén,
De boszant, ha a mértéken túlmén.
S ki megboszant, legyen az akárki,
Megtanítom kesztyűbe'' dudálni.

De te, kislyány, mit huzódol tőlem?
Hiszen ezt én nem neked beszélem;
Gyere mellém, eszem a szépséged,
A világért sem bántalak téged!','Mondom, ne ingerkedjetek velem!
Nem ismeritek a természetem.
Ha föltámad haragom szélvésze,
Nem marad el fejek beverése.','Pest, 1844. június',1844,'1844',array['Természet']::text[],'{}'::text[],false,148,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-51','petofi','Ez a világ amilyen nagy...','Ez a világ amilyen nagy,
Te, galambom, oly kicsiny vagy;
De ha téged birhatnálak,
A világért nem adnálak!

Te vagy a nap, én az éjjel,
Teljes teli sötétséggel;
Ha szivünk összeolvadna,
Rám be szép hajnal hasadna!

Ne nézz reám, süsd le szemed -
Elégeti a lelkemet!
De hisz úgysem szeretsz engem,
Égjen el hát árva lelkem!','Ez a világ amilyen nagy,
Te, galambom, oly kicsiny vagy;
De ha téged birhatnálak,
A világért nem adnálak!','Pest, 1844. június',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,149,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-52','petofi','Színbírálat','Hogy játszottak? ne is kérdezzétek!
Vétek volt ma őket nézni, vétek.
Ily kontárkodás mégis gyalázat;
Csaknem megszalasztották a házat.
Semmi tűz egyben sem, semmi lélek!
Mint fajankók, úgy álltak s beszéltek.
A darab is rosz, silány végképen,
Untató a legnagyobb mértékben.
Ásitottam, hányat és minőket!
S oly sötét volt, tán világ sem égett.

*

(Hol maradhatott az a kislyány? hol?
Üres volt, amelybe jár, a páholy.)','Hogy játszottak? ne is kérdezzétek!
Vétek volt ma őket nézni, vétek.
Ily kontárkodás mégis gyalázat;
Csaknem megszalasztották a házat.','Pest, 1844. június',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,150,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-53','petofi','Kerényi frigyeshez','Szerelmetes barátom, jó napot!
(Vagy estét... amint e firkát kapod.)
Hát hány hét a világ Eperjesen?
Hallom, hogy szenvedtél keservesen,
De csakhogy már bajod végén vagyon!
Örvendek én ezen, pedig nagyon;
Mert, oh barátom, azt elhiheted,
Hogy szörnyü mód szeretlek tégedet.
Már ismeretlen is szerettelek,
Hát még mióta rusztiztam veled!
T''od, a Komlóban, persze, hogy tudod;
Hogy is feledhetnéd azt a napot?
Én részemről csak el nem feledem,
Legyen bár Matuzsálem-életem.

Nos hát te jól vagy, hál'' istennek! Én?
Mint gazdag városban szegény legény.
Másfél hete, hogy őket elhagyám.
Kiknél valék, apám és jó anyám.
Apám kibékült; volt is rája ok:
Hiszen szinész már többé nem vagyok.
Örűl ő - de olyasmit érzek én,
Mit a paradicsomnak küszöbén
Almátevett ősünk érezhetett,
Midőn belőle kikergettetett.
Ott éltem volna én a színpadon
Kín és gyönyör közt... hírben.. szabadon...
Dicső álom volt. Volt! Már elmula.
Borúljon rá felejtés fátyola.

Mint mondám, itt vagyok másfél hete,
Másodmagammal jöttem én ide.
Tudod, ki az, ki Pestre elkisért?
A bú - egy szép kis szőke gyerkemért.
Szegényke! titkolá, hogy értem ég.
Midőn bucsúzni hozzá elmenék,
Oly szomorúan pillantott felém;
S ösztönszerűleg én megölelém.
És csókot érzék, forrót, ajkamon,
És könnyet érzék, forrót, arcomon. -
Én nem tudám, hogy őtet szeretem,
De amidőn megindult szekerem,
S elgondolám, hogy végkép elhagyom:
Elkezde fájni a szivem nagyon.
Mi egymáséi soha nem leszünk,
Egymást feledni lesz talán eszünk.

Egyébiránt időm honn jól telék.
Vers, pajtikám, hó! vers termett elég,
Nem vagyok én verseknek szűkiben,
Bár pénzem jőne olyan könnyeden.
A pénz, a pénz! ez ám a bökkenő.
Ez életünkben a szekérkenő.
Nélkűle a kerék lassan forog,
S forgása közben szörnyen nyikorog.
Azonban érte nem töröm magam;
Jelenleg is - amennyi, annyi - van.
Naponként jön, miből eszem s iszom;
A holnapról én nem gondolkozom,
S ha a jövőbe vetem is szemem:
Vagyon dolgában bizonyára nem;
Azt kérdezem magambam legfölebb:
Mikor mulathatok megint veled?
Veled s a többiekkel, akiket,
Mint téged, oly őszintén szeretek.

Ti vagytok nékem minden örömem;
Emlékezetben legyetek velem,
Míg a boldogság szép órája üt:
Hol ismét áldomásozunk együtt!','Szerelmetes barátom, jó napot!
(Vagy estét... amint e firkát kapod.)
Hát hány hét a világ Eperjesen?
Hallom, hogy szenvedtél keservesen,','Pest, 1844. június 25.',1844,'1844',array['Szerelem','Természet','Család']::text[],'{}'::text[],false,151,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-54','petofi','István öcsémhez','Hát hogymint vagytok otthon, Pistikám?
Gondoltok-e ugy néha-néha rám?
Mondjátok-e, ha estebéd után
Beszélgetéstek meghitt és vidám,
Mondjátok-e az est óráinál:
Hát a mi Sándorunk most mit csinál?
És máskülönben hogy van dolgotok?
Tudom, sokat kell fáradoznotok.
Örök törődés naptok, éjetek,
Csakhogy szükecskén megélhessetek.
Szegény atyánk! ha ő ugy nem bizik
Az emberekben: jégre nem viszik.
Mert ő becsűletes lelkű, igaz;
Azt gondolá, hogy minden ember az.
És e hitének áldozatja lett,
Elveszte mindent, amit keresett.
Szorgalmas élte verítékinek
Gyümölcseit most más emészti meg.
Mért nem szeret ugy engem istenem?
Hogy volna mód, sorsán enyhítenem.
Agg napjait a fáradástul én
Mily édes-örömest fölmenteném.
Ez fáj nekem csak, nyúgodt éltemet
Most egyedűl ez keseríti meg.
Tégy érte, amit tenni bír erőd;
Légy jó fiú és gyámolítsad őt.
Vedd vállaidra félig terheit,
S meglásd, öcsém, az isten megsegít.
S anyánkat, ezt az édes jó anyát,
O Pistikám, szeresd, tiszteld, imádd!
Mi ő nekünk? azt el nem mondhatom,
Mert nincs rá szó, nincsen rá fogalom;
De megmutatná a nagy veszteség:
Ha elszólítná tőlünk őt az ég...
E néhány sorral érd be most, öcsém.
Én a vidámság hangját keresém,
És akaratlan ilyen fekete
Lett gondolatjaimnak menete;
S ha még tovább fonnám e fonalat,
Szivem repedne a nagy kín alatt.
Más levelem majd több lesz és vidám.
Isten megáldjon, édes Pistikám!','Hát hogymint vagytok otthon, Pistikám?
Gondoltok-e ugy néha-néha rám?
Mondjátok-e, ha estebéd után
Beszélgetéstek meghitt és vidám,','Pest, 1844. június',1844,'1844',array['Család']::text[],'{}'::text[],false,152,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-55','petofi','Kis menyecske, szép kis menyecske...','Kis menyecske, szép kis menyecske!
Hej, miért vagy te már menyecske?
Ha te még nem volnál menyecske:
Nem volnék én kétségbeesve.

Nem választottál meg uradnak,
Mert nem vagyok se'' szép, se'' gazdag.
Van most urad, módos, takaros -
Módos, takaros, de haragos.

Nem tudom, szereted-e őtet?
De tudom, nem szeret ő téged.
Nemcsak hogy szerelmet nem ismer,
Szegény menyecske, még meg is ver.

Ha megunod ezt az életet,
Tedd a kezembe a kezedet,
Menjünk ki a Duna partjára,
Ugorjunk együtt a Dunába!','Kis menyecske, szép kis menyecske!
Hej, miért vagy te már menyecske?
Ha te még nem volnál menyecske:
Nem volnék én kétségbeesve.','Pest, 1844. június',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,153,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-56','petofi','Hej Büngözsdi Bandi...','Hej Büngözsdi Bandi, istentelen zsivány,
Mért sikkasztottad el az én jó paripám?
Te bitangolsz mostan drága szép lovamon -
Hóhér kössön hurkot átkozott nyakadon!

Hej Büngözsdi Bandi, istentelen zsivány!
Mért csábítottad el az én kedves babám?
Te öleled most szép szeretőm valahol -
Fűljön rosz lelkeddel a mélységes pokol!

De mi haszna van az átkozódásoknak...
Imádkozzál, Bandi, hogy meg ne kapjalak;
Mert ha megkaphatlak - mennykő üssön beléd! -
Megemlegeted a magyarok istenét.','Hej Büngözsdi Bandi, istentelen zsivány,
Mért sikkasztottad el az én jó paripám?
Te bitangolsz mostan drága szép lovamon -
Hóhér kössön hurkot átkozott nyakadon!','Pest, 1844. június',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,154,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184402-57','petofi','Bucsú a szinészettől','Adom tudtára mindazoknak,
Kiket tán sorsom érdekel,
Hogy tiszta látkörét jövőmnek
Sötét, nehéz köd lepte el.
Eddig Thalia papja voltam,
Most szerkesztő-segéd leszek.
Isten veled, regényes élet!
Kalandok, isten veletek!

Szép élet a szinészi élet,
Ki megpróbálta, tudja jól,
Bár ellene a balitélet
Vak órjásának nyelve szól.
Hogy én lelépek a színpadról,
Szívem nagyon, nagyon beteg -
Isten veled, regényes élet!
Kalandok, isten veletek!

Igaz, hogy ottan a rózsának
Sokkal nagyobb tövise van,
De oly rózsákat, mint ott nőnek,
Máshol keresni hasztalan.
Mindezt szivemben igazolják
Két évi emlékezetek.
Isten veled, regényes élet!
Kalandok, isten veletek!

Mert nem lesz már nekem kalandom;
Pedig e nélkül a világ
Előttem úntató, kietlen,
Egyalakú, nagy pusztaság.
Ki egy országon átfuték, most
Egy kis szobában űlhetek -
Isten veled, regényes élet!
Kalandok, isten veletek!

De sorsom egykor még ezt mondja,
Ha majd rám megbékülve néz:
"Eredj, ahonnan számüzélek,
Légy ami voltál, légy szinész!"
Hát addig is, mig újra, elzárt
Mennyországomba léphetek:
Isten veled, regényes élet!
Kalandok, isten veletek!','Adom tudtára mindazoknak,
Kiket tán sorsom érdekel,
Hogy tiszta látkörét jövőmnek
Sötét, nehéz köd lepte el.','Pest, 1844. június végén',1844,'1844',array['Természet']::text[],'{}'::text[],false,155,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-58','petofi','A csavargó','Önkénytelen az ember,
Mindenre születik,
Mint a magasb hatalmak
Ott fönn elvégezik.
Fölöttem is határozott
Az égi végzemény:
Csavargónak születtem,
Csavargó vagyok én.

Betérek Debrecenbe
Bolond Istók gyanánt,
S tovább megyek, ha ittam
Bort és öleltem lyányt.
Ma itten, holnap ottan,
Csak ez az élemény...
Csavargónak születtem,
Csavargó vagyok én.

Igaz, most a cudar sors
Rútul bánik velem:
Lekötve hívatalhoz
Tengődöm egy helyen.
De nem tart ez sokáig,
Igy biztat a remény;
Mint voltam eddig, újra
Csavargó leszek én.','Önkénytelen az ember,
Mindenre születik,
Mint a magasb hatalmak
Ott fönn elvégezik.','Pest, 1844. június végén',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,156,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-59','petofi','Pusztán születtem...','Pusztán születtem, a pusztán lakom.
Nincs födeles, kéményes hajlokom;
De van cserényem, van jó paripám:
Csikós vagyok az alföldi rónán.

Szőrén szoktam megűlni a lovat,
Ha ide vagy oda útam akad;
Nem szükséges a nyereg a hátán -
Csikós vagyok az alföldi rónán.

Gyócs a gatyám, patyolat az ingem.
Nem vettem, a rózsám varrta ingyen.
Hej, maholnap az én piros rózsám
Csikósné lesz az alföldi rónán.','Pusztán születtem, a pusztán lakom.
Nincs födeles, kéményes hajlokom;
De van cserényem, van jó paripám:
Csikós vagyok az alföldi rónán.','Kúnszentmiklós, 1844. július',1844,'1844',array['Természet']::text[],'{}'::text[],false,157,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-60','petofi','Megy a juhász szamáron...','Megy a juhász szamáron,
Földig ér a lába;
Nagy a legény, de nagyobb
Boldogtalansága.

Gyepes hanton furulyált,
Legelészett nyája.
Egyszercsak azt hallja, hogy
Haldoklik babája.

Fölpattan a szamárra,
Hazafelé vágtat;
De már későn érkezett,
Csak holttestet láthat.

Elkeseredésében
Mi telhetett tőle?
Nagyot ütött botjával
A szamár fejére.','Megy a juhász szamáron,
Földig ér a lába;
Nagy a legény, de nagyobb
Boldogtalansága.','Kúnszentmiklós, 1844. július',1844,'1844',array['Haza']::text[],'{}'::text[],false,158,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-61','petofi','Vizet iszom','Figyeljetek reám,
És oh bámuljatok!
Mert nem mindennapi,
Amit most hallotok.
E dolgon magam is
Nagyon csodálkozom,
De mégis szent igaz:
Nem bort... vizet iszom,
Vizet bizon.

A szőlőket tavaly
Elverte tán a jég?
Vagy a dér csipte meg
S bor nem termett elég?
Nem volt se'' jég, se'' dér,
Bor terme gazdagon,
De mindazáltal én
Nem bort... vizet iszom,
Vizet bizon.

Vagy tán azt vélitek:
Hogy szomjas nem vagyok?
Dehogy nem! szomjaim
Krisztustalan nagyok.
S kizárólag pedig
A borra szomjazom,
De mindazáltal én
Nem bort... vizet iszom,
Vizet bizon.

Hogy rajta senki ne
Csigázza az eszét,
Megfejtem röviden
E találós mesét:
Én a bort rendesen
Kocsmából hozatom,
Most pénzem nincs - vizet,
S nem bort, azért iszom,
Azért bizon!','Figyeljetek reám,
És oh bámuljatok!
Mert nem mindennapi,
Amit most hallotok.','Pest, 1844. július',1844,'1844','{}'::text[],'{}'::text[],false,159,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-62','petofi','Carmen lugubre','Meghalt... ki?... azt mit kérditek!
Hisz a név ugysem teszi meg;
Hazánknak... oh nem! a világnak
Egy ritka, példás féria,
Kinek szent fogadása tartá:
Vizet soha nem innia.

Ő most békével alhatik
Sírjában ítéletnapig;
Mert ama boldog öntudattal
Dugá fejét a föld alá:
Hogy a vizet ugyan használta
(Mosdásra), de meg nem ivá.

Nagyon szüken termett tavaly
A bornemű dicső ital.
És ez lett megölő betűje
A szilárd lelkü férfinak:
Szomjan halt, ahogy pincéjéből
Minden borok kifogytanak.

És engem, nem tagadhatom,
Kinos sejtésnek terhe nyom.
Ha jövendőben következnek
Borban szükölködő napok:
Miként e sírba dőlt nagy férfi,
Még magam is ugy járhatok.','Meghalt... ki?... azt mit kérditek!
Hisz a név ugysem teszi meg;
Hazánknak... oh nem! a világnak
Egy ritka, példás féria,','Pest, 1844. július',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,160,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-63','petofi','Első szerelmem','Virány a mult, szorgalmatos méh
A hű emlékezet;
Meghozza méz gyanánt szivembe
Első szerelmemet.

Csak hozza is! mert az nekem haj
Mindig mi jól esék;
Hiszen e prózai világban
Nincs más költőiség.

Mint iskolás fiú, gazdámnak
Lyányát szerettem én,
S boldog valék, mert a lyánykától
Viszontszerettetém.

Mint szeretett ő! az ebédnél
Tálalni ő szokott,
S mindenkor én elémbe tette
A legjobb falatot.

És uzsonnára kaptam tőle
Sonkát s más egyebet,
Mit szép szerével a kamrából
Kihozni lehetett.

Ha jött az este, s holdvilág volt:
A kertbe illanánk,
És ott a kertben, ottan várt csak
Az üdvek üdve ránk!

Csend volt; méláza a természet
Nagy ünnepélyesen,
Csak a békák kuruttyolának
A szomszéd réteken.

Mi e regényes helyzetben
Érzelgénk boldogan;
Mondók, hogy: ejnye, hogy süt a hold,
Be szép egy este van!

...Ah, szép idők! ti elmulátok
És mindörökre tán,
Már nem terem számomra többé
Sem sonka, sem leány.','Virány a mult, szorgalmatos méh
A hű emlékezet;
Meghozza méz gyanánt szivembe
Első szerelmemet.','Pest, 1844. július',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,161,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-64','petofi','Ambrus gazda','1

Merre oly nagy széllel, Ambrus gazda?
"A kocsmába, ilyen-olyan adta!
Megharagított a feleségem.
Haragom most borral szelidítem.

S azzal járt csak jól e nyelves asszony,
Hogy tovább is nem maradtam otthon;
Mert ha még soká darál előttem,
Nem hiszem, hogy nyelvét ki nem tépem."

*

Hah, rosz asszony roszabb szolgálója!
Ambrus gazdáról e pletykát szórja:
Otthon űlne ő, de felesége
Kivetette őt a ház elébe.

2

Ambrus gazda hősleg iddogála,
Míg a bakter tízet nem kiálta.
Ekkor fölkelt és hazakotródott,
S tudja isten, most miként pusztít ott.
Á, de íme, újra visszatére -
Ambrus gazda, mi jutott eszébe?
"Hát lármázni kezde feleségem;
S lármázott, míg végig nem keféltem.
Ekkor hátat fordíték a háznak.
Reggelig most otthon nem is látnak."

*

Gaz szolgáló! csak nem nyugszik nyelve.
Másnap már meg e hírt terjesztgette:
Ambrus gazda honn volt, s visszatére,
Mert nem ereszté be felesége.','1
Merre oly nagy széllel, Ambrus gazda?
"A kocsmába, ilyen-olyan adta!
Megharagított a feleségem.','Pest, 1844. július',1844,'1844',array['Haza']::text[],'{}'::text[],false,162,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-65','petofi','Az Alföld','Mit nekem te zordon Kárpátoknak
Fenyvesekkel vadregényes tája!
Tán csodállak, ámde nem szeretlek,
S képzetem hegyvölgyedet nem járja.

Lenn az alföld tengersík vidékin
Ott vagyok honn, ott az én világom;
Börtönéből szabadúlt sas lelkem,
Ha a rónák végtelenjét látom.

Felröpűlök ekkor gondolatban
Túl a földön felhők közelébe,
S mosolyogva néz rám a Dunától
A Tiszáig nyúló róna képe.

Délibábos ég alatt kolompol
Kis-Kunságnak száz kövér gulyája;
Deleléskor hosszu gémü kútnál
Széles vályu kettős ága várja.

Méneseknek nyargaló futása
Zúg a szélben, körmeik dobognak,
S a csikósok kurjantása hallik
S pattogása hangos ostoroknak.

A tanyáknál szellők lágy ölében
Ringatózik a kalászos búza,
S a smaragdnak eleven szinével
A környéket vígan koszorúzza.

Idejárnak szomszéd nádasokból
A vadlúdak esti szürkületben,
És ijedve kelnek légi útra,
Hogyha a nád a széltől meglebben.

A tanyákon túl a puszta mélyén
Áll magányos, dőlt kéményü csárda;
Látogatják a szomjas betyárok,
Kecskemétre menvén a vásárra.

A csárdánál törpe nyárfaerdő
Sárgul a királydinnyés homokban;
Odafészkel a visító vércse,
Gyermekektől nem háborgatottan.

Ott tenyészik a bús árvalyányhaj
S kék virága a szamárkenyérnek;
Hűs tövéhez déli nap hevében
Megpihenni tarka gyíkok térnek.

Messze, hol az ég a földet éri,
A homályból kék gyümölcsfák orma
Néz, s megettök, mint halvány ködoszlop,
Egy-egy város templomának tornya. -

Szép vagy, alföld, legalább nekem szép!
Itt ringatták bölcsőm, itt születtem.
Itt borúljon rám a szemfödél, itt
Domborodjék a sír is fölöttem.','Mit nekem te zordon Kárpátoknak
Fenyvesekkel vadregényes tája!
Tán csodállak, ámde nem szeretlek,
S képzetem hegyvölgyedet nem járja.','Pest, 1844. július',1844,'1844',array['Természet']::text[],'{}'::text[],false,163,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-66','petofi','Kedves vendégek','Oh ez az ostoba falusi nép!
Irják, hogy majd feljőnek Pestre. Szép.
S meglátogatnak. Még szebb. Jőjetek.
Hanem meg is szököm előletek.

Pompás mulatság lenne. Képzelem.
Bejárnák Tolnát, Baranyát velem.
Vezetném őket, mint nyájt a szamár.
Jaj, ha tudnák, mint várom őket már.

Jeles család is. Annyit mondhatok.
Körében borzasztóan mulatok.
A táti, ez derék legény. Derék.
Az embert mostan is magázza még.
S mily érdekes hallgatni, hogyha szól
Trágyárul, béresekről, gyapjuról.
És kérdi tőlem: hogy kel most a zab?...
A búza?... árpa?... széna?... krumpli?... bab?...

Költői dolgok mindenekfelett,
Csak ugy hizik tőlök a képzelet.
A mámi, ez már művelt egy személy,
Még az irodalomról is beszél.
Könyvtára van szobája ablakán.
A könyvtár dísze Szigvárt, Kártigám.
És a kisasszony, oh be kellemes.
Mint a sült rák, olyan szemérmetes.
Mindig pirúl. S mi bájjal társalog.
"Igen" s "nem" nála az egész dolog.
Vigan vagyunk. Valóban. Ha ezek
Meglátogatnak, majd lesz élvezet.','Oh ez az ostoba falusi nép!
Irják, hogy majd feljőnek Pestre. Szép.
S meglátogatnak. Még szebb. Jőjetek.
Hanem meg is szököm előletek.','Pest, 1844. július',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,164,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-67','petofi','A boldog Pestiek','Hiába is dicséritek
A szép természetet!
Az tart legföljebb veletek,
Ki rosz gombát evett.
Szegény, szegény falusiak!
S kisvárosbéliek!
Mi élünk csak valódilag,
Mi boldog pestiek!

Lakásunk fényes palota;
Mindent találni benn,
Mit a mesterség adhata,
Hogy légyen kényelem.
Selyem, rugalmas pamlagunk
Lágy hintaként remeg;
Egész török basák vagyunk
Mi boldog pestiek!

És mindennap véghezviszünk
Nagy epikuri tort,
Hol étket és italt nekünk
Sok cifra szolga hord;
Míg a zenének hangjai
Vígan fölzengenek,
Lelkünk elandalítani. -
Mi boldog pestiek!

Hát a színház? a táncterem
És több efféle hely?
Kapunk alatt hintó terem,
S mint a villám visz el.
Igy múlik éjünk és napunk,
Nincs híja semminek,
Mig végre csődöt nem kapunk
Mi boldog pestiek!','Hiába is dicséritek
A szép természetet!
Az tart legföljebb veletek,
Ki rosz gombát evett.','Pest, 1844. július',1844,'1844','{}'::text[],'{}'::text[],false,165,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-68','petofi','Színházban','Nézz le immár, nézz le, lelkem!
Nézz le kissé páholyodból,
Nézz reám szép szemeiddel...
Egy percig csak... irgalomból!

Ha te tudnád... ah, ha tudnád...
Elbájoltál véghetetlen!
Itten állok minden este,
Mint a bálvány, merevedten.

Ma sem volt, csak egy forintom,
Melyet vacsorára szántam...
S jegyet vettem rajta!... még sincs,
Nincs szimpátiád irántam?

Mégsem nézesz rám?... o nézz le!
Itten állok közeledben,
S akkorákat sóhajtok, hogy
Még a kárpit is meglebben.

Nézd, a bú mint fintoritja
Szentimentális pofámot...
Ugy de bánod is te mindezt!...
''Sz az malheuröm, hogy nem bánod.','Nézz le immár, nézz le, lelkem!
Nézz le kissé páholyodból,
Nézz reám szép szemeiddel...
Egy percig csak... irgalomból!','Pest, 1844. július',1844,'1844',array['Természet']::text[],'{}'::text[],false,166,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-69','petofi','Szobámban','Esős idő van; szürke a menny,
Mint a bakancsos-köpönyeg.
Arról szó sincs, hogy kiderűljön,
Sétálni hát már nem megyek.

Mit kéne tennem? feleséget
A jóisten még nem adott;
Ha feleségem volna: véle
Majd eltréfálnám a napot.

Pipára gyujtok, s az esőnek
Halk susogását hallgatom,
És végigszállok gondolatban
A messze fekvő multakon.

Sokon mentem már én keresztül,
Sok jót értem, de több roszat,
S nagyrészt magamnak kell köszönnöm,
Hogy megvalljam az igazat.

Könnyelmüség, könnyelmüség! ez
Gyakorta oly lépésre vitt,
Melynek később vásott fogakkal
Ettem fanyar gyümölcseit.

De bátran mondom: más hibám nincs
A könnyelműségen kivűl,
S ez majd a maga idejében
Az ifjusággal elröpűl.

Viszontagságos életemnek
Egy hű, igaz barátja van,
Egyetlen ő, ki nem hagyott el
Balsorsom háborúiban.

Velem volt ő, mig a hazában
Bujdosva jártam, mint a vad,
És ittam a forrás vizéből,
S alvám a szabad ég alatt;

Velem volt ő, mig a hazán túl
Naponta négy krajcár dijért
Hiven fogyasztám a katonák
Sületlen, sótlan kenyerét:

Velem volt ő, mig a könyűkkel
Sózott szinészi kenyeret
Megpaprikázták bosszusággal
Ármánykodó gazemberek.

Ez egy barátom a költészet.
Ő volt mindenkor énvelem,
Verseltem én minden bajom közt
A színpadon s az őrhelyen.

Leend-e haszna verseimnek?
Túlélik-e majd apjokat?
Ragyognak-e holdként fölöttem,
Ha sírom éje befogad?...

De már derűl! szivárvány támad
Amott a rákosi mezőn,
Sétára hát... csak el ne csipjen
Valamelyik hitelezőm.','Esős idő van; szürke a menny,
Mint a bakancsos-köpönyeg.
Arról szó sincs, hogy kiderűljön,
Sétálni hát már nem megyek.','Pest, 1844. július-augusztus',1844,'1844',array['Természet']::text[],'{}'::text[],false,167,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-70','petofi','Est','A nap lement.
Eljött a csend.
Szellőüzött
Felhők között
Merengve jár
A holdsugár.
Mint rom felett
A képzelet.
A városi
Nem élvezi;
Falun keresd:
Mi szép az est.
Utcára mén
Leány, legény,
S dalolni kezd;
Hallván a neszt,
Dalol vele
A fülmile
Lágy éneket
A lomb megett.
A kert alól
Furulya szól;
A pásztor ott
Tüzet rakott:
S mig elterűl
A tűz körűl,
S megszólal a
Bús furulya:
Ökre, lova
Jár tétova,
És harmatos
Füvet tapos.
Akközben a
Kert ajtaja
Halkan kinyíl;
Miként a nyíl
Odasuhan
Vig-boldogan
A pásztor, és
Van ölelés,
Van csókolás -
Ki volna más,
Ki eljöve?
Mint szép hive.
Mulassatok,
Ti boldogok!...
Mért köztetek
Nem lehetek?','A nap lement.
Eljött a csend.
Szellőüzött
Felhők között','Pest, 1844. július-augusztus',1844,'1844',array['Természet']::text[],'{}'::text[],false,168,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-71','petofi','A régi jó gvadányi','Kegyelmednek már rég pihen a pennája,
Kegyelmednek régen megyilt a sír szája,
Hol békességgel a föltámadást várja,
De még most is kedves nekem a munkája.

Nincs abban sok cifra poétai szépség,
De vagyon annál több igaz magyar épség,
S nagy mértékben aztat bélyegzi elmésség,
Azért is olvasni lelki gyönyörűség.

Sok számos poéta vagyon mostanában,
Fogyasztják a tintát nagy Magyarországban
Sokan, de nem írnak úgy, mint hajdanában
A kegyelmetek jó régi világában.

Ember azt sem tudja, hol tanultak nyelvet?
Beszédjek, nem tudni, magyar-e vagy német?
Magyar konstrukció végkép elenyészett,
S nagy szomorúsággal lehet nézni eztet.

Szomorú dolog ez s valóságos csúfság;
Gyötri lelkeiket gyalázatos hívság,
Hívságtól üldözve a kalamust fogják,
S édes anyánk nyelvét szörnyen megrongálják.

Illendőképen aki nem tud beszélni
És fundamentomos magyarsággal élni,
Ki kellene minden olyat küszöbölni,
Nem kellene hagyni magyar nyelvet ölni.

Ha kegyelmed mostan sírból föltámadna,
S ilyen magyarságot könyvekből olvasna:
Élni, jól tudom, hogy nem igen kívánna,
De halottaihoz újra visszaszállna.

Nyugodjék kegyelmed csendes békességgel!
Appetitusomat ha korcs magyarok el-
Rontják: mulatok a kegyelmed könyvével,
Könyvének igazi magyar beszédjével.','Kegyelmednek már rég pihen a pennája,
Kegyelmednek régen megyilt a sír szája,
Hol békességgel a föltámadást várja,
De még most is kedves nekem a munkája.','Pest, 1844. július-augusztus',1844,'1844',array['Haza','Elmúlás']::text[],'{}'::text[],false,169,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-72','petofi','Az utánzókhoz','Azt gondoljátok: a költés szekér,
Mely ballag széles országútakon?
Sas a költés; hol nem járt senki sem,
Ő arra indul fennen, szabadon.

S az élhetetlen nyomorú csoport
Azt lesi gyáván: merre nyílik ut?
S ha nyílik aztán, mint éhes kutya
A konc után, a kezdett útra fut.

Fogj tollat és írj, hogyha van erőd
Haladni, merre más még nem haladt;
Ha nincs: ragadj ekét vagy kaptafát,
S vágd a földhöz silány dorombodat!','Azt gondoljátok: a költés szekér,
Mely ballag széles országútakon?
Sas a költés; hol nem járt senki sem,
Ő arra indul fennen, szabadon.','Pest, 1844. július-augusztus',1844,'1844',array['Természet']::text[],'{}'::text[],false,170,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-73','petofi','Élet, halál','Boldog, kinek fejére
Az ég oly sorsot mért,
Hogy bor- s leányért éljen
És haljon a honért.','Boldog, kinek fejére
Az ég oly sorsot mért,
Hogy bor- s leányért éljen
És haljon a honért.','Pest, 1844. július-augusztus',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,171,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-74','petofi','Egy telem Debrecenben','Hej, Debrecen,
Ha rád emlékezem!...
Sokat szenvedtem én tebenned,
És mindamellett
Oly jól esik nekem,
Ha rád emlékezem, -

Pápista nem vagyok.
És mégis voltak böjtjeim, pedig nagyok.
Jó, hogy az embernek csontfoga van,
Ezt bölcsen rendelék az istenek,
Mert hogyha vas lett volna a fogam,
A rozsda ette volna meg.

Aztán a télnek kellő közepében
Kifogya szépen
A fűtőszalmám,
S hideg szobában alvám.
Ha fölvevém kopott gubám,
Elmondhatám,
Mint a cigány, ki a hálóból néze ki:
"Juj, be hideg van odaki''!"

S az volt derék,
Ha verselék!
Ujjam megdermedt a hidegben,
És ekkor mire vetemedtem?
Hát mit tehettem egyebet?
Égő pipám
Szorítgatám,
Míg a fagy végre engedett.

Ez ínségben csak az vigasztala,
Hogy ennél már nagyobb inségem is vala.','Hej, Debrecen,
Ha rád emlékezem!...
Sokat szenvedtem én tebenned,
És mindamellett','Pest, 1844. július-augusztus',1844,'1844',array['Természet']::text[],'{}'::text[],false,172,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-75','petofi','Hozzá','Szent borzalommal nyujtom ím feléd
Nem földi kéjtől reszkető kezem,
S enyém vagy-e? valóban az enyém?
Nem álmodom-e? félve kérdezem.

Ó nem, nem álom! hallom hangjaid,
Az andalító édes hangokat,
És arcaidnak látom líljomát,
És itt pihensz, hol hév szivem dagad.

Mennyit nem küzde a balsors velem,
Mig valahára mégis engedett,
Mig a dicső percet megérhetém,
Hol sajátomnak mondlak tégedet.

Sajátom vagy! s e boldogságomat
Kinek, vajon kinek köszönhetem?
Isten megáldja kedves verseim!
Ők, ők szereztek meg téged nekem.

Engedd, hogy még egyszer nézzek reád.
S szorítsanak szivemhez e kezek!
És most... és most... jer a zsebembe, pénz,
S menjünk, először is csizmát veszek.','Szent borzalommal nyujtom ím feléd
Nem földi kéjtől reszkető kezem,
S enyém vagy-e? valóban az enyém?
Nem álmodom-e? félve kérdezem.','Pest, 1844. augusztus elején',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,173,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-76','petofi','Egressy gáborhoz','Megénekellek!... de te lész oka,
Ha énekem tán szabadon nem szárnyal:
Lerészegítéd szomjas lelkemet
Művészetednek édes italával.
Megénekellek... ámbár vakmerőség
Igy fölhangolni kis nádsípomat.
Legyen mentségem, hogy amilyen gyönge,
Oly szívbül-ömlő tiszta hangot ad.

Gyakran nem érti emberét a kor;
Nagyot teremt nagy lelke erejébül,
És ez bukása! népét fölviszi
Olyan magasra, honnan az leszédül.
Még jó, ha költőt ér e balszerencse,
Az ész holt fénye egykor föllobog,
S feltámadását fogják ünnepelni
Világosabban látó századok.

Egészen más a színész végzete.
Lekötve csügg ő egy rövid bilincsen -
Ez a jelen; csak erre számolhat,
Mert a jövőhöz semmi köze nincsen.
Ha a jelennek biztos fövenyébe
Le nem bocsátá híre horgonyát:
Elmegy nevével az idő hajója,
És menni fog az örökléten át.

Vakon mért tartja a sors korodat,
Hogy meg ne értsen? nemzetem müvésze!
Avagy - kivéve egy-kettő talán -
Méltányolólag, lelkesedve néz-e?
Születtél volna boldogabb hazában,
Hol érdemeknek kedvezőbb az ég:
Dicsőségednek fényes ragyogása
Egy félvilágra elsugárzanék.

Eljőnek ők, és néznek hidegen,
És tőled egyre csak nagyot kivánnak;
Nem értik azt ők, mily kis száma van
A sikerűlés remek órájának.
A költő ír, csak hogyha kedve tartja.
A képiró, ha kedve tartja, fest...
És a szinészt befogják az igába,
Habár halállal sujtja őt az est.

S mit szóljak arról, aki ellened
Viseltetik rút, pártos szenvedéllyel?
Ki koszorúd, mit néhányan fonánk,
Dühös kezekkel tépné szerteszéjjel?
Oh mert van ilyen, és pedig nem egy van;
Hogy is ne volna?... magyarok vagyunk,
A párt, a párt és mindörökké csak párt
Sok század óta átkos jelszavunk. -

S mindekkorig te el nem csüggedél,
A zsibbadásnak terhe nem lepett meg,
Hogy ily kevés, ily kétes bére van
Sok átvirasztott, puszta éjjelednek.
De nem, jutalmad nem fog elmaradni!
Megtisztuland az érzet és az ész,
És eljövend a méltánylás idője,
Midőn mindnyájunknak kedvence lész.','Megénekellek!... de te lész oka,
Ha énekem tán szabadon nem szárnyal:
Lerészegítéd szomjas lelkemet
Művészetednek édes italával.','Pest, 1844. augusztus 7.',1844,'1844',array['Haza','Természet']::text[],'{}'::text[],false,174,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184403-77','petofi','Ezrivel terem a fán a meggy...','Ezrivel terem a fán a
Meggy...
Feleségem van nekem csak
Egy;
De mikor még ez az egy is
Sok!
Előbb-utóbb sírba vinni
Fog.

Furcsa istenteremtése
Ő!
Reszketek, ha közelembe
Jő.
Megteszek mindent, amit csak
Kér,
Mégis mindig dorgálás a
Bér.

Már ilyesmit is gondoltam
Én:
Megverem... bírok vele, hisz
Vén.
De mikor a szemem közé
Néz:
Minden bátorságom oda-
Vész.

Három izben volt már félig
Holt;
Jaj istenem! be jó kedvem
Volt.
De az ördög sosem vitte
El;
Oly rosz, hogy az ördögnek sem
Kell.','Ezrivel terem a fán a
Meggy...
Feleségem van nekem csak
Egy;','Pest, 1844. augusztus',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,175,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184404-78','petofi','A helység kalapácsa','Hősköltemény négy énekben

Első ének

Szeretnek az istenek engem,
Rémítő módra szeretnek:
Megajándékoztanak ők
Oly ritka tüdővel,
Mely a csatavészek
Világrendítő dúlakodásit
Illendőn elkurjantani képes,
S melyet tőlem minden kántor irígyel.
És hogy férfi legyen,
Méltó e tüdőhöz,
Lön az égi hatalmak irántami hajlandóságából
A széles tenyerű Fejenagy,
A helységi kovács,
Vagy mint őt a dús képzeletű nép
Költőileg elnevezé:
A helység kalapácsa. -
Ti, kik erős lélekkel birván,
Meg nem szeppentek a harci morajtól,
Halljátok szavamat!
De ti, akiknek szíve
Keményebb dolgoknál
A test alsó részébe hanyatlik,
Oh ti kerűljétek szavamat!

*

"Ámen!" szólt az áhítat
Szent hangján
A menny szolgája; s az egyház
Négy fala, régi szokása szerint,
Komolyan mondotta utána, hogy: "Ámen."
A nép pedig, amely esti imára
Gyűlekezett a szentegyházba, azonnal
Elhordta magát,
S egy-egy kancsó bor előtt
Otthon vagy a csapszék asztala mellett
Dícsérte az istent.
A becsukott templomban csend lett;
Nagyobb csend nincs a mocsárok partjainál sem,
Mikor a gém, bíbic s béka elalszik.

Csend vala hát;
Csak két éhes pók harcolt
Életre, halálra
Egy szilvamagon-hízott légy combja felett;
De, oh balsors! a combot elejték.
Egy egér fölkapta, s iramlott
Véle az oltár háta mögé
A tiszteletes reverendájába,
S lakomáz vala,
S a pókok szeme koppant.

Hah, de mi szörnyű zaj,
Mily lárma riasztja
Egyszerre az egyház
Temetői nyugalmát!
Mennydörgés?
Vagy kásának forrása fazékban?...
Nem!
Ott ember hortyog.

Ugy van! ez emberalak.
Egy zugban két öklére hajolva
Alszik... hanem íme fölébredt,
Miután elhortyantotta magát.
Ásít... szemeit dörzsölve körülnéz...
Lát és sejt... sejtése pogány.
Megy az ajtóhoz; megrázza kilincsét.
És rázta hiába.
Éles eszével
Átlátta azonnal
A dolog állását,
És ezt mondotta: "Bezártak."
S még egyszer mondotta: "Bezártak."
Azután, mint férfihoz illik,
Téged híva segédül,
Lelki jelenlét!
S kére: ne hagyd el.
S te nem hagytad el őt.
Védő szárnyadnak alatta
Ily gondolatok születének
Nem tökkelütött koponyájában,
Mialatt orrát mutató ujjára tevé:

"Hogy szabadúljak?
Kiabálni potyára.
Valamint a puskagolyóbics
Kétannyira nem megy,
Mint amennyire megy:
Szintugy az emberi hang.
Igy hát hahogy orditanék is:
Meghallani nem volnának
Képesek a falubéli fülek,
Mert innen a helység
Majd félórányira fekszik
Lenn a völgy tekenőjében. -
Leugorjam az ablakon által?
Az igaz, gyerkőce-koromban
A cseresznyefa legtetejéről
Gyakran ugortam alá,
Ha csősz-szagot érzék.
De az régen volt. Már az idén
A negyvenedikszer
Értem meg a krumplikapálást.
Lelkem hüvelyét
A férfiuság kora
Megnehezíté;
S ha leugornám:
Nyakamat szegném,
Vagy más bajom esnék."

Igy főzte a gondolatok seregét
Feje bográcsában
A bölcs férfiu, aki
Az idén már negyvenedikszer
Éré meg a krumplikapálást.
Ezután folytatta tünődve:

"Mást kell kitalálnom...
Vagy itt húzom ki az éjet,
S ez nem lesz módnélkűli mulatság."
S komoran nézett a híg levegőnek
Egy pontjára,
Miként a gólyamadár néz
Fenekére a tónak,
Mikor a prédát lesi, mellyel
A kémény tetején
Várakozásba merűlt fiait
Megvendégelni akarja.

"Megvan... ahá, megvan!" rikkanta,
S komoly orcájára derű jött:
Mint kiderűl példának okáért
A föld, mikor a nap
Letépi magáról
A felhők hamuszín ponyváját;
Szintén így kiderűl
A sötétlő konyha is éjjel,
Ha kólyika kezdi gyötörni
A mopszli-kutyácskát,
S a tekintetes asszony
Réműlve kiált
A cselédi szobába:
"Panni te! kelj fel,
Rakj tüzet, és melegíts téglát...
De szaporán!"
Panni pediglen
Föltápászkodik... egy-két
Botlásnak utána
Kijut a konyhába... kovával, acéllal
Meggyujtja a taplót,
Taplóval a kéngyertyát,
Kéngyertyával a szalmát,
Szalmával a fát,
Hogy téglát melegítsen
Hasacskájára a mopszli-kutyának.
Mondom: valamint ilyenkor
Kiderűl a konyha sötéte,
Úgy oszlott a ború
Hősünk komor orra hegyéről,
Midőn e szót ejtette ki: "Megvan!"

S a kiváncsi világ azt kérdi: mi van meg?
Hegyezd füledet,
Kiváncsi világ!
Lantom neked elzengendi: mi van meg.
S ha ekkorig aggodalommal
Néztél hősünk sorsának elébe,
S netalántán arcodat
Érette a búnak könnye füröszté:
Most már szemeid pilláin
Az öröm könnyének
Gyöngye ragyoghat,
Mint fekete átila-dolmányon
A csínos ezüst gomb -
Mert megvagyon a szabadúlás terve,
Jeles terv! illő
Ily okos emberhez.

"Sikerűlni fog, és sikerűlnie kell!"
Mondá a szentegyházi fogoly diadalmasan.
"A toronyba megyek fel,
És a toronyablakon által
Leereszkedem
A harang kötelén...
De ha megkondúl?
Majd úgy intézzük a dolgot,
Hogy szólni ne tudjon:
A kötél jó hosszu."

Mig a bölcs férfiu tervét,
Leleményes eszének
Fényes tanuját,
Teljesülés koronázza:
Pihennénk tán egyet - aztán
Uj erővel
Térjünk a tettek más mezejére.

Második ének

Regényes domb tetejében
A helység nyúgati részén,
Honnan faluszerte
Legjobban látni sarat, port,
Már mint az idő járása vagyon; -
Mint mondom: a helység
Nyúgati részén,
Környékezve csalántól
S a növények több ily ritka nemétől,
Áll a díszes kocsma, amelyet
Sajátjának nevez
Isten kegyiből
És egykori férjének szorgalmából
A szemérmetes Erzsók asszony...
Mint őt nevezék.

Lantom, kegyes égnek ajándoka! zengd el:
Honnan ez elnevezés.

Erzsók asszonyom ékes,
Holdkerek arculatán, - hol még csak
Ötvenöt év lakozik, -
Örökös hajnalnak
Pirja dereng.
S innen ez elnevezés.
Vannak ugyan, kik
Állítni merészek,
Hogy Erzsók asszonyom arcát
Nem a szende szemérem,
Hanem a borital festette hasonlóvá
A hajnali pirhoz.
De ezek csak pletyka beszédek;
Mert Erzsók asszony nem is issza a bort...
Csak ugy önti magába.
Ilyen a rágalom aztán!
Oh, ez előtt nincs
Szentség a föld hátán,
A legszűzebb ártatlanságnak
Tiszta vizét is
Bémocskolja iszappal,
A hóra sarat hány,
És... de hová ragadál?
Oh felhevülésnek
Gyors talyigája!

Vissza tehát
A szemérmetes Erzsók
Ötvenöt éves bájaihoz.

Bájos vala ő!
Mint a pipacsból
Font koszorú,
Vagy mint a bakter dárdájába ütődött
Éjjeli holdsúgár,
És ennek okáért
Látogatá őt
Az egész falu népe
Oly szorgalmatosan;
Elannyira, hogy
Be se'' nézett más kocsmába...
Az igaz, más kocsma nem is volt
A faluban.

Ide járt hát
A falu népe, kivált
Vasárnapi délnek utána,
És nagy mértékben vígadozott,
S a vígadozásnak
Végéről szó sem volt,
Mig a kisbírói tekintély
Tudtokra nem adta
Szívreható mogyorófa-beszéddel,
Hogy már hazamenni tanácsos.

Ma is így megy
A szemérmetes Erzsóknál.
Az isteni tisztelet elmúlt,
A csapszék népesedik,
Valamint a mezőség,
Hol a tehenek csordája legel,
Megnépesedik
Kétszárnyú seregélyekkel
A nyári napoknak
Forró idejében.

Jelen volt
Közepette a vendégek seregének
A helybeli lágyszivü kántor,
Torkának szárazságával
S szerelemvágyas kebelének
Tengerkínjaival.
Őt ugyanis
A szemérmetes Erzsókért
Öröműző lángok emészték,
Mint a vér rozsdája emészti
Ólmos fütyköseinket, amikkel
Tisztújítási csatákban
Egymást simogatjuk.
Ki vetemednék
Bámúlatra tehát,
Hogy ő egyikével
Feje ablakinak
Le-lenéz a folyó bor
Billikomába:
A másikkal azonban
Andalgva mereng
A szemérmetes Erzsók
Kellemes arcán.

Nem maradott el
A béke barátja
Bagarja uram sem,
A csizmacsinálás
Érdemkoszorúzta müvésze.
Méltóságos termetü férfi.
Majd akkora volt ő,
Mint a bajúsz orrának alatta.
Oldala mellett
A bort szörpölte Harangláb,
A fondor lelkületű egyházfi,
Ki, mikoronta Bagarja uram
E kérdést terjesztette elébe:
"Hát Fejenagy koma hol lehet?"
Így hallatta a választ:
"Ott van, ahol van;
Hanem itten nincs... s ma alig lesz."
S miután ezeket mélytitku ajakkal
Elmondotta: kiprémzé
Szája vidékét
Sátáni mosollyal.
Bagarja uram pedig űle,
S olyformán néze szemével,
Mint nézni szokott a halandó,
Ha nem érti a dolgot.

S vala még több érdemteljes egyén
A vendégek koszorújában.

Megnyílt akközben az ajtó,
S lett széles az ő nyílása,
Mint szája a helybeli kántornak,
Mikor éneket énekel
A soksípú orgona mellett.
S ki volt, ki az ajtót
Kinyitotta imígyen?
Ha a hagyomány állításának
Hinni szabad:
Nem más, mint a vitéz Csepü Palkó,
A tiszteletes két pej csikajának
Jókedvű abrakolója.
Jöttek nyomban utána
A hangászkarnak tagjai hárman:
A kancsal hegedűs,
A félszemü cimbalmos
S a bőgő sánta huzója -
Mind ivadéki
A hősi seregnek,
Mely hajdan Nagy-Idánál
A harci dicsőség
Vérfestette babérját
Oly nagyszerüen kanyarítá
Nem-szőke fejére
S nem-szőke fejének
Göndör hajára.

A kancsal hegedűs,
A félszemü cimbalmos
S a bőgő sánta huzója
Föltelepűlt kényelmesen
A kemencének tetejére; miközben
Vitéz Csepü Palkó,
A tiszteletes két pej csikajának
Jókedvű abrakolója,
Így adta bizonyságát
Ékesszólási tehetségének:

"Bort!"

Fölfogta azonnal
A szemérmetes Erzsók
E szónoklat magas értelmét,
S eszközlé annak teljesülését
Nem fontolva haladván.

Miután a vitéz Csepü Palkó
Az orra alatti nyiláshoz
Emelte a kancsót,
És miután mértékletesen
Egyet kortyanta belőle:
(Körülbelül annyit,
Amennyivel öt vagy hat ürgét
Lehetne kicsalni lyukának
Mélységeiből,)
Annakutána
Fölnéze az ég tájéka felé -
A kemencetetőre,
S ilyféle szavakkal
Terhelte meg a levegőnek
Könnyű szekerét.
Hogy szállítná azokat
A derék hangászi fülekbe:

"Húzd rá, Peti,
A fűzfán fütyülődet is,
Aki megáldott!"

S Peti nem késett,
A háromság más ketteje sem.
Cimbalom és hegedű és bőgő
Hangot adott...
Jaj de mi hangok ezek! -
Ezeknek hallata visszaidézi
Tündérhatalommal
Emlékezetembe
Éltem legszebb idejét,
A gyermek-időt.
Látom, mint játsztam öcsémmel
S kis házi kutyánkkal.
Aztán a kutyát elvette öcsém,
Én meg nem akartam od''adni,
S így hajba kapánk.
Mi jött ki belőle?
Az jött ki belőle,
Hogy a zajra apánk kirohan,
Nálunk terem, és mindkettőnket
Jól megnadrágol.
Azalatt a kutyát mi elejtők,
S ráhágtunk farka hegyére.
Mikor e percben mindhárman
Összevisítánk:
Ez összevisítás
Alig lehetett szebb,
Mint a Peti és két társa zenéje.

És lett a zenére
A szemérmetes Erzsók
Teremében nagy vigalom.
Mindennek előtte
Összeütötte bokáját
Vitéz Csepü Palkó,
A tiszteletes két pej csikajának
Jókedvű abrakolója.
Követé e csáberejű példát
A többi legénység,
Béhurcolva szelíden
Egy pár fürge leányzót,
Kik eddig az ablakon által
Kukucskáltak kandi szemekkel,
S kiknek már viszkete talpok
A táncnak vágya miatt,
Hallván a mennyei báju zenét.
S kóválygani kezdtek
Mindnyájan a tánc gyönyörében,
Mint aki nadragulyával
Füszerezte ebédjét.
A lábak dobogása pedig
Rendes vala,
Mint ama zaj, mit
Néha a tiszteletes hall,
Mikor űl a biblia mellett,
S olvassa nagy elmerüléssel;
És amely zajra imígyen
Teszi megjegyzését
Jámbor szívvel:
"Oh az a Palkó
Istentelen ember!
Megint nyaggatja csikóimat,
A szegény párákat,
Korbácsa csapásaival."

Míg ily események
Gazdagiták a világ történeteit
A kocsmaterem közepén:
Szélről a béke barátja
Bagarja, s Harangláb,
A fondor lelkületű egyházfi,
Űltenek, ittanak egyre. -
A helybeli lágyszivü kántor
Még mindig pislogatott
A szemérmetes Erzsók
Ötvenöt éves bájaira.
Arcúlata lelki tusának
Volt tűkörözője.
Látszék, hogy valamit
Akar és nem akar,
Vagy inkább, hogy valamit
Merne, ha merne.
Mikoron meglátta Harangláb,
A fondor lelkületű egyházfi,
Hogy a lágyszivü kántor
Se'' széna, se'' szalma:
Hozzája vonúlt,
S ily szókat láta helyesnek
Intézni a késedezőhöz
Bátoritásnak okáért
Hangtalan hangon,
Mint a sugólyuk
Lakói beszélnek a színpadokon,
Holott nők s férfiak által
Szomorú- és vígjátékok adatnak
S közbe bohózatok és operák
A közönségnek gyönyörére:

"Oh kántor uram!
Hát elmegy a nap,
Megjön az alkony,
Utána az éj,
Elűlnek a csirkék
És ludak és verebek,
Mielőtt ügyesen szőtt
Tervünknek drága gyümölcse megérik? -
Gondolja meg azt komolyan
És nemcsak ugy átabotába,
Hogy századok adnak
Tervkivitelre
Egy ilyen pillanatot.
Az ilyen pillanatokkal
Fukaran kell bánni tehát
Az előre tekintő
Emberi léleknek,
Valamint fukaran bánik
Beszédeivel
Bíró uram,
A bölcs aggastyán. -
Előre tehát,
Hogy az alkalom el ne sikoljék.
Mint elsiklik néha a hal
A halásznak körme közől,
Ha ügyetlen kézzel
Kap utána az ostoba filkó. -
Rajta azért,
Oh kántor uram!
Most vagy sohasem. -
Mért engedni helyet kebelében
A félelem érezetének?
Hiszen részt vett a győri csatában."

Ekképen szóla Harangláb,
A fondor lelkületű egyházfi,
A helybeli lágyszivü kántor
Egyebet nem válaszola,
Mint ami következik:

"Oh te tudója szivem titkának!
Igaz egy betüig
Tartalma beszédidnek,
Mint igaz a szentírás.
Bölcsen tudom azt.
De amint van okom,
Nem hordani többé
A titkolt szerelemnek
Életölő fájdalmát:
Szintúgy van okom,
Elfojtani lelkem
Mélységes mélyében e titkot.
Ha ez emberek itten
Észre találnák venni?...
Avvagy ha pofon vág
A szemérmetes Erzsók
E szörnyű merényért?...
Hát feleségem,
Az amazontermészetü Márta?...
O én a legboldogtalanabb
Valamennyi teremtmény közt,
Mely látta a nap karimáját,
A sugarakban uszót,
Ha felleges ég
Vagy éjszaka nem volt! -
Olyan az én lelkem,
Mint a Duna legközepében
A szélvészhányta dereglye,
Vagy mint a dióhéj,
Mit a gyerekek
Pocsolyába vetének -
Hánykodik erre, amarra...
De bátorság! aki nem mer, nem nyer...
Oh szólj erre, Harangláb,
Mondd meg nekem: ugy van-e vagy sem?...
Akként áldja meg isten
Életedet s unokáidat is,
Amily őszinte leszen
E kérdésemre a válasz,
Amelyet adandasz!"

S őszintén szóla Harangláb,
Mondván: "Úgy van, kántor uram!"

"No, ha úgy van: hát nekivágok!"
S ezzel a helybeli lágyszivü kántor
Fölemelte s letette a kancsót;
Csakhogy mikoron fölemelte,
Csordultig vala az, -
És amidőn letevé,
Üres vala az,
Valamint üresek zsebeim
Most, mikor ezt éneklem
Nagy lelkesedéssel
Költői dühömben. -
Annakutána a lágyszivü kántor
Egyet rántott a lajblija szélén,
S kétségbeesett elszántsággal,
Mint aki hidegfürdőt
Éltében először használ,
Odarontott
A szemérmetes Erzsókhoz.

Harmadik ének

Oh nagyon is jószívü közönség,
Különösen ti,
Szép lyánykái hazámnak,
Kiket annyira szeretek én,
Hanem akiktől
Nem nyerek egy makulányi szerelmet, -
Ha szépen kérlek benneteket:
Ugye nem fogtok haragudni reám,
Hogy a helybeli lágyszivü kántornak
Szerelemvallásától
S a tánc kellő közepéből
Drága figyelmeteket
A templom tájékára csigázom?
Hol a leleményes eszű fogoly
Épen mostan ereszti
Magát lefelé a harang kötelén,
Valamint leereszkedik a pók
Gyakorta szobám tetejéről
Saját fonalán.

És íme leért,
És kutyabaja.
A kötél ugyan azt akará,
Hogy hála fejében
Hagyná ott bőrét tenyerének;
Hanem a hűséges bőr
Konokúl így szólt a kötélhez:
"Én ugyan itten nem maradok, -
Avvagy ha maradnom kell,
Hát szinte maradjanak itt
Hús és csont testvéreim is."
A kötél jó szíve megindult
E ritka bizonyságán
A szép testvérszeretetnek,
S lemonda kivánságáról.

Már este felé volt.
A nap gombóca piroslott,
Valamint a paprika
Vagy mint a spanyolviasz.
Oh te piros nap!
Mért vagy te piros?
Szégyen-e vagy harag az,
Mi arany súgáraidat
Megrezesíti,
Mint a bor az emberek orrát?
Nem szégyen, de nem is harag az,
Csak én tudom ennek okát,
Én, kit földöntúli izék
Földöntúli izékbe avattak.
Ez vésznek előjele,
Amely még ma lesujt a világra,
Miként a mészáros taglója lesujt
Az ökörnek szarva közé.
S nemcsak a nap hirdette a vészt,
A már közelállót;
Az egész természet
Elhagyta a régi kerékvágást.
Két kutya, melyek előbb
Őszinte barátságnak
Példái valának hosszu időktől,
Most egymást marta dühödve
Egy nyomorú juhbőr-darabért,
Mit a mészárszéknek előtte találtak.
S még száz ily példát zengene lantom,
Melyek mind iszonyú pusztúlást
Jóslának a földnek,
De csak a legnevezetesbet
Közleni légyen elég:
A lágyszivü kántornak felesége
Ma nem ivott meg többet
Egy messzely pálinkánál.

Igy állt a világ,
Amidőn a szentegyházi fogoly
Elereszté a mentő kötelet,
S ekképen szóla magában:
"Lenn volnék...
Hála a mennyek urának!
Most egyenest a szemérmetes Erzsókhoz.
O szemérmetes Erzsókom,
Szívem mühelyének
Örök árendása te! nemde
Vársz epekedve reám?
Valamint én várom a tiszteletestől
Kontójának megfizetését,
Melyért nála hetenként
Kunyorálok hiába.
Nem fogsz te sokáig várni reám;
A szerelem lesz sarkantyúm,
Hozzád rohanok,
Mint a malacok gazdasszonyaikhoz,
Ha kukoricát csörgetnek."

Még bé sem fejezé
Költői beszédét,
S íme rohant a szemérmetes Erzsókhoz,
Mint a malacok gazdasszonyaikhoz,
Ha kukoricát csörgetnek.
Amidőn megfogta kilincsét
A kocsmai ajtónak:
Ketyegett hő szíve erősen
Üdv-kéjek gyönyörétől.
Amint benyitott a terembe,
A tánc még egyre dühöngött,
S csak a béke barátja
Bagarja vevé őt észre,
S őszinte örömmel
Idvezlette, kiáltván:
"Jó napot adj isten,
Fejenagy koma!"
(Mert ő, a nagy férfiú, volt ez.)
"Jó napot adj isten,
Hát kelmed is eljött?"

Ezek voltak szavai
Bagarja uramnak,
A béke barátjának,
De a széles tenyerű Fejenagy,
A helység kalapácsa,
A "jó napot adj isten"-re
Nem mondta: "fogadj isten",
Nem mondott semmit,
De nem is hallotta beszédét
Bagarja komájának,
Dehogy hallotta, dehogy!...
Ő csak látott -
Oh mért kellett látnia ekkor?
Mért nem született vakon inkább?
És átaljában mért született?...
Ott látá térdepelésben
A helybeli lágyszivü kántort
A szemérmetes Erzsók
Ötvenöt éves lábainál.
E látványra szivét,
A tiszta szerelmü szivet,
Pokolbeli kínnak
Százharminchatezer bicskája
Hasitotta keresztűl
S fölgyujtá agyvelejét
A haragnak cintmasinája legott.
Mint prédájához a macska,
Zajatlan léptekkel
S szeme égő üszkével
Sompolygott a lágyszivü kántor
Háta mögé,
Aki titokban
Gyötrődő szive érzelmét
Ekkép foglalta szavakba:

"Szemérmetes Erzsók,
Koronája az asszonyi nemnek,
S kezelője a bornak
S a pálinkának!
Lesz-e engedelem számomra szivedben,
Ha lelkem tartalmát
Előtálalni merészlem?...
De nekem már mindegy, akár van,
Akár nincs engedelem számomra,
Kimondom:
Mi furja az oldalamat.
Kimondom, igen,
Nem holmi cikornya-beszéddel,
De az érzés egyszerü hangján: -
Keblem kápolnájában
A hűséges szerelemnek
Az öröklétnél
Félrőffel hosszabb gyertyája lobog
Szent lobogással.
S éretted lobog az,
O szemérmetes Erzsók!
S ha meg nem koppantod
A viszonszerelem koppantójával:
El fog aludni,
És vele el fog aludni
Életem is!...
Itt várom itéletemet;
Most, rögtön, ezennel
Mondja ki szűz ajakad:
A reménység zöld koszorúja
Öveddze-e homlokomat,
Vagy a kétségbeesésnek
Bunkósbotja
Üssön agyon?..."

"Én ütlek agyon...
Én vagyok a kétségbeesés!"
Szólt... nem! mennydörgött egy hang,
A széles tenyerű Fejenagynak hangja;
S széles tenyerével megragadá
A lágyszivü kántor gallérját,
S fölemelte a térdepelésből,
Hogy talpa sem érte a földet;
Aztán meg letevé,
Hogy az orra is érte a földet.
"Én ütlek agyon..."
Folytatta tovább
A széles tenyerű Fejenagy.
"Én morzsolom össze
Csontjaidat,
Mint a malomkő
A búzaszemet!
Hogy mertél... de előbb
Téged vonlak kérdőre, o Erzsók!
Mondd meg nekem azt:
A hűtlenségnek fekete posztaja
Vagy az ártatlanságnak
Patyolatlepedője takarja-e lelked?
Oh, szólj nekem erre!"

A szemérmetes Erzsók
Nem szóla reá,
De tengervízszínű szemének
Bájdús kifejezéséből
Ezt silabizálta ki mennyei kéjjel
A széles tenyerű Fejenagy:
"Oh széles tenyerű Fejenagy,
Helységünk kalapácsa,
S csapra ütője szivem hordójának!
Még kétkedel?...
Ártatlan vagyok én,
Mint az izé..."

Érté e néma beszédet
A helybeli lágyszivü kántornak
Dühteljes dögönyözője,
S engesztelve sohajtott:
"Lelkem lelke, bocsáss meg,
Hogy kételkedni merék
Hűséged acél láncának
Állhatatosságában. -
Most pedig, oh kántor!
Téged veszlek elő;
Készülj a meglakolásra -
Rémséges leszen az,
Valamint rémséges a bűn,
Mit elkövetél.
Példádon okúljanak a késő unokák,
Hogy kell csábítni az ártatlanságot,
Hogy kell konkolyt hinteni
Két szerető szívnek
Tisztabuzája közé!"

Miután a nyelve megállott,
Két keze kezdett mozgani
A széles tenyerű Fejenagynak:
A helybeli lágyszivü kántort
Úgy ütögette a földhöz,
Mint a gyertyát mártani szokták.

A helybeli lágyszivü kántor
Elkezdett bőgni, amint még
Nem bőgött soha
Sem temetéseknél,
Sem a soksípú orgona mellett.
Bőgése zavarnak
Lett okozója
A mulatók közt.
Megbomlott a tánc;
A kancsal hegedűs,
A félszemü cimbalmos
S a bőgő sánta huzója
Feledte tovább hallatni
Hangszere égi zenéjét.
A nép odacsődült,
Karéjt képezve, holottan
A széles tenyerű Fejenagy
Példát ada a késő unokáknak,
Hogy kell csábítni az ártatlanságot,
S hogy kell konkolyt hinteni
Két szerető szívnek
Tisztabuzája közé.
A helybeli lágyszivü kántor
Bőgései közben
Ily szókkal esengett
A helység kalapácsához:
"Csak addig várjon, amíg
Egy szócskát, egy kicsi szócskát mondok -
Aztán verjen kelmed agyon,
Ha jónak látja."

A széles tenyerű Fejenagy,
Ki már belefáradt
A példaadásnak kedvéérti
Földhözütésbe,
Ezeket szuszogá:
"Beszéljen, kántor uram!
Mentse magát,
Meghallgatom én az okos szót
Minden időben...
Mentse magát."
S a helybeli lágyszivü kántor
Igy mentette magát,
Heverve a földön:
"Bűnös vagyok egyrészt,
Nem tagadom,
Mert megszeretém
Lángzó szerelemmel
A szemérmetes Erzsókot...
De tehettem-e róla?
Oh a szerelem
Nem oly portéka, amelytől
Elzárni lehetne a szívet;
Tündéri madár ez, amelynek
Ajtó sem kell, hogy a szívbe röpüljön,
Mint bölcsen tudhatja kegyelmed. -
De szerelmemet én
Titkoltam volna örökké,
Elvittem volna magammal
A más életbe, ahol tán
Nincsen is élet -
Ha nem veszi észre Harangláb.
Ő észrevevé,
S bujtotta tüzem,
Mi okért, mi okért nem?
Arról nincs tudomásom.
Ő volt, ki, midőn ma
Az isteni tisztelet alkalmával
Kegyelmed az álomnak karjába hajolt,
Ezt javasolta nekem:
Zárjuk kelmedre az ajtót,
S így zárva levén,
Ma baj nélkűl tehetem
Hódításaimat
A szemérmetes Erzsóknál...
S én balga szavát fogadám!"
Mindezeket mondá
A helybeli lágyszivü kántor
A megbánásnak örömtelen hangján.

Mint megfordúl a rézkakas
A templom tetején,
Ha más tájról kezd fúni a szél,
Ugy vett más fordulatot
A széles tenyerű Fejenagynak
Lelke, s irányt,
Mikor e szók érinték füle dobját.
"Mit szól kend erre, Harangláb?"
Voltak szavai,
S nem szeliden mondott szavai,
"Igazolja magát kend,
Vagy akkép vágom fültövön,
Hogy azonnal megsiketűl bele."

Odaálla Harangláb,
A fondor lelkületű egyházfi,
S rendűletlen nézve szemébe
A széles tenyerű Fejenagynak,
Ily bátor szókra fakadt:
"Igazolni fogom magamat,
Nem, mintha remegnék
A kend fenyegetéseitől.
Jobban felkösse gatyáját,
Akitől meg kelljen ijednem...
Érti-e kend ezt? -
Mind igaz, amit kántor uram szólt,
Aki, úgy mellesleg mondva,
Gyáva, haszontalan ember,
Hogy oly pimaszúl rám vallott. -
Én bujtogatám őt,
Hogy csapja el a kelmed keziről
A szemérmetes Erzsókot,
Mert én kendet utálom,
Mint a kukorica-gölődint."

"Ugyan úgy-e?"

"Biz úgy ám!"

"Hát kend azt gondolja talán,
Hogy én kendet szeretem
Avval a macskapofájával?"

"Micsodával?"

"Avval a macskapofájával!"

"Macskapofámmal?
Hát te, te sündisznó!
Aki kovácsnak tartja magát,
Pedig holmi cigánytól
Tanulta meg a kalapálást..."

"Hát még mesterségemet is
Gyalázni mered?
Te hitvány templomegér...
No megállj! majd megkalapállak."

S úgy megütötte
Öklének buzogányával
A fondor lelkületű egyházfinak orrát,
Hogy vére kibuggyant.
Erre Harangláb
Ügyesen leütötte fejérül a kucsmát,
Megkapta hajának fürtözetét,
S oly istenesen kezdette cibálni,
Mint a harangkötelet.

Ez iszonyú látvány
Megragadá gyöngéd idegét
A szemérmetes Erzsóknak,
S a szegényke
Ájulat örvényébe bukott.
Bagarja, a béke barátja,
Fölemelte szelíden,
S ápolva tevé őt
Az ágy párnái közé.
Élettelenűl feküvék ott,
Mint a lepuskázott vadlúd
A tó közepén. -
De most jön a haddelhadd!

Amidőn a vitéz Csepü Palkó,
A tiszteletes két pej csikajának
Jókedvű abrakolója,
Látá, hogy komolyabb kezd lenni
A dolog fordúlata:
Fejenagynál terme serényen,
S magát frígyestársának ajánlá.
Őt kedves kötelek csatolák
A széles tenyerű Fejenagyhoz:
Nála tanúlá tudniillik
A kovács-mesterséget
Valami két hétig. -
Hanem ekkor eleblábolt,
Mert nem volt hajlama a mesterséghez.
Vakarta i''kább a lovat,
Semmint patkolta.
De azért kedveltje maradt
A széles tenyerű Fejenagy,
S neki most is "mester uram" volt.

"Mester uram!"
Kurjanta vitéz Csepü Palkó,
A tiszteletes két pej csikajának
Jókedvű abrakolója,
"Ne féljen semmit, mester uram
Itt vagyok én is."
S ezzel nekiugrék
A fondor lelkületű egyházfinak,
Hátán termett, s kezdte püfölni.
Nem bírta Harangláb
Csepü Palkónak terhét,
És összerogyott,
De véle rogyott
A helység kalapácsa is,
Mivel üstöke mindig
Marka között volt még.
Nagyszerü volt ez esés!
Igy hullnak alá a kövek
A romladozó várak tetejéről
A völgy mélységébe.
A tusázókhoz több forróvérü legény
Csatlakozék,
Két pártra szakadva.
S lett rúgás, harapás,
Fej-betörés, vérontás és a többi.

A lyányzók pedig elvonulának
A kocsmateremből,
Mint elvonul a napnak sugara,
Ha zivatar támad.
S elkotródott a lyányok után
A béke barátja Bagarja.

Negyedik ének

Merre, Bagarja uram,
Test-épületének
Élő oszlopain,
Oh merre szalad kend
Gyors szaladással,
Mint a kugli-golyóbis?
Hát férfihoz illik
Megfutamodni a harci veszélytől?
Lemondani a csatabajnak
Hősi jutalmáról,
A dicsőség tölgykoszorújáról?

Ne kárhoztassuk a jámbort!
A gondviselésnek
Választott embere ő,
Ki elhárítani termett
A végpusztúlást falujáról.
Avvagy ha nem ekképen cselekednék,
Mért híná őt a világ
A béke barátjának?

Ő e nevezetnek megfelelőleg
Intézé tette irányát,
S könnyü inakkal iramlott
Az öregbírói lakáshoz,
Amelynek előtte
Méltóságosan állott
A kaloda.

Bagarja, a béke barátja,
Alva találta
A kevés szavu bírót,
A bölcs aggastyánt.
Ottan feküvék ez
Testének egész hosszában
A pamlagon...
Azaz a fapadon.
Párnáúl ködmöne szolgált,
Az öregebbik,
Mert az ujat kímélnie kellett. -
Bagarja uram
Megdöfte az oldalbordáját,
Hogy az álom sűrü ködét
Szétoszlassa szeméről.
De korántsem volt ez
Oly könnyű munka, minőnek
Első látásra talán
Gondolja az ember.
Soká bajlódék véle Bagarja,
Míg fölnyílt az egyik szeme nagy nehezen,
S lelki nyugodtsággal kérdezte:

"Mi baj?"

"Baj van, bíró uram, és nagy baj!
Csak talpra, de gyorsan,
Ha azt nem akarja,
Hogy vége legyen helységünknek,
Vége örökre!
Kiütött a háboru, és dúl.
A szemérmetes Erzsók
Csapszéke lőn a csatatér.
Az egész falu népe
Egymást kaszabolja,
Hogy nézni iszony.
Potyognak az emberek,
Mint a legyek őszi időben.
A föld a kifutott vértől
Olyan, mint a vörös posztó.
Az enyészet gyászlobogója
Leng a szomorú csatatéren.
Tápászkodjék föl, bíró uram,
És menjünk szaporán!
Mert csak bíró uram az,
Ki követ gördíteni képes
A rohanó romlásnak elébe."
Igy végzé a csata festését
A béke barátja Bagarja.
A kevés szavu bíró,
A bölcs aggastyán,
Fölnyitva szemének másodikát is,
E kérdést látá szükségesnek:
"Hát menjünk?"

"Pedig tüstént!" volt a felelet.

"Nem bánom," szóla szokott nyugalommal
A bölcs aggastyán,
S miután új ködmöne rajta volt,
És botja kezében:
Útnak eredtek. -
Szomszéd volt a kevés szavu bíróhoz
A hívatalában pontos kisbíró.
Beszóltanak ehhez az ablakon által,
És mondák: jőne velök.
S szót fogadott a hívatalában
Pontos kisbíró,
Bár nem nagy örömmel,
Mert legszebb kedvtöltésében zavarák:
Épen feleségét verte.

Mikor a kántorlak elébe jutottak,
Az amazontermészetü Márta
Szomszédnéjával
Akkor végzette pörét,
Mely onnan eredt,
Hogy a roszlelkű szomszédné
Egy tyúkját agyonütötte,
Mert ez mindig az ő csirkéi közé járt,
S elette előlök az árpát.

Képzelni lehet,
Hogy mekkora volt dühödése
Az amazontermészetü Mártának
Hallatlan kára miatt;
De azt már képzelni lehetlen,
Hogy mekkora lett dühödése,
Amidőn a béke barátja
Tudtára adá férjének csínját.
Szólni akart,
De a szó elakadt gégéjén.
Szeme vérszinü lett
S arcúlata kék,
És reszkete minden tagja,
Valamint a kocsonnya.
Szétnézett vizsga tekintettel,
Mellette hevert egy seprőnyél,
Azt fölragadá,
S bőszülve kiálta: "Utánam!"

Amidőn a kevés szavu bíró,
A béke barátja Bagarja,
A hívatalában pontos kisbíró
S az amazontermészetü Márta
Elértenek a csatahelyre:
Iszonyú vala a látvány látása,
Amelyet láttak.
A harc járta javában.
A béke barátja Bagarja
Nem füllentett, mikor azt mondá
A kevés szavu bírónak,
Hogy az enyészet gyászlobogója
Leng a szomorú csatatéren.
Ugy volt egy betüig!
A kemence - ahonnan
A kancsal hegedűs,
A félszemü cimbalmos
S a bőgő sánta huzója
Az ifjúságot táncra vidítá
Hurjai bájos pengésével -
A kemence lezúzva
Ugy mered a levegőbe,
Mint valami sziklai vár
A tatárjárásnak utána.
Tört asztalnak s tört poharaknak
Romjai lepték
A véráztatta szobát,
S a vérnek közepette
Búsongva tünődött
Egy leharapott fül.

Az amazontermészetü Márta
Hős elszántsággal törte magát át
A vívó tömegen,
Mígnem férjére talált,
Ki egy szögletbe vonultan,
Kínjában most is nyögve, kucorgott.

Oh Hamlet! mi volt ijedésed,
Mikoron megláttad atyád lelkét,
Ahhoz képest, amint megijedt
A helybeli lágyszivü kántor
Feleségének látásán?
Egy fél-ép asztal alá bújt,
S kezeit könyörögve kinyujtá
Az amazontermészetü Mártához,
De ez nem könyörűlt.
Megfogta egyik lábszárát,
S kihúzta az asztal alól,
És addig döngette, amíg csak
A seprőnyélben tartott.
Aztán ott ragadá meg haját,
Ahol legjobban fáj,
És elhurcolta magával,
Mint a zsidó a lóbőrt;
S ekkép vígasztalta: "Jerünk csak,
Itt a világ szeme láttán
Nem akarlak csúffá tenni... de otthon
Majd megkapod a magadét!"
S miután ura volt mindenha szavának
Az amazontermészetü Márta:
Hinni lehet, hogy most sem szegte meg azt.

Azalatt a kevés szavu bíró,
A bölcs aggastyán,
Nem ékesszólásánál,
De tekintélyénél fogva
Lecsillapítá a harcnak fergetegét.
A vérontásnak idője lejárt.
Meghunnyászkodtak a küzdők,
Mint a marakodó ebek,
Amikor gazdájok előjön,
S rájok bőgi: "Kimenj!"
A háboru közkatonái
Elsompolyodának.
A fondor lelkületű egyházfi
S a helység kalapácsa
Bírói parancsra előállt,
S mindkettő fölterjesztette ügyét.
A kevés szavu bíró,
A bölcs aggastyán,
Megdorgálta keményen
A fondor lelkületű egyházfit -
S a helység kalapácsát,
Mint kezdőjét a csatának,
A hívatalában
Pontos kisbíró által
Kalodába csukatta.

Ott nyögi most fájdalmát hősünk
A kalodában,
S csak azzal vígasztalja magát,
Hogy elleneit megverte vitézül,
S ha innen az isten megszabadítja,
Megkéri azonnal
A szemérmetes Erzsókot.

*

Te pedig, lantomnak húrja, pihenj!
Nagy volt a munka, s bevégzéd
Emberül e munkát.

Én is pihenek
Babéraimon,
Miket a hírnek mezején
Borzas főmre kaszáltam.

Mostan akár ma megássa
Gödrömet a sírásó,
Bánom is én!
Azért én élni fogok,
Míg a világnak
Szappanbuboréka
Szét nem pattan.
Pislogni fog a hír mécse siromnak
Koszorús halmán,
Mint éjjel a macska szeme.

Eljő az irígység
Letépni babéraimat... de hiába!
Nem fogja elérni;
Magasan függendnek azok,
Mint Zöld Marci.

S ha sötét zsákjába dugand
A feledés:
Fölhasogatja sötét zsákját
A halhatatlanságnak fényes borotvája.

Mutató tábla,

mely azt mutatja, hogy az

I. ÉNEKBEN

fölébred álmából egy fogoly, s szabadulást tervez - azonban az
nincs megénekelve: hogy ki légyen ezen szabadulást tervező, álmából
fölébredt fogoly? csupán azért, hogy később a meglepetés annál
meglepőbb legyen. - A

II: ÉNEKBEN

már több foglaltatik: kié a helység leglátogatottabb kocsmája?
mily ékes e kocsma birtokosnéja? miben sántikál a kántor? ki
buzdítja merényének végbevitelére? sat. - A

III. ÉNEKBEN

megszabadúl a fogoly, s börtönéből a kocsmába megy; s amily szörnyű
dolgokat lát: oly szörnyű dolgokat cselekszik. Itt már az is orrára
köttetik a nyájas olvasónak, hogy a fogoly nem más, mint a költemény
hőse. - A

IV. ÉNEKBEN

a szörnyű dolgok véget érnek, s a költemény hőse szörnyű véget ér.','Hősköltemény négy énekben
Első ének
Szeretnek az istenek engem,
Rémítő módra szeretnek:','Pest, 1844. augusztus',1844,'1844',array['Természet','Szerelem','Haza']::text[],array['osz']::text[],false,176,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-79','petofi','Szülőimhez','Hej édes szülőimék,
Gazdagodjam meg csak!
Akkor, hiszem istenem,
Nem panaszolkodnak.

Minden teljesülni fog,
Amit csak kivánnak;
Megelőzöm vágyait
Éd''sapám s anyámnak.

Lesz csinos ház, amiben
Megvonúlnak szépen;
Pince lesz a ház alatt,
Jó bor a pincében.

Meghihatja éd''sapám
Minden jóbarátját;
Borozás közt lelköket
A jókedvbe mártják.

Szép kocsit csináltatok
Éd''sanyám számára;
Nem kell, hogy a templomot
Gyalogosan járja.

Lesz arany szegélyzetű
Imádságos könyve,
Krisztus urunk képe lesz
Szépen metszve benne.

Pistinak meg majd veszek
Drága paripákat,
Rajtok jó Istók öcsém
Vásárokra járhat.

Végesvégül lesz nekem
Dúsgazdag könyvtárom;
Akkor majd a verseket
Nem pénzért csinálom.

Ingyen osztom azokat
Szét az újságokba;
Minden szerkesztő, tudom,
Szívesen fogadja.

S hogyha szép lyányt kaphatok:
- De magyar lelkűt ám! -
Éd''sapám táncolni fog
Fia lakodalmán.

Így élünk majd boldogan
A mulatságoknak,
Így biz, édes szüleim...
Gazdagodjam meg csak!','Hej édes szülőimék,
Gazdagodjam meg csak!
Akkor, hiszem istenem,
Nem panaszolkodnak.','Pest, 1844. augusztus',1844,'1844',array['Család']::text[],'{}'::text[],false,177,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-80','petofi','Tompa mihályhoz','Hát, fiú, olvastam azt a verset,
Amelyet te énhozzám csináltál
Valahol a bártfai forrásnál,
S mondhatom, hogy nagy örömet szerzett.

Sok szépet elmondtál e levélben,
(Ne véld, hogy hizelgéskép beszélem,)
De legjobban az gyönyörködtetett,
Hogy a bort, öcsém, te is szereted.

Ej be derék gyerek vagy te, Miska!
Mért nem ölelhetlek összevissza?
Látszik: deák vagy és kálomista,
Aki a vizet nagy kínnal issza.

Ember a lelked is, atyámfia!
Imádkozzunk a bor istenéhez,
S hagyjuk a világot papolnia,
Hogy, ki a bort szereti, ez és ez.

Haszontalan világ ez a mai;
Egyáltaljában nem tetszik nékem.
Jőjünk csak mi össze!... fenn az égben
Örömkönnyeket sír Csokonai.

Egyébiránt ne gondold, barátom,
Hogy én valami vad fickó vagyok,
Mihelyst a bor szinét meglátom;
Nem én! csak úgy csendesen vígadok.

S ha bizalmas ember van mellettem,
Mosolyogva a bús múlt időket
Elbeszélem, hogy mennyit szenvedtem,
Mint majd egyszer elbeszélem néked.

Hidd el, csodálkozni fogsz fölötte,
Hogy huszonkét éves ember ennyi
Bajon magát keresztültörhette,
S nem birta őt a baj sírba tenni.

Az igaz, most jobb az állapotom,
Bár a legjobbnak ezt sem mondhatom;
Hanem ugy csak állok, hogy ha véled
Találkoznám, megvendégelnélek.

De miért is nem jösz egyszer hozzánk?
Majd meglátnád, milyen jól mulatnánk!
Messze vagy, de én baka koromban
Hetvenhétszer annyit gyalogoltam.

Siess hát, mert ha sokáig késel,
Élted napjáig megemlegeted;
Én rontok hozzád, s akkor jaj neked:
Agyonszorítlak egy öleléssel!','Hát, fiú, olvastam azt a verset,
Amelyet te énhozzám csináltál
Valahol a bártfai forrásnál,
S mondhatom, hogy nagy örömet szerzett.','Pest, 1844. szeptember 4-8.-a között',1844,'1844',array['Szerelem','Természet']::text[],'{}'::text[],false,178,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-81','petofi','Éjszakáim','Még ugy csak megjárja, ha az ég
Fellegetlen, holdas, tisztakék.
Ablakomra rákönyökölök,
Hosszú szárból sűrűn füstölök,
S elmerengek majdnem reggelig...
Nekem ebben nagy kedvem telik.
De mikor hold, csillag nem ragyog,
Akkor én végkép odavagyok.
A tyukokkal el nem alhatom,
Hát galléron csíp az unalom,
S összenyaggat irgalmatlanúl...
Az időm fut, mint a sánta nyúl.
Véghetetlen kínom közepett
Mit tehetnék ekkor egyebet?
A tintába mártom tollamat,
Vagyis: megpendítem lantomat,
S kong belőle oly szeráfi dal,
Hogy, ki hallja, rögtön szörnyethal.
Én azonban folytatom dalom,
Míg az álom és az únalom
Egymással fölöttem hajbakap,
S csakugyan az első markosabb. -
Máskép mulnak éjeim bezeg,
Majd ha feleségre szert teszek.','Még ugy csak megjárja, ha az ég
Fellegetlen, holdas, tisztakék.
Ablakomra rákönyökölök,
Hosszú szárból sűrűn füstölök,','Pest, 1844. szeptember',1844,'1844',array['Természet']::text[],'{}'::text[],false,179,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-82','petofi','Furfangos borivó','Megiszom én a bort, mert szeretem,
De néha megy belém nagy nehezen;
Azonban rajtam nem fog ki soha,
Minden dolognak van oka-foka.

"A kancsó zsarnokszív" - azt gondolom -
"Ki kell belőle a vért ontanom!"
S e gondolatra kancsóm kiürűl,
Készítették bár feneketlenűl.','Megiszom én a bort, mert szeretem,
De néha megy belém nagy nehezen;
Azonban rajtam nem fog ki soha,
Minden dolognak van oka-foka.','Pest, 1844. szeptember',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,180,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-83','petofi','Takarékosság','Akármikép csűrjük, csavarjuk,
Szép, aki gazdálkodni tud;
Ilyennek aztán az adósság
Nem köt nyakába háborut;

Nem szurkol, ha bizonyos utcán
Világos nappal menni kell,
Hetykén tekinthet jobbra-balra,
Találkozzék akárkivel;

Nem mondja, amidőn javában
Cseng a kocsmában a pohár:
"Barátim, megbocsássatok, de
Mennem kell, otthon munka vár"...

S a többi! - - szóval, mátul fogva
Takarékos fiú leszek,
Minden garast úgy megbecsűlök,
Miként apám, a jó öreg.

Hej, csakhogy én az efféléket
Mindig pénz fogytán fogadom;
S amint pénzem jön: akkor ismét
Hegyen-völgyön lakodalom.','Akármikép csűrjük, csavarjuk,
Szép, aki gazdálkodni tud;
Ilyennek aztán az adósság
Nem köt nyakába háborut;','Pest, 1844. szeptember',1844,'1844',array['Természet']::text[],'{}'::text[],false,181,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-84','petofi','Pinty úrfi','Én nem panaszlok sorsom ellen,
Mi ördögért panaszlanék?
Lehet-e kegyesebb irántam,
Mint amilyen kegyes, az ég?
Nekem jutott a nagy szerencse:
Pinty úrfit énekelni meg!
Pinty úrfi a maga nemében
Hat puszta falu környékében
A legpáratlanabb gyerek.

Pinty úrfinak fillére sincsen,
Tán a nagyapjának se'' volt;
Amit telt erszénynek neveznek,
Távol van tőle, mint a hold.
Azért magát föl nem akasztja,
De még csak nem is kesereg.
Pinty úrfi a maga nemében
Hat puszta falu környékében
A legpáratlanabb gyerek.

Asztalt számára nem terítnek,
S ki hinné? éhen mégse'' vesz;
Ha enni kell, a vendéglőkbe
Bekullog ismerősihez,
S egy-egy falatka innen, onnan...
Böndőjét ekkép tölti meg.
Pinty úrfi a maga nemében
Hat puszta falu környékében
A legpáratlanabb gyerek.

Mikép teszen szert öltözetre?
Ez is igen eredeti:
Bál- és egyébre a ruhákat
Úgy kölcsön elkéregeti;
Csakhogy többé ezen ruhákat
Nem látják a jó emberek.
Pinty úrfi a maga nemében
Hat puszta falu környékében
A legpáratlanabb gyerek.

Hol a szállása? azt nem tudjuk;
De ő fennen dicsekszi el:
Milyen pompás szobái vannak!
És amit ő mond, hinni kell.
Bár kávéházakban gyakorta
Olyan Pintyféle szendereg:
Pinty úrfi a maga nemében
Hat puszta falu környékében
A legpáratlanabb gyerek.

És ilyen ő tetőtül talpig,
Tökéletes képmása ez;
Magának és kedves honának
Roppant becsűletet szerez.
Kiáltson föl hát minden ember:
Tartsák meg őt az istenek!
Pinty úrfi a maga nemében
Hat puszta falu környékében
A legpáratlanabb gyerek.','Én nem panaszlok sorsom ellen,
Mi ördögért panaszlanék?
Lehet-e kegyesebb irántam,
Mint amilyen kegyes, az ég?','Pest, 1844. szeptember',1844,'1844',array['Természet','Gyermekkor']::text[],'{}'::text[],false,182,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-85','petofi','Szemfájásomkor','Teremtő isten! szemeimre
A vakságot tán csak nem küldöd?
Mi lesz belőlem, hogyha többé
Nem láthatok lyányt s pipafüstöt!','Teremtő isten! szemeimre
A vakságot tán csak nem küldöd?
Mi lesz belőlem, hogyha többé
Nem láthatok lyányt s pipafüstöt!','Pest, 1844. szeptember',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,183,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-86','petofi','Ha','Ha kalapomnak szőre volna,
És jobbra-balra nem konyulna:
Én volnék a derék legény!
Arszlánnak is beilleném.

Ha már nem volna vagy két éve,
Hogy a mellényem meg van véve:
Én volnék a derék legény!
Arszlánnak is beilleném.

Ha volna több, mint egy kabátom,
Mit hordanom kell télen, nyáron:
Én volnék a derék legény!
Arszlánnak is beilleném.

Ha a nadrágom alja, térde
Nem volna oly nagyon megsértve:
Én volnék a derék legény!
Arszlánnak is beilleném.

Ha a csizmámnak talpa, sarka
Nem kérdené, hogy hol a varga?
Én volnék a derék legény!
Arszlánnak is beilleném.

Ha majd e ha, ha ha, ha meg ha
Elpusztul tőlem a pokolba:
Én leszek a derék legény,
Mindjárt arszlánnak illem én.','Ha kalapomnak szőre volna,
És jobbra-balra nem konyulna:
Én volnék a derék legény!
Arszlánnak is beilleném.','Pest, 1844. szeptember',1844,'1844',array['Természet']::text[],'{}'::text[],false,184,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-87','petofi','Szerelem vándorai','Kél a hold, az éj lovagja,
Hold kiséretében,
Mint hüséges apród, a kis
Esti csillag mégyen.

Indulóban vagyok én is,
S nem megyek magamban;
Holddal esti csillag, vélem
Égő szerelem van.

Csak eredj, hold, csak eredj a
Barna éjszakához;
Megyek én is, megyek én is
Barna kisleányhoz.','Kél a hold, az éj lovagja,
Hold kiséretében,
Mint hüséges apród, a kis
Esti csillag mégyen.','Pest, 1844. szeptember',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,185,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-88','petofi','Halálom','A halál két neme áll előttem,
Nem tudom, hogy melyiké leszek;
Nem tudom, pedig szeretném tudni:
Éhen vagy szomjan halok-e meg?','A halál két neme áll előttem,
Nem tudom, hogy melyiké leszek;
Nem tudom, pedig szeretném tudni:
Éhen vagy szomjan halok-e meg?','Pest, 1844. szeptember',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,186,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-89','petofi','Mi lelt?','Nem tudom, mi lelt ma engem?
Jókedvemben nincs határ;
Danolhatnék, fütyölhetnék,
Egyikhez sem értek bár.

Összeverem a bokámat,
Noha nem szól muzsika;
A szobám világos, ámbár
Nap nem süt belé soha.

Még a füst is rózsaszínű,
Melyet rosz cserép pipám
Legroszabb kapadohányból
Küld keresztül a szobán.

A szivem ver, mintha benne
Háborogna szerelem;
Pedig egy leány sem váltott
Csak egy jó szót is velem.

S annál megfoghatlanabb ez,
Mert zsebemnek zord egén
Pénzfogyatkozásnak éje
Űl sötéten, feketén.

Szóval: a világ előttem
Egy szép tulipánbokor...
Kár, hogy addig lesz csak az, mig
Kimegy fejemből a bor!','Nem tudom, mi lelt ma engem?
Jókedvemben nincs határ;
Danolhatnék, fütyölhetnék,
Egyikhez sem értek bár.','Pest, 1844. szeptember',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,187,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-90','petofi','Igyunk!','Akinek nincs szeretője,
Bort igyék,
S hinni fogja, hogy minden lyány
Érte ég.

És igyék bort az, akinek
Pénze nincs,
S az övé lesz a világon
Minden kincs.

És igyék bort az, akinek
Búja van,
S a bú tőle nyakrafőre
Elrohan.

Sem szeretőm, sem pénzem, csak
Bánatom;
Másnál háromszorta többet
Ihatom.','Akinek nincs szeretője,
Bort igyék,
S hinni fogja, hogy minden lyány
Érte ég.','Pest, 1844. szeptember',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,188,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-91','petofi','Dáridó után','Ez volt aztán az éjszaka!
Bort többé sose lássak,
Ha életemben párja volt
Ennek az áldomásnak.

Egész mohácsi ütközet
Ment végbe ott közöttünk;
Igaz, hogy a török a bor,
És a magyar mi lettünk.

Hanem még az is igaz ám,
Hogy harcoltunk vitézül,
Kivált mikor már a király,
Az ész, kidőlt nyergébül.

A győzelmes poharakat
Dühhel nyakon ragadtuk,
S függtünk letéphetetlenűl,
Mint a pióca, rajtuk.

Ha oly hosszú lesz életünk,
Mint kortyaink valának,
Megérjük boldogabb korát
A bús magyar hazának.','Ez volt aztán az éjszaka!
Bort többé sose lássak,
Ha életemben párja volt
Ennek az áldomásnak.','Pest, 1844. szeptember',1844,'1844',array['Haza']::text[],'{}'::text[],false,189,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-92','petofi','Verseim','A költészet fája életem,
Minden versem egy levelke rajt.
Fa, levél el fog hervadni majd,
A felejtés szele rásohajt.

És mivelhogy elhervadni fog,
Ne is ápolgassam én e fát?
Más hasznot ha nem hajt: legalább,
Amíg élek, hűs árnyékot ád.','A költészet fája életem,
Minden versem egy levelke rajt.
Fa, levél el fog hervadni majd,
A felejtés szele rásohajt.','Pest, 1844. szeptember',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,190,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-93','petofi','Színészdal','Minden müvészetek
Fején a korona:
A mi művészetünk,
Ellen ki mondana?
Mi szép, mi szép, mi szép
A mi föladatunk!
Legyünk büszkék reá,
Hogy színészek vagyunk.

Csak árny, amit teremt
A költőképzelet;
Mi adjuk meg neki
A lelket, életet.
Mi szép, mi szép, mi szép
A mi föladatunk!
Legyünk büszkék reá,
Hogy színészek vagyunk.

Miénk a hatalom
Az emberszív felett:
Idézni egyaránt
Mosolyt vagy könnyeket.
Mi szép, mi szép, mi szép
A mi föladatunk!
Legyünk büszkék reá,
Hogy színészek vagyunk.

Apostolok vagyunk
Az erkölcs mezején.
Apostoli szavunk
Téged kiált: erény!
Mi szép, mi szép, mi szép
A mi föladatunk!
Legyünk büszkék reá,
Hogy színészek vagyunk.

De amit színpadon
A népnek hirdetünk,
Ne hazudtolja meg
A cselekedetünk.
Ha meg nem tesszük azt,
Ami föladatunk:
Akkor gyalázat ránk,
Szinészek nem vagyunk!','Minden müvészetek
Fején a korona:
A mi művészetünk,
Ellen ki mondana?','Pest, 1844. szeptember',1844,'1844','{}'::text[],'{}'::text[],false,191,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-94','petofi','Levél egy színész barátomhoz','Jut még eszedbe a fiú? kivel
Együtt cepelted a vándorbotot,
Mely koldusbotnak is beillenék,
Midőn a sorsnak fényes kedve nincs;
És ez nem éppen olyan ritkaság
Szinészre nézve, mint boldogtalan
Magyar hazánkban a hű honfigond. -
Lásd, én reátok még emlékezem,
És elfeledni nem fogom soha
A jót s roszat, mely ott közöttetek
Mult napjaimnak osztályrésze volt.
Előttem áll a délután, midőn
A színészetbe béavattatám.
Barangolék föl és le céltalan
A nagy hazának minden tájain.
Tarisznyámban, mit hátamon vivék,
Nem mondhatom, hogy nagy volt a teher,
De a nyomor, mint ólom, megnyomott.
Könnyíte rajt a víg könnyelmüség,
Mely útaimban hű társam vala.
Ekkép juték egy nyári délután
Egy kis városba; fáradt lábaim
A fogadóban megpihentenek. -
Vendégszobája egyik oldalán
Helyet szerényen színpad foglala.
Mire való is már a fényüzés?...
Azon tünődtem épen: kérjek-e
Ebédet vagy se? hát ha majd sovány
Zsebem bicskája szépen benntörik?
Az ajtót ekkor megnyitá egy ur;
Volt bennem annyi emberismeret,
Ráfoghatnom, hogy nem más, mint szinész.
Fején kalapja nagybecsű vala,
Mert Elizéus prófétával az
Rokonságban volt... tudnillik: kopasz.
Kabátja új, a nadrág régi rongy,
És lábát csizma helytt cipő födé,
Alkalmasint amelyben szerepelt.
"Thalia papja?" kérdém. - "Az vagyok;
Talán ön is?" - "Még eddig nem." - "Tehát
Jövőben? fölség..." - "Azt sem mondhatom."
Vágtam szavába; ámde ő rohant,
S vezette gyorsan az igazgatót.
Fehér köpenyben az igazgató
Jött üdvezelni engem nyájasan:
"Isten hozá önt, tisztelt honfitárs!
Lesz hát szerencsénk önhöz, édes ur?
Imádja úgye a müvészetet?
Ah, jóbarátom, isteni is az!
S önnek szeméből olvasom ki, hogy
Szinészetünknek egykor hőse lesz,
És kürtölendik bámult nagy nevét
A két hazának minden ajkai...
Ebédelt már ön? itt az ételek
Fölötte drágák, s ami több: roszak.
Az ispán urtól őzcombot kapánk,
A káposztából is van maradék -
Ha meghivásom nem méltóztatik
Elútasítni: jó ebédje lesz."
Igy ostromolt a jó igazgató,
Forgatva nyelve könnyü kerekét.
Én nem rosz kedvvel engedék neki.
Menék ebédre, és ebéd után
Beiktatának ünnepélyesen
A társaságba - nem kutatva: mi
Valék, deák-e vagy csizmadia?
Másnap fölléptem a Peleskei
Notáriusban. Hősleg működém
Három szerepben, minthogy összesen
A társaságnak csak hat tagja volt. -
Egy ideig csak elvalék velök;
Faluzgatánk jó- s balszerencse közt.
De a barátság végre megszakadt,
Mert én utáltam a nyegléskedést,
A sok "utószor"-t, a görögtüzet,
S tudj'' a manó, mily csábitásokat.
A társaság is végre szétoszolt
Egymást érő bel- s külviszály miatt;
S én újra jártam széles e hazát,
Mignem keblébe vett más társaság.
Mit ottan, itt is azt tapasztalám,
S tapasztalásom nem volt olyatén,
Mely kedvre hozta volna lelkemet.
Kenyért keresni színészek leszünk,
Nem a művészet szent szerelmiből,
S haladni nincsen semmi ösztönünk.
"Pártolj, közönség, és majd haladunk,"
Mond a szinész: és az meg így felel:
"Haladjatok, majd aztán pártolunk;"
És végre mind a kettő elmarad.
Nem is hiszem, hogy a szinészetet
Becsülni fogják, míg ez befogad
Minden bitangot, gaz sehonnait,
Kik a világnak söpredékei,
S itten keresnek biztos menhelyet.
Barátom, ez fájt énnekem s neked,
Ez keseríte minket annyira.
Az isten adja, hogy minél előbb
Akképpen álljon szinmüvészetünk,
Amint valóban kéne állnia.','Jut még eszedbe a fiú? kivel
Együtt cepelted a vándorbotot,
Mely koldusbotnak is beillenék,
Midőn a sorsnak fényes kedve nincs;','Pest, 1844. szeptember',1844,'1844',array['Haza']::text[],'{}'::text[],false,192,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-95','petofi','A tintásüveg','Vándorszinész korában Megyeri
(Van-e, ki e nevet nem ismeri?)
Körmölgeté, mint más, a színlapot.
Kapott
Ezért
Egyszer vagy öt forintnyi bért,
Amint mondom, vagy öt forintnyi bért.

Először is hát tintáért megyen,
Ha ismét írni kell, hogy majd legyen.
A tintás üveget pedig hová
Dugá?
Bele
Kabátja hátsó zsebibe,
Amint mondom, kabátja zsebibe.

S hogy pénzre tett szert, lett Megyeri vig,
S hazafelé menvén, ugrándozik.
Hiába inti őt Szentpéteri:
"Kari,
Vigyázz!
Kedved majd követendi gyász,
Amint mondom, majd követendi gyász."

Úgy lett. A sok ugrándozás alatt
Kifolyt a tinta; foltja megmaradt.
Megyeri elbusúl - kedvét szegi
Neki
A folt,
Mivel csak egy kabátja volt,
Amint mondom, csak egy kabátja volt.

Mi több: kabátja éppen sárga volt,
És így annál jobban látszott a folt.
"Eldobnám - szólt - de mással nem birok;"
Ez ok
Miatt
Hordá, mig széjjel nem szakadt,
Amint mondom, mig széjjel nem szakadt.','Vándorszinész korában Megyeri
(Van-e, ki e nevet nem ismeri?)
Körmölgeté, mint más, a színlapot.
Kapott','Pest, 1844. szeptember',1844,'1844',array['Haza']::text[],'{}'::text[],false,193,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-96','petofi','A naphoz','Panaszom van kelmed ellen,
Hallja kelmed, nap uram!
Mi dolog az, sugarával
Bánni olyan fukaran?

Elballag kelmed fölöttem
Minden istenadta nap,
Kis szobám kelmedtől mégis
Egy sziporka fényt se kap.

Oly sötét van benne, mint a...
Majd kimondtam, hogy mibe''.
Legyen egy kis embersége,
S nézzen kelmed néha be.

Hiszen azt, hogy versirás a
Mesterségem, tudja tán,
Azt is tudja, ily esetben
Nem lehet pompás szobám;

Hogyne tudná, ''sz hajdanában
Kelmed szinte lantot vert,
Még mikor le nem rudalták
Az Olympról Jupitert.

Szánjon meg tehát kegyelmed
Kedves kollega uram,
S mátul fogva sugarával
Ne bánjék oly fukaran.','Panaszom van kelmed ellen,
Hallja kelmed, nap uram!
Mi dolog az, sugarával
Bánni olyan fukaran?','Pest, 1844. szeptember 27. után',1844,'1844',array['Természet']::text[],'{}'::text[],false,194,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-97','petofi','A nap házasélete','A nap házas legény,
Tudjátok?
Hanem szegény
Fején
Ez épen a nagy átok,
Mert a papucskormány terhét nyögi;
Rosz felesége annyi bút szerez neki.
Természetes hát, hogy a jó öreg
A bort nem veti meg.
A bort, mely minden bajnak orvoslója.
A bort, mely a szívből a bút kiszórja.
De otthon inni nem merészel,
Mert ekkor kész a pör a feleséggel.
Azonban tud magán segíteni.
Midőn az égen a szokott utat teszi:
Csak arra vár,
Hogy fellegekbe öltözzék a láthatár.
Ekkor nem félve,
Hogy őt meglátja felesége,
Bebaktat egy közeleső
Kocsmába,
S iszik, mint a kefekötő,
Bújába''! -
Ha jön az est,
S a felleg oszlani kezd,
Látjátok őtet, amint mámorosan
Piros pofával az égről lezuhan.','A nap házas legény,
Tudjátok?
Hanem szegény
Fején','Pest, 1844. október',1844,'1844',array['Természet']::text[],'{}'::text[],false,195,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-98','petofi','A leánykákhoz','Ne haragudjatok rám,
Leánykák, lelkeim!
Hogy oly sokszor beszélnek
A borról verseim.

Ti nem gondolhatjátok,
Mily bús az életem,
Hogy gyakran a keservek
Keservét szenvedem.

Mig olvassátok tőlem
A tréfás dalokat,
Nem sejtitek, hogy néha
Szivem majd megszakad.

S lássátok, szépeim! ha
A bú nekem rohan,
Mint felbőszült oroszlán,
Emésztőszilajan;

Ha a világ előttem
Éjjé sötétedik,
S a sötétséges éjben
Vihar kerekedik,

És a vihar szivemben
Dúl irgalmatlanúl:
Csak a bor, amitől ez
Ismét lecsillapúl.

Lecsillapúl lassanként,
Elzúg a fergeteg,
S én újolag vidám, kék
Eget szemlélhetek;

S a fölvidámult égen
A régi fényben jár
A jókedv holdja, a szép
Örömcsillagsugár.

Ily jótevő orvosság
A szőlőnedv nekem;
Nem egyszer menté meg már
Megúnt, bús életem.

Mert gyakran voltam úgy, hogy
Csak még egy pillanat...
S most pókháló födözné
Versíró tollamat,

Míg én magam fekünném
A sírban hidegen,
S a föld hideg porával
Vegyűlne tetemem - -

Ne haragudjatok hát,
Leánykák, lelkeim!
Hogy oly sokszor beszélnek
A borról verseim.','Ne haragudjatok rám,
Leánykák, lelkeim!
Hogy oly sokszor beszélnek
A borról verseim.','Pest, 1844. október',1844,'1844',array['Szerelem','Természet']::text[],'{}'::text[],false,196,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-99','petofi','Sovány ősz','Megköszönöm az ilyen őszt,
Alázatosan köszönöm!
Egész világ örűl, vigad,
Csak énnekem nincs örömöm.
Iszik boldog, boldogtalan,
Szüret van úton, útfelen,
És én isten kegyelmiből
A száraz kortyokat nyelem.

Búsan Budára kullogok,
Megállok a vár tetején;
Nagyszálnak borszülő hegye
Távolból kékellik felém.
Nagyszálnak borszülő hegye
Sok jó napot szerzett nekem;
Hanem mi haszna? hogyha most
A száraz kortyokat nyelem.

Mint holmi falusi biró,
Leteszem a két könyököm,
Remélve, hogy tán valahogy
Majd búmat versben kinyögöm.
Hiába minden fejtörés!
Nem boldogúl a vers velem,
Hogy is verselhetnék? midőn
A száraz kortyokat nyelem.

Nagy bosszusan, nagy álmosan
Az ágyba vágom magamat,
S hej a szüret! ezt mormogom
Fülig a takaró alatt.
És a szüretről álmodom
S a borról minden éjjelen;
Másnap megint, mint azelőtt,
A száraz kortyokat nyelem.

Csak menne már el a szüret,
Csak menne a pokolba már!
Hozná meg isten a telet,
Hideg házban huzzam ki bár.
Vagy meglövöm magam, vagy a
Duna leszen fekvőhelyem,
Ha a jövő szüretkor is
A száraz kortyokat nyelem.','Megköszönöm az ilyen őszt,
Alázatosan köszönöm!
Egész világ örűl, vigad,
Csak énnekem nincs örömöm.','Buda, 1844. október',1844,'1844',array['Természet','Ünnep']::text[],array['osz']::text[],false,197,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-100','petofi','Legenda','"Megint panasz, hát már megint panasz!
És akiről szól, mindig csak pap az.
Tart a panasz estétől hajnalig,
Az ember még csak nem is alhatik!"
Igy szólt az úristen nagy bosszusan.
"Már megtekintem, ott alant mi van."
Felkelt az ágyról, gyertyát gyujtatott,
Felöltözék és útra kelt legott.
Amint elérte volna a kaput,
Szent Péter mint a bunda úgy aludt:
Mert tennap egy új vendég érkezék,
S ily alkalomkor lakmát tart az ég,
Mivel mostanság úgy áll a világ,
Hogy új lakó a mennyben ritkaság.
Ilyenkor aztán Péter bácsinak
Kezében a kancsók jól forganak.
"Keljen már kend fel, Péter! hallja kend?"
Igy szólt az úr, amidőn odament,
Hosszan cibálván üstökét, fülét.
"Kelj föl, hogy a mennykő üssön beléd!"
Fölébredt végre s nyitja a kaput,
S az úr egy hulló csillagon lefut,
S a földre ép oda ereszkedett,
Ahonnan a panasz fölérkezett.
Egy ifjú ember mondá a panaszt;
S az isten ekkép szólitá meg azt,
S megszólitása hangzott nyájasan:
"Beszélj, no, mondd, mi a bajod, fiam?"
"Hej, jó atyám, de nagy az én bajom!
Kapaszkodjék csak föl az ablakon,
S kit ott a pap ágyában látni fog,
A menyecskének férje én vagyok."
Az úr nagy halkkal fölkapaszkodott,
S nagy istentelenséget láthatott:
Mert amint aztán leereszkedék,
Igen furcsán csóválá meg fejét,
Ily szavakban törvén ki sóhaja:
"Biz e, fiam, kuruc-historia!
Segítnék rajta édes-örömest;
De már késő, mert minden megesett.
Hanem vigasztalásul mondhatom,
Hogy e papot pokolba juttatom,
Bár eddig is már a pokol fele,
Sőt több felénél, pappal van tele."','"Megint panasz, hát már megint panasz!
És akiről szól, mindig csak pap az.
Tart a panasz estétől hajnalig,
Az ember még csak nem is alhatik!"','Pest, 1844. október 20-27. között',1844,'1844',array['Természet','Család']::text[],'{}'::text[],false,198,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-101','petofi','Védegyleti dal','Van-e szebb lánc a világon,
Mint mely minket összefűz?
Bűvös karikába gyüjte
Minket a szent honfitűz.

Sír volt keblünk, és halottja
Volt a hazaszeretet;
Nagyszerűen űljük e föl-
Támadási innepet!

Nemzetünk, e nagy folyó, mely
Mindig százfelé szakadt,
Egyesítve innepénél
A különvált ágakat.

Millió és millió száj
És egyetlen hang legyen,
Mely kiáltsa lelkesedve
A magasztos innepen:

"Elfogadjuk, bármi durva,
Amit a hon méhe szül;
Bármi lágy és bármi pompás,
Semmit, semmit e kivül!"

És ne szóljon áldozatról,
Lemondásról senki sem;
Kötelesség! mit az ember
Hon jólléteért teszen.

S a király a honnak atyja,
Mint valóban jó atyánk,
Karjait kiterjesztendi,
És az áldást mondja ránk.','Van-e szebb lánc a világon,
Mint mely minket összefűz?
Bűvös karikába gyüjte
Minket a szent honfitűz.','Pest, 1844. október-november',1844,'1844',array['Haza']::text[],'{}'::text[],false,199,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-102','petofi','Volnék bár...','Volnék bár sivatag bús szigete
A tenger közepének,
Hová ember, madár nem lépne be -
Csak tégedet ne ismernélek.

Volnék megdermedt jégsziklája bár
A messze föld végének,
Mit nem melenget lanyha napsugár -
Csak tégedet ne ismernélek.

Volnék bár a földöv homokja, hol
A nyári nap tüzének
Örök sugára égető pokol -
Csak tégedet ne ismernélek.

Volnék bár hallgató éjféleken
Átokvert kósza lélek,
Ki még koporsajában sem pihen -
Csak tégedet ne ismernélek.

Nem volna mérve oly nagy terhe rám
A kínnak, szenvedésnek,
Létem keresztjét jobban hordanám -
Csak tégedet ne ismernélek.

S mégis, mégis... nem volna életem,
Az örök üdvességnek
Magas helye sem tetszenék nekem,
Ha tégedet nem ismernélek.','Volnék bár sivatag bús szigete
A tenger közepének,
Hová ember, madár nem lépne be -
Csak tégedet ne ismernélek.','Pest, 1844. október-november',1844,'1844',array['Természet']::text[],'{}'::text[],false,200,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-103','petofi','Szivem, te árva rabmadár!...','Szivem, te árva rabmadár!
Kit szűk, szoros kalitka zár,
Légy csendesebben odabenn,
Ne hánykolódjál oly igen;
Ugy meg találod sérteni
Magad, hogy vér fog ömleni...
Vagy üsd meg magadat tehát,
Jőjön halálos seb reád:
Véreddel majd megírhatom
Szerelmem és hattyúdalom.','Szivem, te árva rabmadár!
Kit szűk, szoros kalitka zár,
Légy csendesebben odabenn,
Ne hánykolódjál oly igen;','Pest, 1844. október-november',1844,'1844',array['Természet']::text[],'{}'::text[],false,201,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-104','petofi','Csokonai','Egy kálomista pap s Csokonai
Egymásnak voltak jóbarátai.
Kilódul egyszer Debrecenből
S a jóbarát előtt megáll,
S: ihatnám, pajtás! így kiált föl
Csokonai Vitéz Mihály.

"No, ha ihatnál, hát majd ihatol,
Akad még bor számodra valahol,
Ha máshol nem, tehát pincémben;
Ottan nem egy hordó bor áll."
Szólott a pap, s leballag véle
Csokonai Vitéz Mihály.

"Ihol ni, uccu!" fölkiált a pap,
Amint egy hordóból dugaszt kikap;
"Szaladj csapért! ott fönn felejtém;
Szaladj öcsém, de meg ne állj!"
És fölrohan lóhalálában
Csokonai Vitéz Mihály.

A likra tette tenyerét a pap;
Csak vár, csak vár, hogy jön talán a csap.
S a csap nem jött, és a pap morgott:
"De mi az ördögöt csinál,
Hol a pokolba'' marad az a
Csokonai Vitéz Mihály?"

Tovább nem győzte várni a csapot,
Ott hagyta a hordót (a bor kifolyt),
Fölmén a pincéből a házba,
De ott fönn senkit nem talál.
Csak késő este érkezett meg
Csokonai Vitéz Mihály.

Hát a dologban ez volt az egész:
Kereste ott fönn a csapot Vitéz,
Zeget-zugot kikutat érte,
De csak nem jön rá, hogy hol áll?
És így csapért szomszédba mégyen
Csokonai Vitéz Mihály.

A szomszédban valami lakzi volt,
Elébe hoztak ételt és italt;
És ím az étel és bor mellett
És a zenének hanginál
Csapot, papot, mindent felejtett
Csokonai Vitéz Mihály.','Egy kálomista pap s Csokonai
Egymásnak voltak jóbarátai.
Kilódul egyszer Debrecenből
S a jóbarát előtt megáll,','Pest, 1844. november',1844,'1844',array['Természet']::text[],'{}'::text[],false,202,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-105','petofi','Batthyányi és Károly grófnék','Nekem nincs semmim, semmim e hazában,
De én egészen az övé vagyok;
Bánat- s örömkönny forr szememben, amint
Sötétül napja, avvagy fölragyog.

Örömkönyűim, oh ti gyér vendégek
Minálunk a hű honfiszem felett,
Ha föl nem törtök most a telt kebelből,
Édes terhétől szívem megreped.

- Láttátok-e a két tündérvirágot,
Borús hazánknak két sarkcsillagát?
Evezhetsz bátran, nemzetem hajója,
Nem veszthet az célt, aki ilyet lát.

Én láttam, láttam!... megmutatta őket
Szent vágyaimnak a szövétnekfény;
Hanem mi volt e fény a lánghoz képest,
Mely ekkor égett keblem belsején!

Ott álltak ők, mint égi jelenések.
Szokatlan köztünk ilyen látomány...
Hahogy sokáig néztem volna őket,
Szemfényemet vesztettem volna tán.

S hallottam édes ajkaik zenéjét,
Hallottam őket halkan mondani,
Mit tetteik rég fennszóval beszélnek,
Hogy ők a honnak hű leányai.

Miért nem voltam a lég ajkaiknál?
Hogy vittem volna szét e hangokat,
Mint napvilágot, mindenegy magyarhoz,
Kit éj környékez honfibú miatt.

Ragyogjatok ti ébredő hazámban
Hajnalsugárral, testvércsillagok!
Sugáritokra, Memnon szobraképen,
A nemzetáldás zengedezni fog.','Nekem nincs semmim, semmim e hazában,
De én egészen az övé vagyok;
Bánat- s örömkönny forr szememben, amint
Sötétül napja, avvagy fölragyog.','Pest, 1844. november 15. után',1844,'1844',array['Haza','Természet']::text[],'{}'::text[],false,203,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-106','petofi','Mért nem születtem ezer év előtt?','Mért nem születtem ezer év előtt?
Midőn születtek Árpád daliái,
S ragadva kardot, a vérkedvelőt,
A nagy világgal mentek szembeszállni.

Beh mondtam volna csataéneket,
Versenyt rivalgót kürtjével Lehelnek,
Melynek zugási mennydörgéseket
Vadúl kavargó örvényökbe nyeltek.

Beh fölvetettem volna magamat
Hadvész után nyerítő paripára,
Keresni a sírt vagy babéromat
Hazát teremtő harcok viharába''.

Beh énekeltem volna diadalt,
Vitézeimnek, párducbőrre dőlve,
Midőn az ütközetmoraj kihalt
S az áldomás csengése jött helyébe.

Vagyok henyélő század gyermeke,
Hol megdalolni méltó tárgyam nincsen;
S ha volna is, mi lenne sikere?
Sínlődik a nyelv terhes rabbilincsen.','Mért nem születtem ezer év előtt?
Midőn születtek Árpád daliái,
S ragadva kardot, a vérkedvelőt,
A nagy világgal mentek szembeszállni.','Pest, 1844. november',1844,'1844',array['Haza']::text[],'{}'::text[],false,204,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-107','petofi','Az én szerelmem...','Az én szerelmem nem a csalogány,
Kit fölkeltett a hajnalszürkület,
Hogy édes ének szóljon ajakán
A nap csókjától rózsás föld felett.

Az én szerelmem nem kies liget,
Hol csendes tóban hattyúk ringanak,
Fehér nyakok mig bókot integet
A vízbe néző hold sugárinak.

Az én szerelmem nem nyugalmas ház,
Mit kert gyanánt körűl a béke vett,
Hol a boldogság anyaként tanyáz,
S tündérleányt szűl: a szép örömet.

Az én szerelmem rengeteg vadon;
A féltés benne mint haramja áll,
Kezében tőr; kétségb''esés vagyon,
Minden döfése százszoros halál.','Az én szerelmem nem a csalogány,
Kit fölkeltett a hajnalszürkület,
Hogy édes ének szóljon ajakán
A nap csókjától rózsás föld felett.','Pest, 1844. november',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,205,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-108','petofi','Szemek, mindenható szemek!','Szemek, mindenható szemek!
Ne nézzetek, ne nézzetek
Reám oly hidegen, oly hidegen;
Megöltök, ez halál nekem.
Halál nekem!

Vagy, oh mindenható szemek!
Csak öljetek meg, öljetek;
Aztán mosolygjatok, mosolygjatok,
S én újolag föltámadok,
Föltámadok!','Szemek, mindenható szemek!
Ne nézzetek, ne nézzetek
Reám oly hidegen, oly hidegen;
Megöltök, ez halál nekem.','Pest, 1844. november',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,206,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-109','petofi','Szerelmem zúgó tenger...','Szerelmem zúgó tenger,
De most zugása nem ver
Órjási hánykódás közt földet és eget;
Elszenderűlt, miképen
A gyermek bölcsejében,
Ha hosszan jajgatott és hosszan könnyezett.

A síma habtükörben
Evez föl és le lelkem
Szelíd merengésnek hintázó csónakán;
Partjáról a jövőnek
Csattog felém lágy ének...
Te énekelsz, remény, te kedves csalogány!','Szerelmem zúgó tenger,
De most zugása nem ver
Órjási hánykódás közt földet és eget;
Elszenderűlt, miképen','Pest, 1844. november',1844,'1844',array['Szerelem','Természet']::text[],'{}'::text[],false,207,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-110','petofi','Élet, halál! Nekem már mindegy','Élet, halál... nekem már mindegy!
Ez a kétség irtóztató;
Igy nem mehet tovább, amint megy
És "aki mer, nyer" példaszó.

Hozzá megyek, hozzá kell mennem,
Előtte szívem fölnyitom,
Hadd lássa meg, mi kín van bennem,
S hogy azt mind érte hordozom.

S ha szenvedésem látni fogja,
S a halvány színt, melyben vagyok;
Talán meglágyul indulatja,
Talán majd szánakozni fog.

És hátha könyvéből szemének
E drága sort olvashatom:
Hisz én már téged rég kisérlek,
Van érted titkos bánatom.

És hátha csókja szent kulcsával
Nyitand számomra majd eget...
Vagy, mint őrültet, szolga által
Szobájából majd kilöket.','Élet, halál... nekem már mindegy!
Ez a kétség irtóztató;
Igy nem mehet tovább, amint megy
És "aki mer, nyer" példaszó.','Pest, 1844. november',1844,'1844',array['Elmúlás']::text[],'{}'::text[],false,208,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-111','petofi','A borhoz','Oh bor! te voltál eddig egy barátom;
De látom,
Hogy már kihalt tüzed, mely értem ége,
S frigyünknek vége, vége.

Ha eddig hozzád folyamodtam
Bús állapotban,
Keresztelő lett... a búbánatot
Vidámsággá kereszteléd.
Mért járulok hiába most eléd?
Varázserődet mért nem mutatod?

Fejem nehéz,
És reszket már e kéz,
Mely a teli
Pohárt ajkamhoz emeli;
Ezt befolyásod eszközölte,
De nem hatál be a kebelbe:
A lélek ép.
Nem részegűlhet semmifélekép.
A multnak fekete
Emlékezete
- Mint Dejaníraköntös - rajta van
Letéphetetlenűl, minduntalan.

Oh bor!
Ki annyiszor
Voltál bajomnak orvossága,
Légy most is az, bár utójára:
Feledtesd el velem a gúnymosolyt,
Mely lángszerelmem jégjutalma volt!','Oh bor! te voltál eddig egy barátom;
De látom,
Hogy már kihalt tüzed, mely értem ége,
S frigyünknek vége, vége.','Pest, 1844. november',1844,'1844',array['Szerelem']::text[],'{}'::text[],false,209,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-112','petofi','A külföld magyarjaihoz','Ti fekélyek a hazának testén,
Mit mondjak felőletek?
Hogyha volnék tűz: kiégetnélek,
Égetném rosz véretek.

Nem vagyok tűz, nincs emésztő lángom;
De van éles hangu szóm,
Mely reátok átkait kiáltja,
Átkait irtóztatón.

Annyi kincse van hát e hazának,
Hogy nem is fér benne meg?
Hiszen e hon, e boldogtalan hon
Oly szegény és oly beteg.

És ti rablók! amit orvosságra
Izzad kínnal e haza:
Elhordjátok idegen bálványtok,
A külföld oltárira.

E hazán, mely porban esd kenyérért.
Nem esik meg szívetek;
Míg ő vért sír, poharaitokba
Kinn ti a bort töltitek.

És csak akkor tértek vissza, már ha
Koldusbot van nálatok:
Kit koldussá tettetek, hogy tőle
Ismét koldulhassatok.

Amiként ti e szegény hazából
Magatok száműzitek:
Vesse úgy ki csontotokat a sír
S a mennyország lelketek!','Ti fekélyek a hazának testén,
Mit mondjak felőletek?
Hogyha volnék tűz: kiégetnélek,
Égetném rosz véretek.','Pest, 1844. november',1844,'1844',array['Haza']::text[],'{}'::text[],false,210,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184405-113','petofi','V. ferdinándhoz','Igaz-e, királyom,
Amit mondogatnak?
Nálad híre sincs a
Szabadakaratnak.

Megtennél te mindent
A magyar javára;
Csakhogy titkos önkény
Korlátokba zára.

S nemcsak közdolgokban
Vagy te korlátozva;
E gyalázatos kény
Elhat ten lakodba.

Ami örömednek
Volna kútforrása,
Elzárják előled,
Hogy szemed se lássa.

És kinek, kinek vagy
Ilyen szolgarabja?
Szolgádnak, királyom,
Ki sajátod lopja! -

Ha ez így van: sorsod
Szivemből sajnálom...
Ugy nézz a szemembe,
Jó öreg királyom.','Igaz-e, királyom,
Amit mondogatnak?
Nálad híre sincs a
Szabadakaratnak.','Pest, 1844. november',1844,'1844',array['Haza']::text[],'{}'::text[],false,211,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006'),
('petofi-1844-184406-114','petofi','János vitéz','1

Tüzesen süt le a nyári nap sugára
Az ég tetejéről a juhászbojtárra.
Fölösleges dolog sütnie oly nagyon,
A juhásznak úgyis nagy melege vagyon.

Szerelem tüze ég fiatal szivében,
Ugy legelteti a nyájt a faluvégen.
Faluvégen nyája mig szerte legelész,
Ő addig subáján a fűben heverész.

Tenger virág nyílik tarkán körülötte,
De ő a virágra szemét nem vetette;
Egy kőhajtásnyira foly tőle a patak,
Bámuló szemei odatapadtanak.

De nem ám a patak csillámló habjára,
Hanem a patakban egy szőke kislyányra,
A szőke kislyánynak karcsu termetére,
Szép hosszú hajára, gömbölyű keblére.

Kisleány szoknyája térdig föl van hajtva,
Mivelhogy ruhákat mos a fris patakba'';
Kilátszik a vízből két szép térdecskéje
Kukoricza Jancsi gyönyörűségére.

Mert a pázsit fölött heverésző juhász
Kukoricza Jancsi, ki is lehetne más?
Ki pedig a vízben a ruhát tisztázza,
Iluska az, Jancsi szivének gyöngyháza.

"Szivemnek gyöngyháza, lelkem Iluskája!"
Kukoricza Jancsi így szólott hozzája:
"Pillants ide, hiszen ezen a világon
Csak te vagy énnekem minden mulatságom.

Vesd reám sugarát kökényszemeidnek,
Gyere ki a vízből, hadd öleljelek meg;
Gyere ki a partra, csak egy pillanatra,
Rácsókolom lelkem piros ajakadra!"

"Tudod, Jancsi szivem, örömest kimennék,
Ha a mosással oly igen nem sietnék;
Sietek, mert máskép velem roszul bánnak,
Mostoha gyermeke vagyok én anyámnak."

Ezeket mondotta szőke szép Iluska,
S a ruhákat egyre nagy serényen mosta.
De a juhászbojtár fölkel subájáról,
Közelebb megy hozzá, s csalogatva így szól:

"Gyere ki, galambom! gyere ki, gerlicém!
A csókot, ölelést mindjárt elvégzem én;
Aztán a mostohád sincs itt a közelben,
Ne hagyd, hogy szeretőd halálra epedjen."

Kicsalta a leányt édes beszédével,
Átfogta derekát mind a két kezével,
Megcsókolta száját nem egyszer sem százszor,
Ki mindeneket tud: az tudja csak, hányszor.

2

Az idő aközben haladott sietve,
A patak habjain piroslott az este.
Dúlt-fúlt Iluskának gonosz mostohája;
Hol marad, hol lehet oly soká leánya?

A rosz vén mostoha ekkép gondolkodott;
Követték ezek a szók a gondolatot:
(S nem mondhatni, hogy jókedvvel ejtette ki.)
"Megnézem, mit csinál? ha henyél: jaj neki!"

Jaj neked Iluska, szegény árva kislyány!
Hátad mögött van már a dühös boszorkány;
Nagy szája megnyílik, tüdeje kitágul,
S ily módon riaszt föl szerelem álmábul:

"Becstelen teremtés! gyalázatos pára!
Ilyet mersz te tenni világnak csúfjára?
Lopod a napot és istentelenkedel...
Nézze meg az ember... hogy tüstént vigyen el -"

"Hanem most már elég, hallja-e kend, anyjuk?
Fogja be a száját, vagy majd betapasztjuk.
Ugy merje kend Ilust egy szóval bántani,
Hogy kihullanak még meglevő fogai."

Reszkető kedvese védelmezésére
Ekkép fakadt ki a nyáj bátor őrzője;
Azután haragos szemmel fenyegetve
Az elmondottakhoz e szavakat tette:

"Ha nem akarja, hogy felgyujtsam a házát,
Meg ne illesse kend ezt a szegény árvát.
Úgyis töri magát, dolgozik eleget,
És mégsem kap száraz kenyérnél egyebet.

Most eredj, Iluskám. Megvan még a nyelved,
Hogy elpanaszold, ha roszúl bánik veled. -
S kend ne akadjon fönn azon, mit más csinál,
Hisz kend sem volt jobb a deákné vásznánál."

Kukoricza Jancsi fölkapta subáját,
S sebes lépésekkel ment keresni nyáját,
Nagy megszeppenéssel most vette csak észre,
Hogy imitt-amott van egy-kettő belőle.

3

A nap akkor már a földet érintette,
Mikor Jancsi a nyájt félig összeszedte;
Nem tudja, hol lehet annak másik fele:
Tolvaj-e vagy farkas, ami elment vele?

Akárhová lett az, csakhogy már odavan;
Búsulás, keresés, minden haszontalan.
Most hát mihez fogjon? nekiszánva magát,
Hazafelé hajtja a megmaradt falkát.

"Majd lesz neked Jancsi... no hiszen lesz neked!"
Szomorún kullogva gondolta ezeket,
"Gazduramnak úgyis rosz a csillagzatja,
Hát még... de legyen meg isten akaratja."

Ezt gondolta, többet nem is gondolhatott;
Mert ekkor a nyájjal elérte a kaput.
Kapu előtt állt az indulatos gazda,
Szokás szerint a nyájt olvasni akarta.

"Sose olvassa biz azt kelmed, gazduram!
Mi tagadás benne? igen nagy híja van;
Szánom, bánom, de már nem tehetek róla,"
Kukoricza Jancsi e szavakat szólta.

Gazdája meg ezt a feleletet adta,
S megkapta bajszát, és egyet pödrött rajta:
"Ne bolondozz Jancsi, a tréfát nem értem;
Amíg jól van dolgod, föl ne gerjeszd mérgem."

Kisült, hogy korántsem tréfaság a beszéd,
Jancsi gazdájának majd elvette eszét;
Jancsi gazdája bőg, mint aki megbőszült:
"Vasvillát, vasvillát!... hadd szúrjam keresztül!

Jaj, a zsivány! jaj, az akasztani való!
Hogy ássa ki mind a két szemét a holló!...
Ezért tartottalak? ezért etettelek?
Sohase kerüld ki a hóhérkötelet.

Elpusztulj előlem, többé ne lássalak!"
Jancsi gazdájából így dőltek a szavak;
Fölkapott hirtelen egy petrencés rudat,
A petrencés rúddal Jancsi után szaladt.

Kukoricza Jancsi elfutott előle,
De koránsem azért, mintha talán félne,
Markos gyerek volt ő, husz legényen kitett,
Noha nem érte meg még husszor a telet.

Csak azért futott, mert világosan látta,
Hogy méltán haragszik oly nagyon gazdája;
S ha ütlegre kerül a dolog, azt verje,
Ki félig apja volt, ki őt fölnevelte?

Futott, míg a szuszból gazdája kifogyott;
Azután ballagott, megállt, meg ballagott
Jobbra is, balra is; s mindevvel mit akar?
Nem tudta, mert nagy volt fejében a zavar.

4

Mikorra a patak vize tükörré lett,
Melybe ezer csillag ragyogása nézett:
Jancsi Iluskáék kertje alatt vala;
Maga sem tudta, hogy mikép jutott oda.

Megállt, elővette kedves furulyáját,
Kezdte rajta fújni legbúsabb nótáját;
A harmat, mely ekkor ellepett fűt, bokort,
Tán a szánakozó csillagok könnye volt.

Iluska már aludt. A pitvar eleje
Volt nyár idejében rendes fekvőhelye.
Fekvőhelyéről a jól ismert nótára
Fölkelt, lesietett Jancsi látására.

Jancsinak látása nem esett kedvére,
Mert megijedt tőle, s ily szót csalt nyelvére:
"Jancsi lelkem, mi lelt? mért vagy oly halovány,
Mint az elfogyó hold bús őszi éjszakán?"

"Hej, Iluskám! hogyne volnék én halovány,
Mikor szép orcádat utószor látom tán..."
"Jancsikám, látásod ugyis megrémített;
Hagyd el az istenért az ilyen beszédet!"

"Utószor látlak én, szivem szép tavasza!
Utószor szólt itten furulyám panasza;
Utószor ölellek, utószor csókollak,
Örökre elmegyek, örökre itt hagylak!"

Most a boldogtalan mindent elbeszéle,
Ráborúlt zokogó kedvese keblére,
Ráborúlt, ölelte, de képpel elfordult:
Ne lássa a leány, hogy könnye kicsordult.

"Most hát, szép Iluskám! Most hát, édes rózsám!
Az isten áldjon meg, gondolj néha reám.
Ha látsz száraz kórót szélvésztől kergetve,
Bujdosó szeretőd jusson majd eszedbe."

"Most hát, Jancsi lelkem, eredj, ha menned kell!
A jóisten legyen minden lépéseddel.
Ha látsz tört virágot útközépre vetve,
Hervadó szeretőd jusson majd eszedbe."

Elváltak egymástól, mint ágtól a levél;
Mindkettejök szive lett puszta, hideg tél.
Könnyeit Iluska hullatta nagy számmal,
Jancsi letörölte inge bő ujjával.

Indult; nem nézte egy szemmel sem, hol az ut?
Neki úgyis mindegy volt, akárhova jut.
Fütyörésztek pásztorgyermekek mellette,
Kolompolt a gulya... ő észre sem vette.

A falu messzire volt már háta megett,
Nem látta lobogni a pásztortüzeket;
Mikor utójára megállt s visszanézett,
A torony bámult rá, mint sötét kisértet.

Ha ekkor mellette lett volna valaki,
Hallotta volna őt nagyot sóhajtani;
A levegőeget daruk hasították,
Magasan röpűltek, azok sem hallották.

Ballagott, ballagott a halk éjszakában,
Csak nehéz subája suhogott nyakában;
Ő ugyan subáját gondolta nehéznek,
Pedig a szive volt oly nehéz szegénynek.

5

Mikor a nap fölkelt, s a holdat elküldte,
A puszta, mint tenger, feküdt körülötte;
A nap fölkeltétől a nap enyésztéig
Egyenes rónaság nyujtózkodott végig.

Nem volt virág, nem volt fa, nem volt bokor ott,
A harmat apró gyér fűveken csillogott;
Oldalvást a napnak első sugarára
Fölpiroslott egy tó; környékezte káka.

A tónak szélénél a káka közepett
Egy hosszú nyakú gém eledelt keresett,
És a tó közepén gyors halászmadarak
Hosszú szárnyaikkal le s föl szállongtanak.

Jancsi csak ballagott sötét árnyékával
S elméjének sötét gondolkozásával;
Az egész pusztában széjjel sütött a nap,
De az ő szivében éjek éje maradt.

Mikor a nap elért az ég tetejére,
Eszébe jutott, hogy falatozni kéne,
Tennap ilyen tájban evett utójára,
Meg alig is bírta már lankadó lába.

Letelepűlt, elővette tarisznyáját,
Megette maradék kevés szalonnáját.
Nézte őt a kék ég, a fényes nap... alább
Ragyogó szemével a tündér délibáb.

A kis ebéd neki jóizűen esett,
Megszomjazott rá, a tóhoz közeledett,
Kalapjának belemártá karimáját,
Ekkép enyhitette égő szomjuságát.

A tónak partjáról nem távozott messze:
Az álom szemének pilláját ellepte;
Vakondokturásra bocsátotta fejét,
Hogy visszanyerhesse elfogyott erejét.

Az álom őt odavitte, ahonnan jött,
Iluskája pihent hű karjai között,
Mikor a kisleányt csókolni akarta,
Hatalmas mennydörgés álmát elzavarta.

Szétnézett a puszta hosszában, széltében;
Nagy égiháború volt keletkezőben.
Oly hamar támadott az égiháború,
Mily hamar Jancsinak sorsa lett szomorú.

A világ sötétbe öltözködött vala,
Szörnyen zengett az ég, hullt az istennyila;
Végtére megnyílt a felhők csatornája,
S a tó vize sűrű buborékot hánya.

Jó hosszú botjára Jancsi támaszkodott,
Lekonyította a karimás kalapot,
Nagyszőrű subáját meg kifordította,
Úgy tekintett bele a vad zivatarba.

De a vihar ami hamar keletkezett,
Oly hamar is hagyta el megint az eget.
Megindult a felhő könnyü szélnek szárnyán,
Ragyogott keleten a tarka szivárvány.

Subájáról Jancsi lerázta a vizet,
Miután lerázta, ujra utnak eredt.
Mikor a nap leszállt pihenni ágyába,
Kukoricza Jancsit még vitte két lába.

Vitte őt két lába erdő közepébe,
Sűrű zöld erdőnek sötét közepébe;
Ott őt köszöntötte holló károgása,
Mely épen egy esett vadnak szemét ásta.

Sem erdő, sem holló őt nem háborgatván,
Kukoricza Jancsi ment a maga utján;
Erdő közepében sötét ösvényére
Leküldte világát a hold sárga fénye.

6

Az idő járása éjfél lehetett már,
Mikor szemébe tünt egy pislogó sugár.
Amint közelebb ért, látta, hogy ez a fény
Ablakból világít az erdő legmélyén.

Jancsi e látványra ekkép okoskodék:
"Ez a világ aligha csárdában nem ég;
Bizonyára ugy lesz - hál'' a jóistennek!
Bemegyek az éjre, benne megpihenek."

Csalatkozott Jancsi, mert az nem volt csárda,
Hanem volt tizenkét zsiványnak tanyája.
Nem állott üresen a ház, a zsiványok
Mind a tizenketten odabenn valának.

Éjszaka, zsiványok, csákányok, pisztolyok...
Ha jól megfontoljuk, ez nem tréfadolog;
De az én Jancsimnak helyén állt a szíve,
Azért is közéjük nagy bátran belépe.

"Adjon az úristen szerencsés jó estét!"
Mondott nekik Jancsi ilyen megköszöntést;
Erre a zsiványok fegyverhez kapának,
Jancsinak rohantak, s szólt a kapitányok:

"Szerencsétlenségnek embere, ki vagy te?
Hogy lábadat mered tenni e küszöbre.
Vannak-e szüleid? van-e feleséged?
Akármid van, nem fog többé látni téged."

Jancsinak sem szíve nem vert sebesebben
E szókra, sem nem lett haloványabb színben;
A zsiványkapitány fenyegetésire
Meg nem ijedt hangon ily módon felele:

"Akinek életét van miért félteni,
Ha e tájt kerüli, nagyon bölcsen teszi.
Nekem nem kedves az élet, hát közétek,
Bárkik vagytok, egész bátorsággal lépek.

Azért, ha úgy tetszik, hagyjatok életben,
Hagyjatok ez éjjel itten megpihennem;
Ha nem akarjátok ezt: üssetek agyon,
Hitvány életemet védeni nem fogom."

Ezt mondta, nyugodtan a jövendőt várva,
A tizenkét zsivány csodálkozására.
A kapitány ilyen szókat váltott véle:
"Egyet mondok, öcsém, kettő lesz belőle;

Te derék legény vagy, azt a bátor szented!
Téged az isten is zsiványnak teremtett.
Éltedet megveted, a halált nem féled...
Te kellesz minekünk... kezet csapunk véled!

Rablás, fosztogatás, ölés nekünk tréfa,
E derék tréfának díja gazdag préda.
Ez a hordó ezüst, ez meg arany, látod?...
Nos hát elfogadod a cimboraságot?"

Furcsa dolgok jártak Jancsi elméjében,
S tettetett jókedvvel szólt ilyeténképen:
"Cimborátok vagyok, itt a kezem rája!
Rút életemnek ez a legszebb órája."

"No, hogy még szebb legyen," felelt a kapitány,
"Lássunk, embereim, az áldomás után;
Papok pincéjéből van jó borunk elég,
Nézzük meg a kancsók mélységes fenekét!"

S a kancsók mélységes fenekére néztek,
S lett eltemetése fejökben az észnek;
Maga volt csak Jancsi, ki mértéket tartott,
Kinálgatták, de ő aprókat kortyantott.

Álmot hozott a bor latrok pillájára...
Jancsinak sem kellett több, ő csak ezt várta.
Mikor a zsiványok jobbra, balra dőltek,
Jancsi a beszédet ilyformán kezdé meg:

"Jó éjszakát!... nem kelt föl titeket sem más,
Majd csak az itéletnapi trombitálás!
Élete gyertyáját soknak eloltátok,
Küldök én örökös éjszakát reátok.

Most a kincses kádhoz! Megtöltöm tarisznyám,
Hazaviszem neked, szerelmes Iluskám!
Cudar mostohádnak nem lész többé rabja,
Feleségül veszlek... isten is akarja.

Házat építtetek a falu közepén,
Ékes menyecskének odavezetlek én;
Ottan éldegélünk mi ketten boldogan,
Mint Ádám és Éva a paradicsomban...

Istenem teremtőm! mit beszélek én itt?
Zsiványoknak vigyem el átkozott pénzit?
Tán minden darabhoz vérfoltok ragadtak,
S én ilyen kincsekkel legyek boldog, gazdag?

Hozzájok sem nyúlok... azt én nem tehetem,
Nincs elromolva a lelkiisméretem. -
Édes szép Iluskám, csak viseld terhedet,
Bízd a jóistenre árva életedet!"

Mikor elvégezte Jancsi a beszédet,
Az égő gyertyával a házból kilépett,
Meggyujtá födelét mind a négy szögleten,
Elharapózott a mérges láng sebesen.

Egy láng lett a födél szempillantás alatt,
A láng piros nyelve az ég felé szaladt,
Feketévé vált a tisztakék égi bolt,
Elhaloványodott a teljes fényü hold.

A szokatlan világ amint elterjedett,
Fölriasztotta a baglyot, bőregeret;
Kiterjesztett szárnyok sebes suhogása
A falombozatok nyugalmát fölrázta.

A föltámadó nap legelső sugára
Lesütött a háznak füstölgő romjára,
Pusztult ablakán át benézett a házba,
Ott a haramjáknak csontvázait látta.

7

Jancsi már hetedhét országon túl jára,
Nem is igen gondolt a zsiványtanyára;
Egyszerre valami csillámlott előtte,
Hát sugarát a nap fegyverekre lőtte.

Katonák jövének, gyönyörű huszárok,
A nap fénye ezek fegyverén csillámlott;
Alattok a lovak tomboltak, prüsszögtek,
Kényesen rázták szép sörényes fejöket.

Mikor őket Jancsi közeledni látta,
Alig fért meg szíve a baloldalába'',
Mert így gondolkodott: "Ha befogadnának,
Be örömest mennék én is katonának!"

Amint a katonák közelébe értek,
Ily szavát hallotta Jancsi a vezérnek:
"Vigyázz, földi! bizony rálépsz a fejedre...
Mi ördögért vagy úgy a búnak eredve?"

Jancsi pedig szólott fohászkodva nagyot:
"Én a kerek világ bujdosója vagyok;
Ha kegyelmetekkel egy sorban lehetnék,
A ragyogó nappal farkasszemet néznék."

Szólt megint a vezér: "Jól meggondold, földi!
Nem mulatni megyünk, megyünk öldökölni.
Rárontott a török a francia népre;
Franciáknak megyünk mi segedelmére."

"Hát hisz akkor én meg még jobban szeretném,
Ha magamat lóra, nyeregbe vethetném;
Mert ha én nem ölök, engem öl meg a bú -
Nagyon kivánt dolog nekem a háború.

Igaz, hogy eddig csak szamarat ismértem,
Mivelhogy juhászság volt a mesterségem.
De magyar vagyok, s a magyar lóra termett,
Magyarnak teremt az isten lovat, nyerget."

Sokat mondott Jancsi megeredt nyelvével,
De még többet mondott sugárzó szemével;
Nagyon természetes hát, hogy a vezérnek
Megtetszett, és be is vette közlegénynek.

Cifra beszéd kéne azt elősorolni,
A vörös nadrágban mit érezett Jancsi,
Mit érezett, mikor a mentét fölkapta,
S villogó kardját a napnak megmutatta.

Csillagokat rúgott szilaj paripája,
Mikor Jancsi magát fölvetette rája,
De ő keményen űlt rajta, mint a cövek,
A földindulás sem rázhatta volna meg.

Bámulói lettek katonapajtási,
Nem győzték szépségét, erejét csodálni,
És amerre mentek, s beszállásozának,
Induláskor gyakran sírtak a leányok.

Lyányokra nézve ami Jancsit illeti,
Egyetlenegy leány sem tetszett őneki,
Az igaz, hogy noha sok földet bejára,
Sehol sem akadt ő Iluska párjára.

8

Nos hát ment a sereg, csak ment, csak mendegélt,
Tatárországnak már elérte közepét;
De itten reája nagy veszedelem várt:
Látott érkezni sok kutyafejű tatárt.

Kutyafejű tatár népek fejedelme
A magyar sereget ekkép idvezelte:
"Hogy mikép mertek ti szembeszállni vélünk?
Tudjátok-e, hogy mi emberhússal élünk?"

Nagy volt ijedsége szegény magyaroknak,
Minthogy a tatárok ezerannyin voltak;
Jó, hogy akkor azon a vidéken jára
Szerecsenországnak jószívű királya.

Ez a magyaroknak mindjárt pártját fogta,
Mert Magyarországot egyszer beutazta,
S ekkor Magyarország jámborlelkü népe
Igen becsületes módon bánt ővéle.

El sem feledte ezt a szerecsen király:
Azért a magyarok védelmére kiáll,
S a tatár császárral, kivel jóbarát volt,
Kiengesztelésűl ily szavakat váltott:

"Kedves jóbarátom, ne bántsd e sereget,
Legkisebbet sem fog ez ártani neked,
Igen jól ismerem én a magyar népet,
Kedvemért bocsásd át országodon őket."

"A kedvedért, pajtás, hát csak már megteszem."
Szólt kibékülve a tatár fejedelem,
De még meg is írta az úti levelet,
Hogy senki se bántsa a magyar sereget.

Az igaz, hogy nem is lett semmi bántása,
De mégis örűlt, hogy elért a határra,
Hogyne örűlt volna? ez a szegény vidék
Egyebet se'' terem: medvehúst meg fügét.

9

Tatárország hegyes-völgyes tartománya
Messziről nézett a seregnek utána,
Mert jól bent vala már nagy Taljánországban,
Rozmarínfa-erdők sötét árnyékában.

Itt semmi különös nem történt népünkkel,
Csakhogy küszködnie kellett a hideggel,
Mert Taljánországban örökös tél vagyon;
Mentek katonáink csupa havon, fagyon.

No de a magyarság erős természete,
Bármi nagy hideg volt, megbirkozott vele;
Aztán meg, ha fáztak, hát kapták magokat,
Leszálltak s hátokra vették a lovokat.

10

Ekképen jutottak át Lengyelországba,
Lengyelek földéről pedig Indiába;
Franciaország és India határos,
De köztük az út nem nagyon mulatságos.

India közepén még csak dombok vannak,
De aztán a dombok mindig magasabbak,
S mikor a két ország határát elérik,
Már akkor a hegyek fölnyúlnak az égig.

Tudni való, hogy itt a sereg izzadott,
Le is hányt magáról dolmányt, nyakravalót...
Hogyne az istenért? a nap fejök felett
Valami egy óra-járásra lehetett.

Enni nem ettek mást, mint levegőeget;
Ez olyan sürü ott, hogy harapni lehet.
Hanem még italhoz is furcsán jutottak:
Ha szomjaztak, vizet felhőből facsartak.

Elérték végtére tetejét a hegynek;
Itt már oly meleg volt, hogy csak éjjel mentek.
Lassacskán mehettek; nagy akadály volt ott:
Hát a csillagokban a ló meg-megbotlott.

Amint ballagtak a csillagok közepett,
Kukoricza Jancsi ekkép elmélkedett:
"Azt mondják, ahányszor egy csillag leszalad,
A földön egy ember élete megszakad.

Ezer a szerencséd, te gonosz mostoha,
Hogy nem tudom, melyik kinek a csillaga;
Nem kínzanád tovább az én galambomat -
Mert lehajítanám mostan csillagodat."

Eztán nemsokára lejtősen haladtak,
Alacsonyodtak már a hegyek alattok,
A szörnyű forróság szinte szűnni kezdett,
Mentül beljebb érték a francia földet.

11

A franciák földje gyönyörű tartomány,
Egész paradicsom, egész kis Kánaán,
Azért is vásott rá a törökök foga,
Pusztitó szándékkal azért törtek oda.

Mikor a magyarság beért az országba,
A törökök ott már raboltak javába'';
Kirabolták a sok gazdag templom kincsét,
És üresen hagytak minden borospincét.

Látni lehetett sok égő város lángját,
Kivel szemközt jöttek, azt kardjokra hányták,
Magát a királyt is kiűzték várából,
S megfosztották kedves egyetlen lyányától.

Így találta népünk a francia királyt,
Széles országában föl s le bujdosva járt;
Amint őt meglátták a magyar huszárok,
Sorsán szánakozó könnyet hullatának.

A bujdosó király ily szókat hallatott:
"Ugye, barátim, hogy keserves állapot?
Kincsem vetélkedett Dárius kincsével,
S most küszködnöm kell a legnagyobb ínséggel."

A vezér azt mondá vigasztalására:
"Ne busúlj, franciák fölséges királya!
Megtáncoltatjuk mi ezt a gonosz népet,
Ki ily méltatlanul mert bánni tevéled.

Ez éjjelen által kipihenjük magunk,
Mert hosszu volt az út, kissé elfáradtunk;
De holnap azután, mihelyt fölkel a nap,
Visszafoglaljuk mi vesztett országodat."

"Hát szegény leányom, hát édes leányom?"
Jajdult föl a király, "őtet hol találom?
Elrabolta tőlem törökök vezére...
Aki visszahozza, számolhat kezére."

Nagy buzditás volt ez a magyar seregnek;
Minden ember szivét reménység szállta meg.
Ez volt mindenkinek fejében föltéve:
"Vagy visszakerítem, vagy meghalok érte."

Kukoricza Jancsi tán egymaga volt csak
Meg nem hallója az elmondott dolognak;
Jancsinak az esze más egyeben jára:
Visszaemlékezett szép Iluskájára.

12

Másnap reggel a nap szokás szerint fölkelt,
De nem lát és nem hall olyat minden reggel,
Mint amilyet hallott, mint amilyet látott
Mindjárt, mihelyest a föld szélére hágott.

Megszólalt a sereg harsány trombitája,
Minden legény talpon termett szózatára;
Jól kiköszörülték acél szablyáikat,
Azután nyergelték gyorsan a lovakat.

A király erőnek erejével rajt volt,
Hogy ő is elmegy, s a többiekkel harcol;
Hanem a huszárok bölcseszű vezére
A királyhoz ilyen tanácsot intéze:

"Nem, kegyelmes király! csak maradj te hátra,
A te karjaid már gyöngék a csatára;
Tudom, meghagyta az idő bátorságod,
De mi haszna? hogyha erőd vele szállott.

Bízd az isten után mireánk ügyedet;
Fogadást teszünk, hogy mire a nap lemegy:
Országodból tovaűzzük ellenséged,
S elfoglalhatd ujra a királyi széket."

Erre a magyarság lóra kerekedett,
S keresni indult a rabló törököket;
Nem soká kereste, mindjárt rájok akadt,
És egy követ által izent nekik hadat.

Visszajött a követ, harsog a trombita,
Rémséges zugással kezdődik a csata;
Acélok csengése, torkok kurjantása
Volt a magyaroknál harci jel adása.

A sarkantyút vágták lovak oldalába,
Dobogott a földön lovak patkós lába,
Vagy talán a földnek dobbant meg a szíve,
E vészt jövendölő zajra megijedve.

Törökök vezére hétlófarkú basa,
Ötakós hordónak elég volna hasa;
A sok boritaltól piroslik az orra,
Azt hinné az ember, hogy érett uborka.

A török csapatnak nagyhasu vezére
Rendbe szedte népét a harcnak jelére;
A rendbeszedett nép ugyancsak megállott,
Amint megrohanták a magyar huszárok.

De nem volt gyerekség ez a megrohanás,
Lett is nemsokára szörnyü rendzavarás;
Izzadott a török véres verítéket,
Tőle a zöld mező vörös tengerré lett.

Hej csinálom-adta! meleg egy nap volt ez,
Heggyé emelkedett már a török holttest.
De a basa még él mennykő nagy hasával,
S Kukoricza Jancsit célozza vasával.

Kukoricza Jancsi nem veszi tréfának,
S ily szóval megy neki a török basának:
"Atyafi! te úgyis sok vagy egy legénynek;
Megállj, én majd kettőt csinálok belőled."

S akként cselekedett, amint megfogadta,
Szegény török basát kettéhasította,
Jobbra-balra hullott izzadó lováról,
Igy múlt ki őkelme ebből a világból.

Mikor ezt látta a gyáva török sereg,
Uccu! hátat fordít és futásnak ered,
Futott, futott s talán mostanság is futna,
Hogyha a huszárok el nem érték volna.

De bezzeg elérték, le is kaszabolták;
Hullottak a fejek előttök, mint a mák.
Egyetlenegy nyargal még lóhalálába'',
Ennek Kukoricza Jancsi ment nyomába.

Hát a török basa fia vágtatott ott,
Ölében valami fehérféle látszott.
A fehérség volt a francia királylyány;
Nem tudott magáról semmit, elájulván.

Soká nyargalt Jancsi, amíg utolérte,
"Megállj, a hitedet!" kiáltott feléje,
"Állj meg, vagy testeden mindjárt nyitok kaput,
Melyen által hitvány lelked pokolba fut."

De a basa fia meg nem állott volna,
Ha a ló alatta össze nem omolna.
Összeomlott, ki is fújta ott páráját.
Basa fia ilyen szóra nyitá száját:

''Kegyelem, kegyelem, nemeslelkű vitéz!
Ha semmi másra nem: ifjuságomra nézz;
Ifjú vagyok még, az életet szeretem...
Vedd el mindenemet, csak hagyd meg életem!''

"Tartsd meg mindenedet, gyáva élhetetlen!
Kezem által halni vagy te érdemetlen.
Hordd el magad innen, vidd hírűl hazádnak,
Haramja fiai hogy és mikép jártak."

Leszállott lováról, királylyányhoz lépe,
És beletekintett gyönyörű szemébe,
Melyet a királylyány épen most nyita ki,
Mialatt ily szókat mondának ajaki:

"Kedves szabadítóm! nem kérdezem, ki vagy?
Csak annyit mondok, hogy hálám irántad nagy.
Háladatosságból én mindent megteszek,
Hogyha kedved tartja, feleséged leszek."

Jancsi ereiben nem folyt víz vér helyett,
Szivében hatalmas tusa keletkezett;
De lecsillapítá szíve nagy tusáját,
Emlékezetébe hozván Iluskáját.

Nyájasdadon így szólt a szép királylyányhoz:
"Menjünk, rózsám, elébb az édesatyádhoz.
Ott majd közelebbről vizsgáljuk a dolgot."
S ló előtt a lyánnyal lassacskán ballagott.

13

Kukoricza Jancsi meg a királyleány
Csatahelyre értek a nap alkonyatán.
A leáldozó nap utósó sugára
Vörös szemmel nézett a siralmas tájra.

Nem látott egyebet, csak a véres halált,
S hollósereget, mely a halottakra szállt;
Nem igen telt benne nagy gyönyörüsége,
Le is ereszkedett tenger mélységébe.

A csatahely mellett volt egy jókora tó,
Tiszta szőke vizet magába foglaló.
De piros volt az most, mert a magyar sereg
Török vértől magát vizében mosta meg.

Miután megmosdott az egész legénység,
A francia királyt várába kisérték;
A csatamezőtől az nem messzire állt...
Idekisérték hát a francia királyt.

Alighogy bevonult a várba a sereg,
Kukoricza Jancsi szinte megérkezett.
Olyan volt mellette az ékes királylyány,
Mint felhő mellett a tündöklő szivárvány.

Hogy az öreg király leányát meglátta,
Reszkető örömmel borult a nyakába,
S csak azután mondta a következőket,
Mikor a lyány ajkán tőle sok csók égett:

"Most már örömemnek nincsen semmi híja;
Szaladjon valaki, s a szakácsot híja,
Készítsen, ami jó, mindent vacsorára,
Az én győzedelmes vitézim számára."

"Király uram! nem kell híni a szakácsot,"
A király mellett egy hang ekkép rikácsolt,
"Elkészítettem már mindent hamarjában,
Föl is van tálalva a szomszéd szobában."

A szakács szavai kedvesen hangzottak
Füleiben a jó magyar huszároknak;
Nem igen sokáig hívatták magokat,
Körülülték a megterhelt asztalokat.

Amily kegyetlenűl bántak a törökkel,
Csak ugy bántak ők most a jó ételekkel;
Nem is csoda biz az, mert megéhezének
A nagy öldöklésben a derék vitézek.

Járta már a kancsó isten igazába'',
Ekkor a királynak ily szó jött szájába:
"Figyelmezzetek rám, ti nemes vitézek,
Mert nagy fontosságu, amit majd beszélek."

S a magyar huszárok mind figyelmezének,
Fölfogni értelmét király beszédének,
Aki egyet ivott, azután köhhentett,
S végre ily szavakkal törte meg a csendet:

"Mindenekelőtt is mondd meg a nevedet,
Bátor vitéz, aki lyányom megmentetted."
"Kukoricza Jancsi becsületes nevem:
Egy kicsit parasztos, de én nem szégyenlem."

Kukoricza Jancsi ekképen felele,
Azután a király ily szót váltott vele:
"Én a te nevedet másnak keresztelem,
Mától fogva neved János vitéz legyen.

Derék János vitéz, halld most beszédemet:
Minthogy megmentetted kedves gyermekemet,
Vedd el feleségül, legyen ő a tied,
És vele foglald el királyi székemet.

A királyi széken én sokáig ültem,
Rajta megvénültem, rajta megőszültem.
Nehezek nekem már a királyi gondok,
Annakokáért én azokról lemondok.

Homlokodra teszem a fényes koronát,
Fényes koronámért nem is kívánok mást,
Csak hogy e várban egy szobát rendelj nékem,
Melyben hátralevő napjaimat éljem."

A király szavai ím ezek valának,
Nagy csodálkozással hallák a huszárok.
János vitéz pedig e szíves beszédet
Alázatos hangon ekkép köszöné meg:

"Köszönöm szépen a kelmed jó''karatját,
Amely reám nézve nem érdemlett jóság;
Egyszersmind azt is ki kell nyilatkoztatnom,
Hogy én e jóságot el nem fogadhatom.

Hosszú históriát kéne elbeszélnem,
Miért e jósággal lehetetlen élnem;
De attól tartok, hogy megunnák kelmetek;
S én másnak terhére lenni nem szeretek."

"De csak beszélj, fiam, meghallgatjuk biz azt;
Hiábavalóság, ami téged aggaszt."
Igy biztatta őt a jó francia király,
S János vitéz beszélt, amint itt írva áll:

14

"Hogy is kezdjem csak hát?... Mindennek előtte
Hogyan tettem szert a Kukoricza névre?
Kukorica között találtak engemet,
Ugy ruházták rám a Kukoricza nevet.

Egy gazdaember jólelkü felesége
- Amint ő nekem ezt sokszor elmesélte -
Egyszer kinézett a kukoricaföldre,
S ott egy barázdában lelt engem heverve.

Szörnyen sikítottam, sorsomat megszánta,
Nem hagyott a földön, felvett a karjára,
És hazafelé ezt gondolta mentiben:
"Fölnevelem szegényt, hisz ugy sincs gyermekem."

Hanem volt ám neki haragos vad férje,
Akinek én sehogy sem voltam ínyére.
Hej, amikor engem az otthon meglátott,
Ugyancsak járták a cifra káromlások.

Engesztelte a jó asszony ily szavakkal:
"Hagyjon kend föl, apjok, azzal a haraggal.
Hiszen ott kinn csak nem hagyhattam vesztére,
Tarthatnék-e számot isten kegyelmére?

Aztán nem lesz ez a háznál haszontalan,
Kednek gazdasága, ökre és juha van,
Ha felcsuporodik a kis istenadta,
Nem kell kednek bérest, juhászt fogadnia."

Valahogy, valahogy csakugyan engedett;
De azért rám soha jó szemet nem vetett.
Hogyha nem ment dolgom a maga rendiben,
Meg-meghusángolt ő amugy istenesen.

Munka s ütleg között ekkép nevelkedtem,
Részesűltem nagyon kevés örömekben;
Az egész örömem csak annyiból állott,
Hogy a faluban egy szép kis szőke lyány volt.

Ennek édesanyja jókor a síré lett,
Édesapja pedig vett más feleséget;
Hanem az apja is elhalt nemsokára,
Így jutott egyedűl mostohaanyjára.

Ez a kis leányzó volt az én örömem,
Az egyetlen rózsa tüskés életemen.
Be tudtam is őtet szeretni, csodálni!
Ugy hítak minket, hogy: a falu árvái.

Már gyerekkoromban hogyha őt láthattam,
Egy turós lepényért látását nem adtam;
Örültem is, mikor a vasárnap eljött,
És vele játszhattam a gyerekek között.

Hát mikor még aztán sihederré lettem,
S izegni-mozogni elkezdett a szivem!
Csak úgyis voltam ám, mikor megcsókoltam,
Hogy a világ összedőlhetett miattam.

Sokszor megbántotta gonosz mostohája...
Isten neki soha azt meg ne bocsássa!
És ki tudja, még mit el nem követ rajta,
Ha fenyegetésem zabolán nem tartja.

Magamnak is ugyan kutyául lett dolga,
Belefektettük a jó asszonyt a sírba,
Aki engem talált, és aki, mondhatom,
Mint tulajdon anyám, úgy viselte gondom.

Kemény az én szívem, teljes életemben
Nem sokszor esett meg, hogy könnyet ejtettem,
De nevelőanyám sírjának halmára
Hullottak könnyeim zápornak módjára.

Iluska is, az a szép kis szőke leány,
Nem tettetett bútól fakadt sírva halmán;
Hogyne? az istenben boldogúlt jó lélek
Kedvezett, amiben lehetett, szegénynek.

Nem egyszer mondta, hogy: "várakozzatok csak!
Én még benneteket összeházasítlak;
Olyan pár válik is ám tibelőletek,
Hogy még!... várjatok csak, várjatok, gyerekek!"

Hát hiszen vártunk is egyre keservesen;
Meg is tette volna, hiszem az egy istent,
(Mert szavának állott ő minden időbe'')
Ha le nem szállt volna a föld mélységébe.

Azután hát aztán, hogy meghalálozott,
A mi reménységünk végkép megszakadott:
Mindazonáltal a reménytelenségbe''
Ugy szerettük egymást, mint annakelőtte.

De az úristennek más volt akaratja,
Szívünknek ezt a bús örömet sem hagyta.
Egyszer én valahogy nyájam elszalasztám,
Annak következtén elcsapott a gazdám.

Búcsut mondtam az én édes Iluskámnak,
Keserű érzéssel mentem a világnak.
Bujdosva jártam a világot széltére,
Mígnem katonának csaptam föl végtére.

Nem mondtam én neki, az én Iluskámnak,
Hogy ne adja szivét soha senki másnak,
Ő sem mondta nekem, hogy hűséges legyek -
Tudtuk, hogy hűségünk ugysem szegjük mi meg.

Azért szép királylyány ne tarts reám számot;
Mert ha nem bírhatom kedves Iluskámat:
Nem is fogok bírni senkit e világon,
Ha elfelejtkezik is rólam halálom."','1
Tüzesen süt le a nyári nap sugára
Az ég tetejéről a juhászbojtárra.
Fölösleges dolog sütnie oly nagyon,','',1844,'1844',array['Természet','Szerelem','Haza']::text[],array['tel']::text[],false,212,'Petőfi Sándor összes költeményei, Szépirodalmi Könyvkiadó, 1974 · MEK-01006')
